window.PK=window.PK||{};window.PK.peptides=[{"slug":"bpc-157","name":"BPC-157","synonyme":["Compuesto de Protección Corporal 157","PL 14736"],"kategorie":"Regeneration","studienlage":"frühe klinische Studien","kurz":"Un péptido sintético estudiado principalmente en modelos preclínicos de regeneración de tejidos.","kurz_en":"Un péptido sintético estudiado principalmente en modelos preclínicos de regeneración de tejidos.","beschreibung":"BPC-157 es un pentadecapeptido sintético cuya secuencia se deriva de una proteína protectora encontrada en el jugo gástrico humano. Está entre los péptidos más estudiados en la investigación de regeneración de tejidos, con una base amplia de estudios en animales y un número limitado de estudios humanos pequeños. Las áreas de enfoque de la investigación incluyen tendones, ligamentos, el revestimiento gastrointestinal y la cicatrización de heridas.","beschreibung_en":"BPC-157 es un pentadecapeptido sintético cuya secuencia se deriva de una proteína protectora encontrada en el jugo gástrico humano. Está entre los péptidos más estudiados en la investigación de regeneración de tejidos, con una base amplia de estudios en animales y un número limitado de estudios humanos pequeños. Las áreas de enfoque de la investigación incluyen tendones, ligamentos, el revestimiento gastrointestinal y la cicatrización de heridas.","mechanismus":"En modelos preclínicos, se ha descrito que el BPC-157 está involucrado en la angiogénesis a través de la vía VEGFR2-AKT-eNOS, apoyando la formación de nuevos vasos sanguíneos en tejido lesionado. Otros mecanismos estudiados incluyen la regulación al alza de los receptores de hormona del crecimiento, la modulación de citoquinas inflamatorias y el apoyo a la migración celular a través de la vía FAK-paxilina. Los mecanismos exactos en humanos aún no están completamente establecidos.","mechanismus_en":"En modelos preclínicos, se ha descrito que el BPC-157 está involucrado en la angiogénesis a través de la vía VEGFR2-AKT-eNOS, apoyando la formación de nuevos vasos sanguíneos en tejido lesionado. Otros mecanismos estudiados incluyen la regulación al alza de los receptores de hormona del crecimiento, la modulación de citoquinas inflamatorias y el apoyo a la migración celular a través de la vía FAK-paxilina. Los mecanismos exactos en humanos aún no están completamente establecidos.","evidenz":[{"art":"preclínico","kurz":"Una revisión sistemática de 2025 evaluó la literatura de 1993 a 2024 e incluyó 35 estudios preclínicos en animales sobre lesiones musculares, tendinosas, ligamentarias y óseas, que describieron en su mayoría resultados positivos de curación.","kurz_en":"Una revisión sistemática de 2025 evaluó la literatura de 1993 a 2024 e incluyó 35 estudios preclínicos en animales sobre lesiones musculares, tendinosas, ligamentarias y óseas, que describieron en su mayoría resultados positivos de curación.","quelle":"Vasireddi et al. 2025, HSS Journal, PMID 40756949"},{"art":"clínico","kurz":"La misma revisión identificó una serie de casos clínicos retrospectiva en la que 7 de 12 pacientes informaron alivio del dolor que duró más de seis meses después de inyecciones intraarticulares en la rodilla.","kurz_en":"La misma revisión identificó una serie de casos clínicos retrospectiva en la que 7 de 12 pacientes informaron alivio del dolor que duró más de seis meses después de inyecciones intraarticulares en la rodilla.","quelle":"Vasireddi et al. 2025, HSS Journal, PMID 40756949"},{"art":"clínico","kurz":"Una revisión retrospectiva de 16 pacientes con dolor de rodilla describió una mejoría significativa en 14 de ellos durante un período de seguimiento de seis a doce meses. No hubo grupo de control.","kurz_en":"Una revisión retrospectiva de 16 pacientes con dolor de rodilla describió una mejoría significativa en 14 de ellos durante un período de seguimiento de seis a doce meses. No hubo grupo de control.","quelle":"Lee & Padgett 2021, Altern Ther Health Med, PMID 34324435"}],"sicherheit":["Los datos de seguridad humana controlados con placebo siguen estando en gran parte ausentes, la mayoría de las declaraciones de seguridad se extraen de modelos animales.","A nivel mecanicista, se discute que las mismas vías que impulsan la angiogénesis y la proliferación celular durante la curación podrían teóricamente también apoyar el crecimiento tumoral existente. No se ha establecido un vínculo causal en humanos.","Los estudios humanos pequeños disponibles no informaron sobre eventos adversos graves.","Los productos de fabricación no controlada conllevan un riesgo de contaminación que es independiente de la molécula misma."],"sicherheit_en":["Los datos de seguridad humana controlados con placebo siguen estando en gran parte ausentes, la mayoría de las declaraciones de seguridad se extraen de modelos animales.","A nivel mecanicista, se discute que las mismas vías que impulsan la angiogénesis y la proliferación celular durante la curación podrían teóricamente también apoyar el crecimiento tumoral existente. No se ha establecido un vínculo causal en humanos.","Los estudios humanos pequeños disponibles no informaron sobre eventos adversos graves.","Los productos de fabricación no controlada conllevan un riesgo de contaminación que es independiente de la molécula misma."],"hinweise":["Solo con fines de investigación, no apto para uso en humanos","Un certificado de análisis no establece idoneidad médica"],"hinweise_en":["Solo con fines de investigación, no apto para uso en humanos","Un certificado de análisis no establece idoneidad médica"],"rekonstitution":"Las condiciones específicas de cada producto figuran en la documentación original del fabricante. Este portal no ofrece instrucciones de preparación ni de uso en humanos.","rekonstitution_en":"Las condiciones específicas de cada producto figuran en la documentación original del fabricante. Este portal no ofrece instrucciones de preparación ni de uso en humanos.","lagerung":"Las condiciones específicas de cada producto figuran en la documentación original del fabricante. Este portal no ofrece instrucciones de preparación ni de uso en humanos.","lagerung_en":"Las condiciones específicas de cada producto figuran en la documentación original del fabricante. Este portal no ofrece instrucciones de preparación ni de uso en humanos.","rechtsstatus":"BPC-157 no está autorizado como medicamento en Alemania, la UE ni Estados Unidos y no está clasificado como producto alimenticio. Se vende exclusivamente como sustancia química para investigación.","rechtsstatus_en":"BPC-157 no está autorizado como medicamento en Alemania, la UE ni Estados Unidos y no está clasificado como producto alimenticio. Se vende exclusivamente como sustancia química para investigación.","typischeMg":[],"faq":[{"q":"¿Es BPC-157 un medicamento aprobado?","a":"No. BPC-157 no está aprobado como medicamento en la UE o los Estados Unidos. Se vende comercialmente solo como un químico de investigación para uso de laboratorio, no para uso humano.","q_en":"¿Es BPC-157 un medicamento aprobado?","a_en":"No. BPC-157 no está aprobado como medicamento en la UE o los Estados Unidos. Se vende comercialmente solo como un químico de investigación para uso de laboratorio, no para uso humano."},{"q":"¿De dónde proviene la secuencia BPC-157?","a":"Se deriva de una proteína protectora encontrada en el jugo gástrico humano, que es también el origen del nombre Body Protection Compound.","q_en":"¿De dónde proviene la secuencia BPC-157?","a_en":"Se deriva de una proteína protectora encontrada en el jugo gástrico humano, que es también el origen del nombre Body Protection Compound."},{"q":"¿Existen estudios en humanos sobre BPC-157?","a":"Hay algunos estudios pequeños y series de casos con limitaciones metodológicas, pero no ensayos grandes controlados con placebo. La mayor parte de la evidencia proviene de modelos animales.","q_en":"¿Existen estudios en humanos sobre BPC-157?","a_en":"Hay algunos estudios pequeños y series de casos con limitaciones metodológicas, pero no ensayos grandes controlados con placebo. La mayor parte de la evidencia proviene de modelos animales."}],"seo":{"title":"BPC-157: perfil de investigación y evidencia","title_en":"BPC-157: perfil de investigación y evidencia","description":"Resumen de BPC-157: origen, mecanismo, evidencia y perfil de seguridad, presentado de forma fáctica para el contexto de la investigación.","description_en":"Resumen de BPC-157: origen, mecanismo, evidencia y perfil de seguridad, presentado de forma fáctica para el contexto de la investigación."},"demo":false,"steckbrief":{"cas":"137525-51-0","molekulargewicht":"1419.5 g/mol","aminosaeuren":15,"halbwertszeit":null,"reinheitsstandard":"≥ 99 % (HPLC, estándar comercial)","loeslichkeit":null,"sequenzLaenge":15,"quellen":["PubChem CID 9941957","chemverify Katalog 14.09.2026"],"reinheitsstandard_en":"≥ 99 % (HPLC, estándar comercial)"},"verwandt":["tb-500","ghk-cu","thymosin-alpha-1","pentadeca-arginate"]},{"slug":"pentadeca-arginate","name":"Pentadeca Arginate (PDA)","synonyme":["PDA","Sal de arginato de BPC-157"],"kategorie":"Regeneration","studienlage":"präklinisch","kurz":"Un pentadecapeptido que comparte la secuencia de aminoácidos de BPC-157, ofrecido como sal de arginina para mejorar la solubilidad y estabilidad.","kurz_en":"Un pentadecapeptido que comparte la secuencia de aminoácidos de BPC-157, ofrecido como sal de arginina para mejorar la solubilidad y estabilidad.","beschreibung":"Pentadeca Arginate, a menudo abreviado PDA, lleva la misma secuencia de 15 aminoácidos que el conocido péptido BPC-157. La diferencia radica en el contraión: en lugar de una sal de acetato, la secuencia está unida a arginina, lo que los proveedores describen como mejorando la solubilidad y la estabilidad de almacenamiento. Los estudios independientes que examinan esta forma de sal específica aún no están disponibles.","beschreibung_en":"Pentadeca Arginate, a menudo abreviado PDA, lleva la misma secuencia de 15 aminoácidos que el conocido péptido BPC-157. La diferencia radica en el contraión: en lugar de una sal de acetato, la secuencia está unida a arginina, lo que los proveedores describen como mejorando la solubilidad y la estabilidad de almacenamiento. Los estudios independientes que examinan esta forma de sal específica aún no están disponibles.","mechanismus":"Dado que la secuencia de aminoácidos es idéntica a BPC-157, los mecanismos descritos en modelos preclínicos se basan en la misma estructura subyacente, incluida la participación en la angiogénesis a través de la vía VEGFR2-AKT-eNOS y la modulación de procesos inflamatorios. No se ha estudiado de forma independiente si la unión de la arginina cambia, acelera o ralentiza estos efectos. Los mecanismos exactos en humanos siguen sin resolverse incluso para la secuencia padre.","mechanismus_en":"Dado que la secuencia de aminoácidos es idéntica a BPC-157, los mecanismos descritos en modelos preclínicos se basan en la misma estructura subyacente, incluida la participación en la angiogénesis a través de la vía VEGFR2-AKT-eNOS y la modulación de procesos inflamatorios. No se ha estudiado de forma independiente si la unión de la arginina cambia, acelera o ralentiza estos efectos. Los mecanismos exactos en humanos siguen sin resolverse incluso para la secuencia padre.","evidenz":[{"art":"preclínico","kurz":"Debido a que Pentadeca Arginate comparte su secuencia con BPC-157, la evidencia disponible se basa en estudios de la secuencia parental. Una revisión sistemática de 2025 evaluó 35 estudios preclínicos en animales sobre lesiones musculares, tendinosas, ligamentos y óseas, que describieron en su mayoría resultados positivos de curación.","kurz_en":"Debido a que Pentadeca Arginate comparte su secuencia con BPC-157, la evidencia disponible se basa en estudios de la secuencia parental. Una revisión sistemática de 2025 evaluó 35 estudios preclínicos en animales sobre lesiones musculares, tendinosas, ligamentos y óseas, que describieron en su mayoría resultados positivos de curación.","quelle":"Vasireddi et al. 2025, HSS Journal, PMID 40756949"},{"art":"preclínico","kurz":"Un estudio celular describió la activación y la regulación al alza de VEGFR2, un receptor clave en la formación de vasos sanguíneos, para la misma secuencia, acompañado de un aumento en la formación de tubos endoteliales en el modelo de laboratorio.","kurz_en":"Un estudio celular describió la activación y la regulación al alza de VEGFR2, un receptor clave en la formación de vasos sanguíneos, para la misma secuencia, acompañado de un aumento en la formación de tubos endoteliales en el modelo de laboratorio.","quelle":"Hsieh et al. 2016, Journal of Molecular Medicine, PMID 27847966"}],"sicherheit":["No existen datos de seguridad independientes para la forma de sal de arginina en sí, una búsqueda bibliográfica dirigida no arrojó resultados.","Los datos humanos controlados con placebo siguen estando en gran parte ausentes para la secuencia subyacente, la mayoría de las declaraciones de seguridad se derivan de modelos animales.","A nivel mecanicista, se discute que las mismas vías que impulsan la angiogénesis y la proliferación celular durante la curación podrían teóricamente también apoyar el crecimiento tumoral existente. No se ha establecido un vínculo causal en humanos.","Los productos de fabricación no controlada conllevan un riesgo de contaminación que es independiente de la molécula misma."],"sicherheit_en":["No existen datos de seguridad independientes para la forma de sal de arginina en sí, una búsqueda bibliográfica dirigida no arrojó resultados.","Los datos humanos controlados con placebo siguen estando en gran parte ausentes para la secuencia subyacente, la mayoría de las declaraciones de seguridad se derivan de modelos animales.","A nivel mecanicista, se discute que las mismas vías que impulsan la angiogénesis y la proliferación celular durante la curación podrían teóricamente también apoyar el crecimiento tumoral existente. No se ha establecido un vínculo causal en humanos.","Los productos de fabricación no controlada conllevan un riesgo de contaminación que es independiente de la molécula misma."],"hinweise":["Solo con fines de investigación, no apto para uso en humanos","Un certificado de análisis no establece idoneidad médica"],"hinweise_en":["Solo con fines de investigación, no apto para uso en humanos","Un certificado de análisis no establece idoneidad médica"],"rekonstitution":"Las condiciones específicas de cada producto figuran en la documentación original del fabricante. Este portal no ofrece instrucciones de preparación ni de uso en humanos.","rekonstitution_en":"Las condiciones específicas de cada producto figuran en la documentación original del fabricante. Este portal no ofrece instrucciones de preparación ni de uso en humanos.","lagerung":"Las condiciones específicas de cada producto figuran en la documentación original del fabricante. Este portal no ofrece instrucciones de preparación ni de uso en humanos.","lagerung_en":"Las condiciones específicas de cada producto figuran en la documentación original del fabricante. Este portal no ofrece instrucciones de preparación ni de uso en humanos.","rechtsstatus":"Pentadeca Arginate no está autorizado como medicamento en Alemania, la UE ni Estados Unidos y no está clasificado como producto alimenticio. Se vende exclusivamente como sustancia química para investigación.","rechtsstatus_en":"Pentadeca Arginate no está autorizado como medicamento en Alemania, la UE ni Estados Unidos y no está clasificado como producto alimenticio. Se vende exclusivamente como sustancia química para investigación.","typischeMg":[],"faq":[{"q":"¿Es Pentadeca Arginate lo mismo que BPC-157?","a":"La secuencia de aminoácidos es idéntica. La diferencia radica en el contraión: BPC-157 se ofrece generalmente como sal de acetato, Pentadeca Arginate como sal de arginina, lo cual los proveedores describen como mejorando la solubilidad.","q_en":"¿Es Pentadeca Arginate lo mismo que BPC-157?","a_en":"La secuencia de aminoácidos es idéntica. La diferencia radica en el contraión: BPC-157 se ofrece generalmente como sal de acetato, Pentadeca Arginate como sal de arginina, lo cual los proveedores describen como mejorando la solubilidad."},{"q":"¿Existen estudios independientes sobre la forma de sal de arginina?","a":"No, una búsqueda bibliográfica dirigida no encontró estudios independientes sobre la forma de sal de arginina en sí. La evidencia disponible se relaciona con la secuencia parental de BPC-157.","q_en":"¿Existen estudios independientes sobre la forma de sal de arginina?","a_en":"No, una búsqueda bibliográfica dirigida no encontró estudios independientes sobre la forma de sal de arginina en sí. La evidencia disponible se relaciona con la secuencia parental de BPC-157."},{"q":"¿Es Pentadeca Arginate un medicamento aprobado?","a":"No. No está aprobado en la UE o en los Estados Unidos y se vende exclusivamente como un químico de investigación para uso de laboratorio.","q_en":"¿Es Pentadeca Arginate un medicamento aprobado?","a_en":"No. No está aprobado en la UE o en los Estados Unidos y se vende exclusivamente como un químico de investigación para uso de laboratorio."}],"seo":{"title":"Pentadeca Arginate (PDA): Perfil de Investigación y Evidencia","title_en":"Pentadeca Arginate (PDA): Perfil de Investigación y Evidencia","description":"Resumen de Pentadeca Arginate: identidad de secuencia con BPC-157, evidencia sobre la secuencia parental y perfil de seguridad, presentado de forma fáctica para investigación.","description_en":"Resumen de Pentadeca Arginate: identidad de secuencia con BPC-157, evidencia sobre la secuencia parental y perfil de seguridad, presentado de forma fáctica para investigación."},"demo":false,"steckbrief":{"cas":null,"molekulargewicht":null,"aminosaeuren":15,"halbwertszeit":null,"reinheitsstandard":null,"loeslichkeit":null,"sequenzLaenge":15,"quellen":["chemverify Katalog 14.09.2026 (CAS/Molekulargewicht dort nicht geführt, PubChem: kein Eintrag für Pentadeca Arginate)"]},"verwandt":["bpc-157","tb-500","ghk-cu"]},{"slug":"tb-500","name":"TB-500","synonyme":["Fragmento de timosina beta-4","Frag TB4"],"kategorie":"Regeneration","studienlage":"präklinisch","kurz":"Un fragmento sintético de la propia proteína del cuerpo, timosina beta-4, estudiado en investigación preclínica sobre migración celular y regeneración de tejidos.","kurz_en":"Un fragmento sintético de la propia proteína del cuerpo, timosina beta-4, estudiado en investigación preclínica sobre migración celular y regeneración de tejidos.","beschreibung":"TB-500 es la secuencia central de siete aminoácidos producida sintéticamente de la propia proteína del cuerpo, timosina beta-4. La mayoría de los datos disponibles, incluidos los estudios clínicos, se relacionan con la timosina beta-4 completa de 43 aminoácidos, no con el fragmento aislado TB-500 en sí. Las áreas de estudio incluyen la migración celular, la angiogénesis y un posible papel en la activación de folículos pilosos.","beschreibung_en":"TB-500 es la secuencia central de siete aminoácidos producida sintéticamente de la propia proteína del cuerpo, timosina beta-4. La mayoría de los datos disponibles, incluidos los estudios clínicos, se relacionan con la timosina beta-4 completa de 43 aminoácidos, no con el fragmento aislado TB-500 en sí. Las áreas de estudio incluyen la migración celular, la angiogénesis y un posible papel en la activación de folículos pilosos.","mechanismus":"La secuencia central estudiada se une a G-actina, un bloque de construcción del citoesqueleto, influyendo así en el movimiento celular dentro del tejido. En la proteína completa timosina beta-4, también se han descrito la participación en la angiogénesis a través del aumento de la expresión de VEGF y un efecto regulador de la inflamación a través de la vía NF-κB. Si estos mecanismos se transfieren completamente al fragmento aislado TB-500 no está científicamente establecido.","mechanismus_en":"La secuencia central estudiada se une a G-actina, un bloque de construcción del citoesqueleto, influyendo así en el movimiento celular dentro del tejido. En la proteína completa timosina beta-4, también se han descrito la participación en la angiogénesis a través del aumento de la expresión de VEGF y un efecto regulador de la inflamación a través de la vía NF-κB. Si estos mecanismos se transfieren completamente al fragmento aislado TB-500 no está científicamente establecido.","evidenz":[{"art":"preclínico","kurz":"Un estudio en ratas y ratones describió que la secuencia activa de timosina beta-4, que también forma TB-500, influyó en la migración de células madre dentro del folículo piloso.","kurz_en":"Un estudio en ratas y ratones describió que la secuencia activa de timosina beta-4, que también forma TB-500, influyó en la migración de células madre dentro del folículo piloso.","quelle":"Philp et al. 2004, FASEB Journal, PMID 14657002"},{"art":"clínico","kurz":"Un ensayo clínico aleatorizado y controlado con placebo en pacientes con ojo seco severo probó una formulación de gota ocular de la proteína completa de timosina beta-4 y describió signos y síntomas mejorados en comparación con el placebo. El ensayo involucró la proteína completa, no el fragmento TB-500 en sí mismo.","kurz_en":"Un ensayo clínico aleatorizado y controlado con placebo en pacientes con ojo seco severo probó una formulación de gota ocular de la proteína completa de timosina beta-4 y describió signos y síntomas mejorados en comparación con el placebo. El ensayo involucró la proteína completa, no el fragmento TB-500 en sí mismo.","quelle":"Sosne et al. 2015, Cornea, PMID 25826322"}],"sicherheit":["Para TB-500 como fragmento aislado, no hay estudios de seguridad humana controlados independientes disponibles.","Para la proteína completa de timosina beta-4, los estudios clínicos han descrito principalmente efectos secundarios leves y transitorios.","A nivel mecanicista, se discute un vínculo teórico entre los efectos promotores de la angiogénesis y el crecimiento tumoral existente, no se ha establecido una conexión causal.","Timosina beta-4 y fragmentos relacionados están en la lista prohibida de la Agencia Mundial Antidopaje."],"sicherheit_en":["Para TB-500 como fragmento aislado, no hay estudios de seguridad humana controlados independientes disponibles.","Para la proteína completa de timosina beta-4, los estudios clínicos han descrito principalmente efectos secundarios leves y transitorios.","A nivel mecanicista, se discute un vínculo teórico entre los efectos promotores de la angiogénesis y el crecimiento tumoral existente, no se ha establecido una conexión causal.","Timosina beta-4 y fragmentos relacionados están en la lista prohibida de la Agencia Mundial Antidopaje."],"hinweise":["Solo con fines de investigación, no apto para uso en humanos","Un certificado de análisis no establece idoneidad médica"],"hinweise_en":["Solo con fines de investigación, no apto para uso en humanos","Un certificado de análisis no establece idoneidad médica"],"rekonstitution":"Las condiciones específicas de cada producto figuran en la documentación original del fabricante. Este portal no ofrece instrucciones de preparación ni de uso en humanos.","rekonstitution_en":"Las condiciones específicas de cada producto figuran en la documentación original del fabricante. Este portal no ofrece instrucciones de preparación ni de uso en humanos.","lagerung":"Las condiciones específicas de cada producto figuran en la documentación original del fabricante. Este portal no ofrece instrucciones de preparación ni de uso en humanos.","lagerung_en":"Las condiciones específicas de cada producto figuran en la documentación original del fabricante. Este portal no ofrece instrucciones de preparación ni de uso en humanos.","rechtsstatus":"TB-500 no está aprobado como medicamento en Alemania, la UE o los Estados Unidos, y se vende exclusivamente como producto químico de investigación. La proteína relacionada timosina beta-4 tampoco está aprobada como medicamento independiente.","rechtsstatus_en":"TB-500 no está aprobado como medicamento en Alemania, la UE o los Estados Unidos, y se vende exclusivamente como producto químico de investigación. La proteína relacionada timosina beta-4 tampoco está aprobada como medicamento independiente.","typischeMg":[],"faq":[{"q":"¿Es TB-500 lo mismo que timosina beta-4?","a":"No. TB-500 es un fragmento sintético de siete aminoácidos de la secuencia completa de 43 aminoácidos de timosina beta-4. La mayoría de los datos clínicos se relacionan con la proteína completa, no con el fragmento.","q_en":"¿Es TB-500 lo mismo que timosina beta-4?","a_en":"No. TB-500 es un fragmento sintético de siete aminoácidos de la secuencia completa de 43 aminoácidos de timosina beta-4. La mayoría de los datos clínicos se relacionan con la proteína completa, no con el fragmento."},{"q":"¿Hay estudios clínicos sobre TB-500 en sí mismo?","a":"No hay estudios humanos controlados independientes sobre el fragmento aislado de TB-500 disponibles. Los datos clínicos disponibles provienen de la proteína completa de timosina beta-4.","q_en":"¿Hay estudios clínicos sobre TB-500 en sí mismo?","a_en":"No hay estudios humanos controlados independientes sobre el fragmento aislado de TB-500 disponibles. Los datos clínicos disponibles provienen de la proteína completa de timosina beta-4."},{"q":"¿Es TB-500 relevante para las reglas antidopaje?","a":"Timosina beta-4 y fragmentos relacionados están en la lista prohibida de la Agencia Mundial Antidopaje.","q_en":"¿Es TB-500 relevante para las reglas antidopaje?","a_en":"Timosina beta-4 y fragmentos relacionados están en la lista prohibida de la Agencia Mundial Antidopaje."}],"seo":{"title":"TB-500: perfil de investigación y evidencia","title_en":"TB-500: perfil de investigación y evidencia","description":"Resumen de TB-500: origen de timosina beta-4, mecanismo, evidencia y perfil de seguridad, presentado de forma fáctica para el contexto de la investigación.","description_en":"Resumen de TB-500: origen de timosina beta-4, mecanismo, evidencia y perfil de seguridad, presentado de forma fáctica para el contexto de la investigación."},"demo":false,"steckbrief":{"cas":null,"molekulargewicht":"4963 g/mol","aminosaeuren":43,"halbwertszeit":null,"reinheitsstandard":"≥ 99 % (HPLC, estándar comercial)","loeslichkeit":null,"sequenzLaenge":43,"quellen":["PubChem CID 45382195","chemverify Katalog 14.09.2026"],"reinheitsstandard_en":"≥ 99 % (HPLC, estándar comercial)"},"verwandt":["bpc-157","ghk-cu","thymosin-alpha-1","pentadeca-arginate"]},{"slug":"5-amino-1mq","name":"5-Amino-1MQ","synonyme":["5-Amino 1MQ","5A1MQ","Inhibidor de NNMT"],"kategorie":"Stoffwechsel","studienlage":"präklinisch","kurz":"Una molécula pequeña e inhibidor selectivo de la enzima nicotinamida N-metiltransferasa (NNMT), estudiada hasta la fecha exclusivamente en modelos animales preclínicos relacionados con el metabolismo de la grasa.","kurz_en":"Una molécula pequeña e inhibidor selectivo de la enzima nicotinamida N-metiltransferasa (NNMT), estudiada hasta la fecha exclusivamente en modelos animales preclínicos relacionados con el metabolismo de la grasa.","beschreibung":"5-Amino-1MQ no es un péptido sino una molécula pequeña, un inhibidor selectivo y biodisponible oralmente de la nicotinamida N-metiltransferasa (NNMT). Tiene un peso molecular de 173,21 Da, y los lotes de investigación vendidos comercialmente suelen tener una pureza de al menos 98 por ciento. Está listado bajo la categoría de metabolismo porque la NNMT está involucrada en el metabolismo energético en tejido adiposo y músculo. Hasta la fecha, solo hay datos preclínicos de modelos roedores disponibles, y no se conocen estudios controlados en humanos.","beschreibung_en":"5-Amino-1MQ no es un péptido sino una molécula pequeña, un inhibidor selectivo y biodisponible oralmente de la nicotinamida N-metiltransferasa (NNMT). Tiene un peso molecular de 173,21 Da, y los lotes de investigación vendidos comercialmente suelen tener una pureza de al menos 98 por ciento. Está listado bajo la categoría de metabolismo porque la NNMT está involucrada en el metabolismo energético en tejido adiposo y músculo. Hasta la fecha, solo hay datos preclínicos de modelos roedores disponibles, y no se conocen estudios controlados en humanos.","mechanismus":"La NNMT transfiere un grupo metilo desde S-adenosilmetionina (SAM) a la nicotinamida, un precursor de NAD+, formando 1-metilnicotinamida. Esta reacción consume tanto SAM como la nicotinamida precursor de NAD+. 5-Amino-1MQ inhibe selectivamente esta enzima, lo que preservó los niveles intracelulares de NAD+ y SAM en células de grasa y músculo en modelos animales. En investigación preclínica, esto se ha relacionado con un aumento del gasto energético, reducción del tamaño del adipocito y mejorada capacidad regenerativa del tejido muscular.","mechanismus_en":"La NNMT transfiere un grupo metilo desde S-adenosilmetionina (SAM) a la nicotinamida, un precursor de NAD+, formando 1-metilnicotinamida. Esta reacción consume tanto SAM como la nicotinamida precursor de NAD+. 5-Amino-1MQ inhibe selectivamente esta enzima, lo que preservó los niveles intracelulares de NAD+ y SAM en células de grasa y músculo en modelos animales. En investigación preclínica, esto se ha relacionado con un aumento del gasto energético, reducción del tamaño del adipocito y mejorada capacidad regenerativa del tejido muscular.","evidenz":[{"art":"preclínico","kurz":"En un modelo de ratón con silenciamiento genético de la NNMT en el tejido adiposo, se observó protección contra la obesidad inducida por la dieta en comparación con animales de control, junto con un aumento del gasto energético.","kurz_en":"En un modelo de ratón con silenciamiento genético de la NNMT en el tejido adiposo, se observó protección contra la obesidad inducida por la dieta en comparación con animales de control, junto con un aumento del gasto energético.","quelle":"Kraus D et al. 2014, Nature 508:258-262, PMID 24717514"},{"art":"preclínico","kurz":"En ratones obesos inducidos por la dieta, once días de administración de 5-Amino-1MQ redujeron el peso corporal, la masa grasa y el tamaño del adipocito en comparación con animales de control, sin alterar la ingesta de alimentos.","kurz_en":"En ratones obesos inducidos por la dieta, once días de administración de 5-Amino-1MQ redujeron el peso corporal, la masa grasa y el tamaño del adipocito en comparación con animales de control, sin alterar la ingesta de alimentos.","quelle":"Neelakantan H et al. 2018, Biochemical Pharmacology, PMID 29155147"},{"art":"preclínico","kurz":"En ratones envejecidos, un inhibidor de la NNMT se asoció con la reactivación de células madre musculares senescentes y una mejorada capacidad regenerativa del músculo esquelético después de una lesión.","kurz_en":"En ratones envejecidos, un inhibidor de la NNMT se asoció con la reactivación de células madre musculares senescentes y una mejorada capacidad regenerativa del músculo esquelético después de una lesión.","quelle":"Neelakantan H et al. 2019, Biochemical Pharmacology 163:481-492, PMID 30753815"},{"art":"preclínico","kurz":"Combinar una dieta de calorías reducidas con 5-Amino-1MQ normalizó el porcentaje de grasa corporal y el peso más rápido en ratones obesos inducidos por la dieta que el cambio de dieta por sí solo, al tiempo que alteraba la composición del microbioma intestinal.","kurz_en":"Combinar una dieta de calorías reducidas con 5-Amino-1MQ normalizó el porcentaje de grasa corporal y el peso más rápido en ratones obesos inducidos por la dieta que el cambio de dieta por sí solo, al tiempo que alteraba la composición del microbioma intestinal.","quelle":"Scientific Reports 2022, PMID 35013352"}],"sicherheit":["En el estudio de 2018 de Neelakantan et al. en ratones obesos, la ingesta de alimentos no cambió con 5-Amino-1MQ, lo que en el modelo animal sugiere una tolerabilidad razonable durante el período del estudio.","No se conocen estudios de seguridad humana controlados sobre 5-Amino-1MQ, solo hay datos de modelos animales disponibles.","No se han publicado paquetes toxicológicos preclínicos estandarizados, como estudios de administración repetida de varias semanas en especies adicionales, para 5-Amino-1MQ.","Las interacciones con otras sustancias o suplementos no se han estudiado sistemáticamente para 5-Amino-1MQ."],"sicherheit_en":["En el estudio de 2018 de Neelakantan et al. en ratones obesos, la ingesta de alimentos no cambió con 5-Amino-1MQ, lo que en el modelo animal sugiere una tolerabilidad razonable durante el período del estudio.","No se conocen estudios de seguridad humana controlados sobre 5-Amino-1MQ, solo hay datos de modelos animales disponibles.","No se han publicado paquetes toxicológicos preclínicos estandarizados, como estudios de administración repetida de varias semanas en especies adicionales, para 5-Amino-1MQ.","Las interacciones con otras sustancias o suplementos no se han estudiado sistemáticamente para 5-Amino-1MQ."],"hinweise":["Solo con fines de investigación, no apto para uso en humanos","Un certificado de análisis no establece idoneidad médica"],"hinweise_en":["Solo con fines de investigación, no apto para uso en humanos","Un certificado de análisis no establece idoneidad médica"],"rekonstitution":"Las condiciones específicas de cada producto figuran en la documentación original del fabricante. Este portal no ofrece instrucciones de preparación ni de uso en humanos.","rekonstitution_en":"Las condiciones específicas de cada producto figuran en la documentación original del fabricante. Este portal no ofrece instrucciones de preparación ni de uso en humanos.","lagerung":"Las condiciones específicas de cada producto figuran en la documentación original del fabricante. Este portal no ofrece instrucciones de preparación ni de uso en humanos.","lagerung_en":"Las condiciones específicas de cada producto figuran en la documentación original del fabricante. Este portal no ofrece instrucciones de preparación ni de uso en humanos.","rechtsstatus":"5-Amino-1MQ no está aprobado como medicamento en la UE o Estados Unidos y se vende exclusivamente como producto químico de investigación. No se conocen ensayos de aprobación humana.","rechtsstatus_en":"5-Amino-1MQ no está aprobado como medicamento en la UE o Estados Unidos y se vende exclusivamente como producto químico de investigación. No se conocen ensayos de aprobación humana.","typischeMg":[10,50],"faq":[{"q":"¿Es 5-Amino-1MQ un péptido?","a":"No. 5-Amino-1MQ es una molécula pequeña, no un péptido, y no consiste en una cadena de aminoácidos. Se estudia como un inhibidor selectivo de la enzima NNMT y se enumera aquí entre los compuestos relacionados con el metabolismo porque actúa sobre sistemas diana relacionados.","q_en":"¿Es 5-Amino-1MQ un péptido?","a_en":"No. 5-Amino-1MQ es una molécula pequeña, no un péptido, y no consiste en una cadena de aminoácidos. Se estudia como un inhibidor selectivo de la enzima NNMT y se enumera aquí entre los compuestos relacionados con el metabolismo porque actúa sobre sistemas diana relacionados."},{"q":"¿Existen estudios en humanos sobre 5-Amino-1MQ?","a":"No, no se conocen estudios clínicos controlados en humanos hasta la fecha. Todos los datos publicados provienen de investigación preclínica en ratones.","q_en":"¿Existen estudios en humanos sobre 5-Amino-1MQ?","a_en":"No, no se conocen estudios clínicos controlados en humanos hasta la fecha. Todos los datos publicados provienen de investigación preclínica en ratones."},{"q":"¿Por qué se estudia NNMT en la investigación?","a":"NNMT es una enzima activa en el tejido adiposo y muscular que descompone la nicotinamida, un precursor del NAD+. Niveles elevados de NNMT se han relacionado con una reducción de la actividad metabólica en modelos preclínicos, por lo que su inhibición se está estudiando como enfoque de investigación.","q_en":"¿Por qué se estudia NNMT en la investigación?","a_en":"NNMT es una enzima activa en el tejido adiposo y muscular que descompone la nicotinamida, un precursor del NAD+. Niveles elevados de NNMT se han relacionado con una reducción de la actividad metabólica en modelos preclínicos, por lo que su inhibición se está estudiando como enfoque de investigación."}],"seo":{"title":"5-Amino-1MQ: Inhibidor de NNMT en Investigación Preclínica","title_en":"5-Amino-1MQ: Inhibidor de NNMT en Investigación Preclínica","description":"5-Amino-1MQ de un vistazo: mecanismo, estado del estudio preclínico y estado legal del inhibidor de NNMT, una molécula pequeña en lugar de un péptido.","description_en":"5-Amino-1MQ de un vistazo: mecanismo, estado del estudio preclínico y estado legal del inhibidor de NNMT, una molécula pequeña en lugar de un péptido."},"demo":false,"steckbrief":{"cas":"685079-15-6","molekulargewicht":"159.21 g/mol","aminosaeuren":null,"halbwertszeit":null,"reinheitsstandard":"≥ 98 % (HPLC, estándar comercial)","loeslichkeit":null,"sequenzLaenge":null,"quellen":["PubChem CID 950107","chemverify Katalog 14.09.2026","kein Peptid, kleines Molekül ohne Aminosäuresequenz (NNMT-Inhibitor)"],"reinheitsstandard_en":"≥ 98 % (HPLC, estándar comercial)"},"verwandt":["aod-9604","mots-c","tirzepatid"]},{"slug":"aod-9604","name":"AOD-9604","synonyme":["Medicamento antiobesidad 9604","Tyr-hGH Frag 177-191"],"kategorie":"Stoffwechsel","studienlage":"klinisch untersucht","kurz":"Un fragmento de péptido de la hormona del crecimiento humana (aminoácidos 177-191) estudiado por un efecto reductor de grasa sin los efectos promotores de crecimiento de la hormona completa.","kurz_en":"Un fragmento de péptido de la hormona del crecimiento humana (aminoácidos 177-191) estudiado por un efecto reductor de grasa sin los efectos promotores de crecimiento de la hormona completa.","beschreibung":"AOD-9604 es un fragmento sintético de 16 aminoácidos de la hormona del crecimiento humana (secuencia Tyr-hGH177-191), desarrollado originalmente por Metabolic Pharmaceuticals en colaboración con la Universidad de Monash para la regulación del peso. Se estudió en seis ensayos clínicos aleatorizados controlados con placebo en humanos con más de 900 participantes por sus efectos metabólicos y seguridad. El desarrollo clínico como compuesto para la obesidad fue descontinuado en 2007 después de que el ensayo más grande no cumpliera con su objetivo de eficacia primaria.","beschreibung_en":"AOD-9604 es un fragmento sintético de 16 aminoácidos de la hormona del crecimiento humana (secuencia Tyr-hGH177-191), desarrollado originalmente por Metabolic Pharmaceuticals en colaboración con la Universidad de Monash para la regulación del peso. Se estudió en seis ensayos clínicos aleatorizados controlados con placebo en humanos con más de 900 participantes por sus efectos metabólicos y seguridad. El desarrollo clínico como compuesto para la obesidad fue descontinuado en 2007 después de que el ensayo más grande no cumpliera con su objetivo de eficacia primaria.","mechanismus":"AOD-9604 comprende la región lipolítica (aminoácidos 177-191) de la molécula de hormona del crecimiento, sin la región de unión al receptor responsable del crecimiento y los efectos metabólicos mediados por IGF-1 de la hGH completa. Los modelos preclínicos describen una activación de la lipólisis a través del mensajero diacilglicerol y la enzima lipasa sensible a la hormona, mediada a través del receptor adrenérgico beta-3. A diferencia de la hGH completa, AOD-9604 no afectó los niveles de IGF-1 ni la sensibilidad a la insulina en los estudios.","mechanismus_en":"AOD-9604 comprende la región lipolítica (aminoácidos 177-191) de la molécula de hormona del crecimiento, sin la región de unión al receptor responsable del crecimiento y los efectos metabólicos mediados por IGF-1 de la hGH completa. Los modelos preclínicos describen una activación de la lipólisis a través del mensajero diacilglicerol y la enzima lipasa sensible a la hormona, mediada a través del receptor adrenérgico beta-3. A diferencia de la hGH completa, AOD-9604 no afectó los niveles de IGF-1 ni la sensibilidad a la insulina en los estudios.","evidenz":[{"art":"preclínico","kurz":"En un estudio preclínico en ratas Zucker obesas, 19 días de administración oral de AOD-9604 redujeron el aumento de peso corporal en más del 50 por ciento en comparación con los animales de control.","kurz_en":"En un estudio preclínico en ratas Zucker obesas, 19 días de administración oral de AOD-9604 redujeron el aumento de peso corporal en más del 50 por ciento en comparación con los animales de control.","quelle":"Ng FM et al. 2000, Hormone Research 53(6):274-278, PMID 11146367"},{"art":"preclínico","kurz":"En ratones obesos, la administración crónica de AOD-9604 aumentó la oxidación de grasa y la sensibilidad lipolítica a través de la vía del receptor adrenérgico beta-3, comparable a la hGH completa pero sin afectar la sensibilidad a la insulina.","kurz_en":"En ratones obesos, la administración crónica de AOD-9604 aumentó la oxidación de grasa y la sensibilidad lipolítica a través de la vía del receptor adrenérgico beta-3, comparable a la hGH completa pero sin afectar la sensibilidad a la insulina.","quelle":"Heffernan M et al. 2001, Endocrinology 142(12):5182-5189, PMID 11673763"},{"art":"clínico","kurz":"En un estudio multicéntrico aleatorizado, doble ciego y controlado con placebo en 300 adultos con obesidad, el grupo que recibió 1 mg oral diariamente perdió un promedio de 2,8 kg durante 12 semanas en comparación con 0,8 kg bajo placebo.","kurz_en":"En un estudio multicéntrico aleatorizado, doble ciego y controlado con placebo en 300 adultos con obesidad, el grupo que recibió 1 mg oral diariamente perdió un promedio de 2,8 kg durante 12 semanas en comparación con 0,8 kg bajo placebo.","quelle":"Herd C et al. 2005, randomisierte Multicenter-Studie (Publikationsnachweis: ResearchGate ID 295313034 / University of Melbourne)"},{"art":"clínico","kurz":"Una revisión de seguridad en seis ensayos clínicos controlados con placebo en humanos no encontró aumento en los niveles de IGF-1, no hubo eventos adversos graves relacionados con AOD-9604 y no se detectaron anticuerpos anti-AOD-9604 detectables.","kurz_en":"Una revisión de seguridad en seis ensayos clínicos controlados con placebo en humanos no encontró aumento en los niveles de IGF-1, no hubo eventos adversos graves relacionados con AOD-9604 y no se detectaron anticuerpos anti-AOD-9604 detectables.","quelle":"Stier H et al. 2013, Journal of Endocrinology and Metabolism 3(2), jofem.org"}],"sicherheit":["En seis ensayos clínicos controlados con placebo en humanos, no ocurrieron eventos adversos graves relacionados con AOD-9604, y los efectos reportados fueron menores y transitorios.","A diferencia de la hGH completa, AOD-9604 no elevó los niveles de IGF-1 ni deterioró la tolerancia a la glucosa en estos ensayos.","No se detectaron anticuerpos contra AOD-9604 en los ensayos que evaluaron inmunogenicidad.","El desarrollo clínico se discontinuó en 2007 después de que el ensayo de fase 2b más grande no alcanzara estadísticamente su objetivo primario de pérdida de peso frente al placebo, sin que se reportaran preocupaciones de seguridad como razón.","Dado que AOD-9604 no está aprobado como medicamento en ninguna parte, no existe información oficial de prescripción sobre seguridad a largo plazo."],"sicherheit_en":["En seis ensayos clínicos controlados con placebo en humanos, no ocurrieron eventos adversos graves relacionados con AOD-9604, y los efectos reportados fueron menores y transitorios.","A diferencia de la hGH completa, AOD-9604 no elevó los niveles de IGF-1 ni deterioró la tolerancia a la glucosa en estos ensayos.","No se detectaron anticuerpos contra AOD-9604 en los ensayos que evaluaron inmunogenicidad.","El desarrollo clínico se discontinuó en 2007 después de que el ensayo de fase 2b más grande no alcanzara estadísticamente su objetivo primario de pérdida de peso frente al placebo, sin que se reportaran preocupaciones de seguridad como razón.","Dado que AOD-9604 no está aprobado como medicamento en ninguna parte, no existe información oficial de prescripción sobre seguridad a largo plazo."],"hinweise":["Solo con fines de investigación, no apto para uso en humanos","Un certificado de análisis no establece idoneidad médica"],"hinweise_en":["Solo con fines de investigación, no apto para uso en humanos","Un certificado de análisis no establece idoneidad médica"],"rekonstitution":"Las condiciones específicas de cada producto figuran en la documentación original del fabricante. Este portal no ofrece instrucciones de preparación ni de uso en humanos.","rekonstitution_en":"Las condiciones específicas de cada producto figuran en la documentación original del fabricante. Este portal no ofrece instrucciones de preparación ni de uso en humanos.","lagerung":"Las condiciones específicas de cada producto figuran en la documentación original del fabricante. Este portal no ofrece instrucciones de preparación ni de uso en humanos.","lagerung_en":"Las condiciones específicas de cada producto figuran en la documentación original del fabricante. Este portal no ofrece instrucciones de preparación ni de uso en humanos.","rechtsstatus":"AOD-9604 no está aprobado como medicamento en la UE o en los Estados Unidos. El desarrollo clínico como compuesto para la obesidad se discontinuó en 2007 después de un ensayo de fase 2b. La sustancia se vende exclusivamente como producto químico de investigación y figura en la Lista Prohibida de la WADA para deportes.","rechtsstatus_en":"AOD-9604 no está aprobado como medicamento en la UE o en los Estados Unidos. El desarrollo clínico como compuesto para la obesidad se discontinuó en 2007 después de un ensayo de fase 2b. La sustancia se vende exclusivamente como producto químico de investigación y figura en la Lista Prohibida de la WADA para deportes.","typischeMg":[2,5,10],"faq":[{"q":"¿Está aprobado AOD-9604 como medicamento?","a":"No. AOD-9604 fue estudiado en seis ensayos clínicos, y el desarrollo como compuesto para la obesidad se discontinuó en 2007. Actualmente no es un medicamento aprobado y solo se vende como producto químico de investigación.","q_en":"¿Está aprobado AOD-9604 como medicamento?","a_en":"No. AOD-9604 fue estudiado en seis ensayos clínicos, y el desarrollo como compuesto para la obesidad se discontinuó en 2007. Actualmente no es un medicamento aprobado y solo se vende como producto químico de investigación."},{"q":"¿En qué se diferencia AOD-9604 de la hormona del crecimiento completa?","a":"AOD-9604 contiene solo la región lipolítica de la molécula de hGH (aminoácidos 177-191), no la región que desencadena los efectos de crecimiento mediados por IGF-1. A diferencia de la hGH intacta, no mostró efecto sobre IGF-1 ni sensibilidad a la insulina en los estudios.","q_en":"¿En qué se diferencia AOD-9604 de la hormona del crecimiento completa?","a_en":"AOD-9604 contiene solo la región lipolítica de la molécula de hGH (aminoácidos 177-191), no la región que desencadena los efectos de crecimiento mediados por IGF-1. A diferencia de la hGH intacta, no mostró efecto sobre IGF-1 ni sensibilidad a la insulina en los estudios."},{"q":"¿Se permite AOD-9604 en el deporte?","a":"No. AOD-9604 está listado como fragmento de hormona del crecimiento en la Lista Prohibida de la WADA, y no hay exención de uso terapéutico disponible para él.","q_en":"¿Se permite AOD-9604 en el deporte?","a_en":"No. AOD-9604 está listado como fragmento de hormona del crecimiento en la Lista Prohibida de la WADA, y no hay exención de uso terapéutico disponible para él."}],"seo":{"title":"AOD-9604: Fragmento de hGH 177-191 en Investigación","title_en":"AOD-9604: Fragmento de hGH 177-191 en Investigación","description":"AOD-9604 de un vistazo: mecanismo, estado del estudio y perfil de seguridad del fragmento hGH 177-191 estudiado en ensayos clínicos para la regulación del peso.","description_en":"AOD-9604 de un vistazo: mecanismo, estado del estudio y perfil de seguridad del fragmento hGH 177-191 estudiado en ensayos clínicos para la regulación del peso."},"demo":false,"steckbrief":{"cas":"221231-10-3","molekulargewicht":"1815.1 g/mol","aminosaeuren":16,"halbwertszeit":null,"reinheitsstandard":"≥ 98 % (HPLC, estándar comercial)","loeslichkeit":null,"sequenzLaenge":16,"quellen":["PubChem CID 71300630","chemverify Katalog 14.09.2026"],"reinheitsstandard_en":"≥ 98 % (HPLC, estándar comercial)"},"verwandt":["tesamorelin","mots-c","5-amino-1mq"]},{"slug":"cagrilintid","name":"Cagrilintida","synonyme":["AM833","NN9838"],"kategorie":"Stoffwechsel","studienlage":"klinisch untersucht","kurz":"Un análogo de acción prolongada de la propia hormona del cuerpo, amilina, estudiado en ensayos clínicos para la regulación metabólica y de la saciedad, solo y en combinación con semaglutida.","kurz_en":"Un análogo de acción prolongada de la propia hormona del cuerpo, amilina, estudiado en ensayos clínicos para la regulación metabólica y de la saciedad, solo y en combinación con semaglutida.","beschreibung":"La cagrilintida es un análogo de amilina de acción prolongada desarrollado por Novo Nordisk. Está siendo estudiada tanto como sustancia independiente como en combinación fija con el compuesto GLP-1 semaglutida, comercializado bajo el nombre CagriSema, en ensayos de fase 3. Hasta la fecha, la cagrilintida no está aprobada como medicamento independiente en ningún país.","beschreibung_en":"La cagrilintida es un análogo de amilina de acción prolongada desarrollado por Novo Nordisk. Está siendo estudiada tanto como sustancia independiente como en combinación fija con el compuesto GLP-1 semaglutida, comercializado bajo el nombre CagriSema, en ensayos de fase 3. Hasta la fecha, la cagrilintida no está aprobada como medicamento independiente en ningún país.","mechanismus":"La cagrilintida se une a los receptores de amilina en el cerebro, principalmente los subtipos AMY1 y AMY3 formados por el receptor de calcitonina junto con proteínas RAMP accesorias. Esto se ha relacionado con una ralentización del vaciado gástrico, una reducción de la liberación de glucagón postprandial y la señalización de saciedad en regiones cerebrales como el área postrema. La lipidación de ácidos grasos de la molécula extiende sustancialmente su duración de acción en comparación con la hormona natural amilina, permitiendo la administración semanal en el entorno del ensayo.","mechanismus_en":"La cagrilintida se une a los receptores de amilina en el cerebro, principalmente los subtipos AMY1 y AMY3 formados por el receptor de calcitonina junto con proteínas RAMP accesorias. Esto se ha relacionado con una ralentización del vaciado gástrico, una reducción de la liberación de glucagón postprandial y la señalización de saciedad en regiones cerebrales como el área postrema. La lipidación de ácidos grasos de la molécula extiende sustancialmente su duración de acción en comparación con la hormona natural amilina, permitiendo la administración semanal en el entorno del ensayo.","evidenz":[{"art":"clínico","kurz":"En un ensayo aleatorizado de fase 2 que probó varias cantidades en 706 adultos con sobrepeso u obesidad, cagrilintida solo durante 26 semanas condujo a una pérdida de peso corporal media del 10,8 por ciento en la mayor cantidad probada, en comparación con alrededor del 3 por ciento bajo placebo.","kurz_en":"En un ensayo aleatorizado de fase 2 que probó varias cantidades en 706 adultos con sobrepeso u obesidad, cagrilintida solo durante 26 semanas condujo a una pérdida de peso corporal media del 10,8 por ciento en la mayor cantidad probada, en comparación con alrededor del 3 por ciento bajo placebo.","quelle":"Lau DCW et al. 2021, The Lancet 398:2160-2172, PMID 34798060"},{"art":"clínico","kurz":"En el ensayo de fase 3 REDEFINE 1, el brazo de cagrilintida solo a 2,4 mg semanal logró una pérdida de peso corporal de alrededor del 11,8 por ciento después de 68 semanas, en comparación con el 2,3 por ciento bajo placebo.","kurz_en":"En el ensayo de fase 3 REDEFINE 1, el brazo de cagrilintida solo a 2,4 mg semanal logró una pérdida de peso corporal de alrededor del 11,8 por ciento después de 68 semanas, en comparación con el 2,3 por ciento bajo placebo.","quelle":"Garvey WT et al. 2025, New England Journal of Medicine 393:625-638, PMID 40544433"},{"art":"preclínico","kurz":"En un modelo murino de obesidad inducida por dieta, el efecto de reducción de peso corporal de cagrilintida dependió de los receptores de amilina cerebral AMY1 y AMY3, y el efecto estuvo ausente en animales con eliminación de receptores.","kurz_en":"En un modelo murino de obesidad inducida por dieta, el efecto de reducción de peso corporal de cagrilintida dependió de los receptores de amilina cerebral AMY1 y AMY3, y el efecto estuvo ausente en animales con eliminación de receptores.","quelle":"Carvas AO et al. 2025, eBioMedicine, PMID 40609154"},{"art":"preclínico","kurz":"La optimización estructural con lipidación de ácidos grasos dio a cagrilintida una vida media sustancialmente más larga de aproximadamente 159 a 195 horas que la hormona propia del cuerpo amilina, permitiendo la administración semanal en el entorno del ensayo.","kurz_en":"La optimización estructural con lipidación de ácidos grasos dio a cagrilintida una vida media sustancialmente más larga de aproximadamente 159 a 195 horas que la hormona propia del cuerpo amilina, permitiendo la administración semanal en el entorno del ensayo.","quelle":"Kruse T et al. 2021, Journal of Medicinal Chemistry 64:11183-11194, PMID 34288673"}],"sicherheit":["En el ensayo aleatorizado de fase 2 con cagrilintida como única sustancia, los efectos gastrointestinales ocurrieron en el 41 a 63 por ciento de los participantes, en comparación con el 32 por ciento bajo placebo, más comúnmente náuseas.","En el ensayo combinado de fase 1b con cantidades crecientes de cagrilintida junto con semaglutida, los efectos gastrointestinales se describieron como la categoría de evento adverso más frecuente, con un perfil de seguridad general manejable.","Como agonista del receptor de amilina, se ha descrito un vaciado gástrico ralentizado, un mecanismo que también contribuye a los efectos gastrointestinales con los compuestos GLP-1.","Dado que la cagrilintida no está aprobada como medicamento por sí solo en ninguna parte, no existe información oficial de prescripción sobre seguridad a largo plazo."],"sicherheit_en":["En el ensayo aleatorizado de fase 2 con cagrilintida como única sustancia, los efectos gastrointestinales ocurrieron en el 41 a 63 por ciento de los participantes, en comparación con el 32 por ciento bajo placebo, más comúnmente náuseas.","En el ensayo combinado de fase 1b con cantidades crecientes de cagrilintida junto con semaglutida, los efectos gastrointestinales se describieron como la categoría de evento adverso más frecuente, con un perfil de seguridad general manejable.","Como agonista del receptor de amilina, se ha descrito un vaciado gástrico ralentizado, un mecanismo que también contribuye a los efectos gastrointestinales con los compuestos GLP-1.","Dado que la cagrilintida no está aprobada como medicamento por sí solo en ninguna parte, no existe información oficial de prescripción sobre seguridad a largo plazo."],"hinweise":["Solo con fines de investigación, no apto para uso en humanos","Un certificado de análisis no establece idoneidad médica"],"hinweise_en":["Solo con fines de investigación, no apto para uso en humanos","Un certificado de análisis no establece idoneidad médica"],"rekonstitution":"Las condiciones específicas de cada producto figuran en la documentación original del fabricante. Este portal no ofrece instrucciones de preparación ni de uso en humanos.","rekonstitution_en":"Las condiciones específicas de cada producto figuran en la documentación original del fabricante. Este portal no ofrece instrucciones de preparación ni de uso en humanos.","lagerung":"Las condiciones específicas de cada producto figuran en la documentación original del fabricante. Este portal no ofrece instrucciones de preparación ni de uso en humanos.","lagerung_en":"Las condiciones específicas de cada producto figuran en la documentación original del fabricante. Este portal no ofrece instrucciones de preparación ni de uso en humanos.","rechtsstatus":"La cagrilintida se encuentra actualmente en ensayos de fase 3 tanto como sustancia independiente como en combinación fija con semaglutida bajo el nombre CagriSema, y aún no ha sido aprobada como medicamento en la UE ni en los Estados Unidos. En diciembre de 2025, se presentó una nueva solicitud de medicamento para la combinación CagriSema a la FDA de EE. UU., con una decisión esperada en 2026. La cagrilintida se vende exclusivamente como producto químico de investigación.","rechtsstatus_en":"La cagrilintida se encuentra actualmente en ensayos de fase 3 tanto como sustancia independiente como en combinación fija con semaglutida bajo el nombre CagriSema, y aún no ha sido aprobada como medicamento en la UE ni en los Estados Unidos. En diciembre de 2025, se presentó una nueva solicitud de medicamento para la combinación CagriSema a la FDA de EE. UU., con una decisión esperada en 2026. La cagrilintida se vende exclusivamente como producto químico de investigación.","typischeMg":[5,10],"faq":[{"q":"¿Está cagrilintida ya disponible como medicamento?","a":"No. La cagrilintida está siendo estudiada como sustancia independiente y en la combinación CagriSema en ensayos de fase 3. Un proceso de aprobación de la FDA para CagriSema ha estado en curso desde diciembre de 2025. La cagrilintida actualmente no es un medicamento aprobado.","q_en":"¿Está cagrilintida ya disponible como medicamento?","a_en":"No. La cagrilintida está siendo estudiada como sustancia independiente y en la combinación CagriSema en ensayos de fase 3. Un proceso de aprobación de la FDA para CagriSema ha estado en curso desde diciembre de 2025. La cagrilintida actualmente no es un medicamento aprobado."},{"q":"¿Qué diferencia a cagrilintida de semaglutida?","a":"La semaglutida actúa sobre el receptor GLP-1, mientras que la cagrilintida actúa sobre los receptores de amilina en el cerebro. Ambos compuestos también se estudian como una combinación fija llamada CagriSema, que mostró un mayor efecto en el peso corporal en los ensayos que ninguna de las sustancias por separado.","q_en":"¿Qué diferencia a cagrilintida de semaglutida?","a_en":"La semaglutida actúa sobre el receptor GLP-1, mientras que la cagrilintida actúa sobre los receptores de amilina en el cerebro. Ambos compuestos también se estudian como una combinación fija llamada CagriSema, que mostró un mayor efecto en el peso corporal en los ensayos que ninguna de las sustancias por separado."},{"q":"¿De dónde proviene cagrilintida?","a":"La cagrilintida fue desarrollada por la compañía farmacéutica Novo Nordisk, que también desarrolló semaglutida. Se referencia bajo las designaciones cortas AM833 y NN9838 en ensayos clínicos, incluido el programa de ensayos REDEFINE.","q_en":"¿De dónde proviene cagrilintida?","a_en":"La cagrilintida fue desarrollada por la compañía farmacéutica Novo Nordisk, que también desarrolló semaglutida. Se referencia bajo las designaciones cortas AM833 y NN9838 en ensayos clínicos, incluido el programa de ensayos REDEFINE."}],"seo":{"title":"Cagrilintida: Análogo de Amilina en Ensayos de Fase 3","title_en":"Cagrilintida: Análogo de Amilina en Ensayos de Fase 3","description":"Cagrilintida de un vistazo: mecanismo, estado del estudio y perfil de seguridad del análogo de amilina, estudiado solo y en la combinación CagriSema.","description_en":"Cagrilintida de un vistazo: mecanismo, estado del estudio y perfil de seguridad del análogo de amilina, estudiado solo y en la combinación CagriSema."},"demo":false,"steckbrief":{"cas":"1415456-99-3","molekulargewicht":"4409 g/mol","aminosaeuren":37,"halbwertszeit":null,"reinheitsstandard":"≥ 98 % (HPLC, estándar comercial)","loeslichkeit":null,"sequenzLaenge":37,"quellen":["PubChem CID 171397054","chemverify Katalog 14.09.2026"],"reinheitsstandard_en":"≥ 98 % (HPLC, estándar comercial)"},"verwandt":["semaglutid","tirzepatid","retatrutid","survodutid"]},{"slug":"mots-c","name":"MOTS-c","synonyme":["Péptido Derivado Mitocondrial MOTS-c","Marco de Lectura Abierta Mitocondrial del rRNA 12S Tipo-c"],"kategorie":"Stoffwechsel","studienlage":"frühe klinische Studien","kurz":"Un péptido codificado mitocondriamente estudiado como mímico de ejercicio en investigación metabólica.","kurz_en":"Un péptido codificado mitocondriamente estudiado como mímico de ejercicio en investigación metabólica.","beschreibung":"MOTS-c es un péptido de 16 aminoácidos codificado directamente en el ADN mitocondrial en lugar del núcleo celular. Fue descubierto en 2015 y se estudia como una molécula de señalización endógena que se libera en mayores cantidades durante el esfuerzo físico. La investigación se centra en posibles efectos sobre la sensibilidad a la insulina, el metabolismo de la grasa y el envejecimiento celular.","beschreibung_en":"MOTS-c es un péptido de 16 aminoácidos codificado directamente en el ADN mitocondrial en lugar del núcleo celular. Fue descubierto en 2015 y se estudia como una molécula de señalización endógena que se libera en mayores cantidades durante el esfuerzo físico. La investigación se centra en posibles efectos sobre la sensibilidad a la insulina, el metabolismo de la grasa y el envejecimiento celular.","mechanismus":"MOTS-c inhibe el ciclo del folato de la célula, lo que provoca que se acumule la molécula mensajera AICAR y active el sensor de energía central AMPK. Esta vía estimula, entre otras cosas, la captación de glucosa en las células musculares y la oxidación de ácidos grasos. Bajo estrés metabólico, MOTS-c también se desplaza al núcleo de la célula, donde influye en la expresión de genes implicados en la adaptación al estrés.","mechanismus_en":"MOTS-c inhibe el ciclo del folato de la célula, lo que provoca que se acumule la molécula mensajera AICAR y active el sensor de energía central AMPK. Esta vía estimula, entre otras cosas, la captación de glucosa en las células musculares y la oxidación de ácidos grasos. Bajo estrés metabólico, MOTS-c también se desplaza al núcleo de la célula, donde influye en la expresión de genes implicados en la adaptación al estrés.","evidenz":[{"art":"preclínico","kurz":"En la descripción original, MOTS-c previno el desarrollo de resistencia a la insulina en ratones con dieta alta en grasa durante varias semanas y restauró la sensibilidad a la insulina de animales jóvenes en ratones viejos.","kurz_en":"En la descripción original, MOTS-c previno el desarrollo de resistencia a la insulina en ratones con dieta alta en grasa durante varias semanas y restauró la sensibilidad a la insulina de animales jóvenes en ratones viejos.","quelle":"Lee et al. 2015, Cell Metabolism 21(3):443-454"},{"art":"preclínico","kurz":"En ratones mayores, la administración repetida de MOTS-c durante varias semanas extendió la esperanza de vida media en 5 a 7 por ciento y mejoró la resistencia, la fuerza de agarre y el equilibrio en comparación con el placebo.","kurz_en":"En ratones mayores, la administración repetida de MOTS-c durante varias semanas extendió la esperanza de vida media en 5 a 7 por ciento y mejoró la resistencia, la fuerza de agarre y el equilibrio en comparación con el placebo.","quelle":"Reynolds et al. 2021, Nature Communications, DOI 10.1038/s41467-020-20790-0"},{"art":"clínico","kurz":"En un estudio observacional de 20 adultos físicamente activos, los niveles séricos de MOTS-c se correlacionaron positivamente con la potencia de salto, la fuerza máxima y la masa muscular de las piernas, pero no con la captación máxima de oxígeno.","kurz_en":"En un estudio observacional de 20 adultos físicamente activos, los niveles séricos de MOTS-c se correlacionaron positivamente con la potencia de salto, la fuerza máxima y la masa muscular de las piernas, pero no con la captación máxima de oxígeno.","quelle":"Domin et al. 2023, International Journal of Molecular Sciences"}],"sicherheit":["Estudios animales publicados de hasta seis meses no reportaron efectos secundarios relevantes.","El efecto más comúnmente reportado es una reacción en el sitio de inyección local como ardor y enrojecimiento.","MOTS-c inhibe el ciclo folato; una posible deficiencia de folato con uso prolongado solo se ha descrito teóricamente hasta ahora.","Los ensayos controlados de intervención humana sobre eficacia y seguridad aún no están disponibles."],"sicherheit_en":["Estudios animales publicados de hasta seis meses no reportaron efectos secundarios relevantes.","El efecto más comúnmente reportado es una reacción en el sitio de inyección local como ardor y enrojecimiento.","MOTS-c inhibe el ciclo folato; una posible deficiencia de folato con uso prolongado solo se ha descrito teóricamente hasta ahora.","Los ensayos controlados de intervención humana sobre eficacia y seguridad aún no están disponibles."],"hinweise":["Solo con fines de investigación, no apto para uso en humanos","Un certificado de análisis no establece idoneidad médica"],"hinweise_en":["Solo con fines de investigación, no apto para uso en humanos","Un certificado de análisis no establece idoneidad médica"],"rekonstitution":"Las condiciones específicas de cada producto figuran en la documentación original del fabricante. Este portal no ofrece instrucciones de preparación ni de uso en humanos.","rekonstitution_en":"Las condiciones específicas de cada producto figuran en la documentación original del fabricante. Este portal no ofrece instrucciones de preparación ni de uso en humanos.","lagerung":"Las condiciones específicas de cada producto figuran en la documentación original del fabricante. Este portal no ofrece instrucciones de preparación ni de uso en humanos.","lagerung_en":"Las condiciones específicas de cada producto figuran en la documentación original del fabricante. Este portal no ofrece instrucciones de preparación ni de uso en humanos.","rechtsstatus":"MOTS-c no está aprobado como medicamento ni producto alimenticio ni en la UE ni en EE. UU. Se vende exclusivamente como químico de investigación y no está destinado al uso humano.","rechtsstatus_en":"MOTS-c no está aprobado como medicamento ni producto alimenticio ni en la UE ni en EE. UU. Se vende exclusivamente como químico de investigación y no está destinado al uso humano.","typischeMg":[5,10],"faq":[{"q":"Qué diferencia a MOTS-c de otros péptidos","a":"MOTS-c está codificado directamente en el ADN mitocondrial en lugar del núcleo de la célula. Actúa a través del sensor de energía celular AMPK y por lo tanto se clasifica como un mimetizador del ejercicio.","q_en":"Qué diferencia a MOTS-c de otros péptidos","a_en":"MOTS-c está codificado directamente en el ADN mitocondrial en lugar del núcleo de la célula. Actúa a través del sensor de energía celular AMPK y por lo tanto se clasifica como un mimetizador del ejercicio."},{"q":"¿Es MOTS-c un medicamento aprobado","a":"No. MOTS-c no está aprobado como medicamento ni producto alimenticio ni en la UE ni en EE. UU. y se vende exclusivamente como químico de investigación.","q_en":"¿Es MOTS-c un medicamento aprobado","a_en":"No. MOTS-c no está aprobado como medicamento ni producto alimenticio ni en la UE ni en EE. UU. y se vende exclusivamente como químico de investigación."},{"q":"¿Qué tan robustos son los datos humanos sobre MOTS-c","a":"Limitados hasta ahora. La evidencia consiste principalmente en estudios animales preclínicos y un estudio observacional humano sobre correlación con la fuerza muscular; todavía faltan ensayos controlados de intervención humana.","q_en":"¿Qué tan robustos son los datos humanos sobre MOTS-c","a_en":"Limitados hasta ahora. La evidencia consiste principalmente en estudios animales preclínicos y un estudio observacional humano sobre correlación con la fuerza muscular; todavía faltan ensayos controlados de intervención humana."}],"seo":{"title":"Resumen de investigación sobre MOTS-c","title_en":"Resumen de investigación sobre MOTS-c","description":"MOTS-c explicado factual: mecanismo de acción mitocondrial, datos de estudios preclínicos y clínicos, y estado legal del péptido.","description_en":"MOTS-c explicado factual: mecanismo de acción mitocondrial, datos de estudios preclínicos y clínicos, y estado legal del péptido."},"demo":false,"steckbrief":{"cas":"1627580-64-6","molekulargewicht":"2174.6 g/mol","aminosaeuren":16,"halbwertszeit":null,"reinheitsstandard":"≥ 98 % (HPLC, estándar comercial)","loeslichkeit":null,"sequenzLaenge":16,"quellen":["PubChem CID 146675088","chemverify Katalog 14.09.2026"],"reinheitsstandard_en":"≥ 98 % (HPLC, estándar comercial)"},"verwandt":["semaglutid","ss-31","aod-9604","5-amino-1mq"]},{"slug":"retatrutid","name":"Retatrutida","synonyme":["LY3437943"],"kategorie":"Stoffwechsel","studienlage":"klinisch untersucht","kurz":"Un péptido que actúa simultáneamente sobre los receptores GLP-1, GIP y glucagón, actualmente en ensayos clínicos avanzados relacionados con la regulación metabólica.","kurz_en":"Un péptido que actúa simultáneamente sobre los receptores GLP-1, GIP y glucagón, actualmente en ensayos clínicos avanzados relacionados con la regulación metabólica.","beschreibung":"Retatrutida es un agonista triple que actúa a la vez sobre tres receptores metabólicos: GLP-1, GIP y glucagón. El fabricante, Eli Lilly, comunicó el 23 de julio de 2026 resultados preliminares (topline) de fase 3 y ha anunciado que presentará la solicitud ante la autoridad estadounidense FDA en el 1.er trimestre de 2027. Retatrutida es una molécula en investigación y hasta la fecha no está autorizada como medicamento en ningún país.","beschreibung_en":"Retatrutida es un agonista triple que actúa a la vez sobre tres receptores metabólicos: GLP-1, GIP y glucagón. El fabricante, Eli Lilly, comunicó el 23 de julio de 2026 resultados preliminares (topline) de fase 3 y ha anunciado que presentará la solicitud ante la autoridad estadounidense FDA en el 1.er trimestre de 2027. Retatrutida es una molécula en investigación y hasta la fecha no está autorizada como medicamento en ningún país.","mechanismus":"A través del receptor GLP-1, se han descrito efectos en la regulación de la saciedad y la ralentización del vaciado gástrico. El receptor GIP se ha relacionado con una secreción de insulina mejorada y un posible amortiguamiento de los efectos gastrointestinales. La acción adicional en el receptor de glucagón se ha asociado con un aumento del gasto energético hepático y la activación del tejido adiposo marrón.","mechanismus_en":"A través del receptor GLP-1, se han descrito efectos en la regulación de la saciedad y la ralentización del vaciado gástrico. El receptor GIP se ha relacionado con una secreción de insulina mejorada y un posible amortiguamiento de los efectos gastrointestinales. La acción adicional en el receptor de glucagón se ha asociado con un aumento del gasto energético hepático y la activación del tejido adiposo marrón.","evidenz":[{"art":"clínico","kurz":"En un ensayo aleatorizado de fase 2 en adultos con obesidad, una proporción marcadamente mayor de participantes en retatrutida logró una pérdida de peso corporal relevante después de 48 semanas en comparación con el placebo.","kurz_en":"En un ensayo aleatorizado de fase 2 en adultos con obesidad, una proporción marcadamente mayor de participantes en retatrutida logró una pérdida de peso corporal relevante después de 48 semanas en comparación con el placebo.","quelle":"Jastreboff AM et al. 2023, New England Journal of Medicine 389:514-526, PMID 37366315"},{"art":"clínico","kurz":"En un subestudio con participantes con enfermedad hepática grasa concurrente, se observó una reducción medida por RM del contenido de grasa hepática que aumentó con la cantidad administrada después de 24 semanas.","kurz_en":"En un subestudio con participantes con enfermedad hepática grasa concurrente, se observó una reducción medida por RM del contenido de grasa hepática que aumentó con la cantidad administrada después de 24 semanas.","quelle":"Sanyal AJ et al. 2024, Nature Medicine"},{"art":"clínico","kurz":"En un ensayo de fase 2 en personas con diabetes tipo 2, retatrutida redujo la HbA1c más que el comparador activo dulaglutide, junto con una mayor pérdida de peso corporal.","kurz_en":"En un ensayo de fase 2 en personas con diabetes tipo 2, retatrutida redujo la HbA1c más que el comparador activo dulaglutide, junto con una mayor pérdida de peso corporal.","quelle":"Rosenstock J et al. 2023, The Lancet 402:529-544, PMID 37385280"}],"sicherheit":["Los efectos más comúnmente reportados en los ensayos son gastrointestinales, incluyendo náuseas y diarrea, y disminuyen a lo largo de los estudios.","En la cantidad más alta, los ensayos observaron una mayor tasa de interrupción en comparación con el placebo.","En un ensayo de fase 3, algunos participantes en el grupo de cantidad más alta reportaron disestesia (hormigueo o entumecimiento en las extremidades), resolviéndose en su mayoría a lo largo del estudio.","Dado que la retatrutida no está aprobada como medicamento en ninguna parte, no existe información oficial de prescripción sobre seguridad a largo plazo."],"sicherheit_en":["Los efectos más comúnmente reportados en los ensayos son gastrointestinales, incluyendo náuseas y diarrea, y disminuyen a lo largo de los estudios.","En la cantidad más alta, los ensayos observaron una mayor tasa de interrupción en comparación con el placebo.","En un ensayo de fase 3, algunos participantes en el grupo de cantidad más alta reportaron disestesia (hormigueo o entumecimiento en las extremidades), resolviéndose en su mayoría a lo largo del estudio.","Dado que la retatrutida no está aprobada como medicamento en ninguna parte, no existe información oficial de prescripción sobre seguridad a largo plazo."],"hinweise":["Solo con fines de investigación, no apto para uso en humanos","Un certificado de análisis no establece idoneidad médica"],"hinweise_en":["Solo con fines de investigación, no apto para uso en humanos","Un certificado de análisis no establece idoneidad médica"],"rekonstitution":"Las condiciones específicas de cada producto figuran en la documentación original del fabricante. Este portal no ofrece instrucciones de preparación ni de uso en humanos.","rekonstitution_en":"Las condiciones específicas de cada producto figuran en la documentación original del fabricante. Este portal no ofrece instrucciones de preparación ni de uso en humanos.","lagerung":"Las condiciones específicas de cada producto figuran en la documentación original del fabricante. Este portal no ofrece instrucciones de preparación ni de uso en humanos.","lagerung_en":"Las condiciones específicas de cada producto figuran en la documentación original del fabricante. Este portal no ofrece instrucciones de preparación ni de uso en humanos.","rechtsstatus":"Retatrutida es una molécula en investigación y no está autorizada como medicamento ni en la UE ni en Estados Unidos. El fabricante, Eli Lilly, comunicó el 23 de julio de 2026 resultados preliminares (topline) de fase 3 y ha anunciado que presentará la solicitud ante la FDA en el 1.er trimestre de 2027. Presentar una solicitud no equivale a una autorización. Se vende exclusivamente como producto químico de investigación.","rechtsstatus_en":"Retatrutida es una molécula en investigación y no está autorizada como medicamento ni en la UE ni en Estados Unidos. El fabricante, Eli Lilly, comunicó el 23 de julio de 2026 resultados preliminares (topline) de fase 3 y ha anunciado que presentará la solicitud ante la FDA en el 1.er trimestre de 2027. Presentar una solicitud no equivale a una autorización. Se vende exclusivamente como producto químico de investigación.","typischeMg":[5,10,15],"faq":[{"q":"¿Está retatrutida ya disponible como medicamento?","a":"No. El fabricante, Eli Lilly, comunicó el 23 de julio de 2026 resultados preliminares (topline) de fase 3 y ha anunciado que presentará la solicitud ante la FDA en el 1.er trimestre de 2027. Retatrutida es una molécula en investigación y actualmente no es un medicamento autorizado.","q_en":"¿Está retatrutida ya disponible como medicamento?","a_en":"No. El fabricante, Eli Lilly, comunicó el 23 de julio de 2026 resultados preliminares (topline) de fase 3 y ha anunciado que presentará la solicitud ante la FDA en el 1.er trimestre de 2027. Retatrutida es una molécula en investigación y actualmente no es un medicamento autorizado."},{"q":"¿Qué diferencia a retatrutida de semaglutida?","a":"La semaglutida actúa solo sobre el receptor GLP-1, mientras que la retatrutida actúa adicionalmente sobre los receptores GIP y glucagón. Los ensayos clínicos mostraron un efecto mayor en el peso corporal y la grasa hepática como resultado.","q_en":"¿Qué diferencia a retatrutida de semaglutida?","a_en":"La semaglutida actúa solo sobre el receptor GLP-1, mientras que la retatrutida actúa adicionalmente sobre los receptores GIP y glucagón. Los ensayos clínicos mostraron un efecto mayor en el peso corporal y la grasa hepática como resultado."},{"q":"¿De dónde viene retatrutida?","a":"Retatrutida fue desarrollada por la farmacéutica Eli Lilly y se estudia en el programa de fase 3 TRIUMPH, del que se comunicaron resultados preliminares (topline) en 2026.","q_en":"¿De dónde viene retatrutida?","a_en":"Retatrutida fue desarrollada por la farmacéutica Eli Lilly y se estudia en el programa de fase 3 TRIUMPH, del que se comunicaron resultados preliminares (topline) en 2026."}],"seo":{"title":"Retatrutida: agonista triple, resultados de fase 3 comunicados","title_en":"Retatrutida: agonista triple, resultados de fase 3 comunicados","description":"Retatrutida de un vistazo: mecanismo, estado del estudio y perfil de seguridad del agonista triple GLP-1/GIP/glucagón en ensayos clínicos avanzados.","description_en":"Retatrutida de un vistazo: mecanismo, estado del estudio y perfil de seguridad del agonista triple GLP-1/GIP/glucagón en ensayos clínicos avanzados."},"demo":false,"steckbrief":{"cas":"2381989-03-1","molekulargewicht":"~4600 g/mol","aminosaeuren":39,"halbwertszeit":null,"reinheitsstandard":"≥ 98 % (HPLC, estándar comercial)","loeslichkeit":"soluble en agua estéril o agua bacteriostática","sequenzLaenge":39,"quellen":["chemverify Katalog 14.09.2026 (PubChem: kein Eintrag)"],"reinheitsstandard_en":"≥ 98 % (HPLC, estándar comercial)","loeslichkeit_en":"soluble en agua estéril o agua bacteriostática"},"verwandt":["semaglutid","tirzepatid","cagrilintid","survodutid"]},{"slug":"semaglutid","name":"Semaglutida","synonyme":[],"kategorie":"Stoffwechsel","studienlage":"zugelassenes Arzneimittel","kurz":"Un agonista del receptor GLP-1, conocido como medicamento aprobado y listado aquí como sustancia de investigación para la regulación metabólica.","kurz_en":"Un agonista del receptor GLP-1, conocido como medicamento aprobado y listado aquí como sustancia de investigación para la regulación metabólica.","beschreibung":"La semaglutida es un agonista del receptor GLP-1 aprobado como medicamento bajo varios nombres comerciales. Es objeto de investigación clínica exhaustiva sobre la regulación metabólica y la saciedad. Los lotes de investigación listados aquí no son equivalentes a medicamentos aprobados y están destinados únicamente para uso de laboratorio.","beschreibung_en":"La semaglutida es un agonista del receptor GLP-1 aprobado como medicamento bajo varios nombres comerciales. Es objeto de investigación clínica exhaustiva sobre la regulación metabólica y la saciedad. Los lotes de investigación listados aquí no son equivalentes a medicamentos aprobados y están destinados únicamente para uso de laboratorio.","mechanismus":"La semaglutida activa el receptor GLP-1, que influye en la regulación del hambre en el hipotálamo, ralentiza el vaciado gástrico y estimula la liberación de insulina de manera dependiente de la glucosa. Esta acción dependiente de la glucosa se describe como la razón de su menor riesgo de hipoglucemia en comparación con la insulina.","mechanismus_en":"La semaglutida activa el receptor GLP-1, que influye en la regulación del hambre en el hipotálamo, ralentiza el vaciado gástrico y estimula la liberación de insulina de manera dependiente de la glucosa. Esta acción dependiente de la glucosa se describe como la razón de su menor riesgo de hipoglucemia en comparación con la insulina.","evidenz":[{"art":"clínico","kurz":"En un ensayo aleatorizado con 1.961 adultos con sobrepeso u obesidad, la semaglutida semanal durante 68 semanas condujo a una pérdida de peso corporal media del 14,9 por ciento frente a un 2,4 por ciento en el placebo.","kurz_en":"En un ensayo aleatorizado con 1.961 adultos con sobrepeso u obesidad, la semaglutida semanal durante 68 semanas condujo a una pérdida de peso corporal media del 14,9 por ciento frente a un 2,4 por ciento en el placebo.","quelle":"Wilding JPH et al. 2021, New England Journal of Medicine, PMID 33567185"},{"art":"clínico","kurz":"En un ensayo de resultados cardiovasculares con 3 297 personas con diabetes de tipo 2 y riesgo cardiovascular elevado, semaglutida se asoció con una tasa un 26 % menor de eventos cardiovasculares mayores en comparación con placebo.","kurz_en":"En un ensayo de resultados cardiovasculares con 3 297 personas con diabetes de tipo 2 y riesgo cardiovascular elevado, semaglutida se asoció con una tasa un 26 % menor de eventos cardiovasculares mayores en comparación con placebo.","quelle":"Marso SP et al. 2016, New England Journal of Medicine 375:1834-1844, PMID 27633186"}],"sicherheit":["Los efectos comúnmente reportados son gastrointestinales, particularmente náuseas, diarrea y vómitos, en su mayoría transitorios durante el curso del uso.","Los casos raros discutidos en la literatura incluyen un posible vínculo con neuropatía óptica isquémica anterior no arterítica.","Según la información de prescripción, el uso está contraindicado en personas con antecedentes personales o familiares de carcinoma tiroideo medular."],"sicherheit_en":["Los efectos comúnmente reportados son gastrointestinales, particularmente náuseas, diarrea y vómitos, en su mayoría transitorios durante el curso del uso.","Los casos raros discutidos en la literatura incluyen un posible vínculo con neuropatía óptica isquémica anterior no arterítica.","Según la información de prescripción, el uso está contraindicado en personas con antecedentes personales o familiares de carcinoma tiroideo medular."],"hinweise":["Solo con fines de investigación, no apto para uso en humanos","Un certificado de análisis no establece idoneidad médica"],"hinweise_en":["Solo con fines de investigación, no apto para uso en humanos","Un certificado de análisis no establece idoneidad médica"],"rekonstitution":"Las condiciones específicas de cada producto figuran en la documentación original del fabricante. Este portal no ofrece instrucciones de preparación ni de uso en humanos.","rekonstitution_en":"Las condiciones específicas de cada producto figuran en la documentación original del fabricante. Este portal no ofrece instrucciones de preparación ni de uso en humanos.","lagerung":"Las condiciones específicas de cada producto figuran en la documentación original del fabricante. Este portal no ofrece instrucciones de preparación ni de uso en humanos.","lagerung_en":"Las condiciones específicas de cada producto figuran en la documentación original del fabricante. Este portal no ofrece instrucciones de preparación ni de uso en humanos.","rechtsstatus":"La semaglutida está aprobada como medicamento bajo los nombres Ozempic, Wegovy y Rybelsus en la UE y Estados Unidos para el tratamiento de la diabetes tipo 2 y para el control de peso, y está disponible solo por receta. Los lotes de investigación descritos aquí no son equivalentes a los productos farmacéuticos terminados aprobados.","rechtsstatus_en":"La semaglutida está aprobada como medicamento bajo los nombres Ozempic, Wegovy y Rybelsus en la UE y Estados Unidos para el tratamiento de la diabetes tipo 2 y para el control de peso, y está disponible solo por receta. Los lotes de investigación descritos aquí no son equivalentes a los productos farmacéuticos terminados aprobados.","typischeMg":[2,5],"faq":[{"q":"¿Es semaglutida un medicamento aprobado?","a":"Sí, la semaglutida está aprobada como medicamento de prescripción bajo los nombres Ozempic, Wegovy y Rybelsus. La sustancia descrita aquí es solo un lote de investigación, no un producto farmacéutico terminado.","q_en":"¿Es semaglutida un medicamento aprobado?","a_en":"Sí, la semaglutida está aprobada como medicamento de prescripción bajo los nombres Ozempic, Wegovy y Rybelsus. La sustancia descrita aquí es solo un lote de investigación, no un producto farmacéutico terminado."},{"q":"¿En qué se diferencia semaglutida de retatrutida?","a":"La semaglutida actúa solo sobre el receptor GLP-1, mientras que retatrutida actúa además sobre los receptores GIP y de glucagón. Retatrutida es una molécula en investigación y aún no está autorizada, mientras que la semaglutida ya lo está.","q_en":"¿En qué se diferencia semaglutida de retatrutida?","a_en":"La semaglutida actúa solo sobre el receptor GLP-1, mientras que retatrutida actúa además sobre los receptores GIP y de glucagón. Retatrutida es una molécula en investigación y aún no está autorizada, mientras que la semaglutida ya lo está."},{"q":"¿Para qué se utiliza semaglutida como medicamento?","a":"Como medicamento aprobado, semaglutida se prescribe para la diabetes tipo 2 y el control de peso. Esta página describe la sustancia exclusivamente como un químico de investigación para fines de laboratorio.","q_en":"¿Para qué se utiliza semaglutida como medicamento?","a_en":"Como medicamento aprobado, semaglutida se prescribe para la diabetes tipo 2 y el control de peso. Esta página describe la sustancia exclusivamente como un químico de investigación para fines de laboratorio."}],"seo":{"title":"Semaglutida: Compuesto GLP-1 en un Contexto de Investigación","title_en":"Semaglutida: Compuesto GLP-1 en un Contexto de Investigación","description":"Semaglutida de un vistazo: mecanismo, estado del estudio, perfil de seguridad y estado legal del agonista del receptor GLP-1 aprobado.","description_en":"Semaglutida de un vistazo: mecanismo, estado del estudio, perfil de seguridad y estado legal del agonista del receptor GLP-1 aprobado."},"demo":false,"steckbrief":{"cas":"910463-68-2","molekulargewicht":"4114 g/mol","aminosaeuren":31,"halbwertszeit":"≈ 1 semana (eliminación, información de prescripción de Ozempic)","reinheitsstandard":"≥ 99 % (HPLC, estándar comercial)","loeslichkeit":null,"sequenzLaenge":31,"quellen":["PubChem CID 56843331","DailyMed SPL OZEMPIC (Semaglutid), Novo Nordisk","chemverify Katalog 14.09.2026"],"halbwertszeit_en":"≈ 1 semana (eliminación, información de prescripción de Ozempic)","reinheitsstandard_en":"≥ 99 % (HPLC, estándar comercial)"},"verwandt":["tirzepatid","retatrutid","survodutid","cagrilintid"]},{"slug":"survodutid","name":"Survodutida","synonyme":["BI 456906"],"kategorie":"Stoffwechsel","studienlage":"klinisch untersucht","kurz":"Un péptido que actúa sobre los receptores GLP-1 y glucagón simultáneamente, actualmente en ensayos clínicos avanzados relacionados con la regulación metabólica.","kurz_en":"Un péptido que actúa sobre los receptores GLP-1 y glucagón simultáneamente, actualmente en ensayos clínicos avanzados relacionados con la regulación metabólica.","beschreibung":"La survodutida es un agonista dual de los receptores GLP-1 y glucagón, desarrollado por Boehringer Ingelheim en colaboración con Zealand Pharma. Se está estudiando en ensayos de fase 3 para la regulación del peso en la obesidad así como en la esteatohepatitis asociada a la disfunción metabólica (MASH), y no está aprobada como medicamento en ningún país hasta la fecha.","beschreibung_en":"La survodutida es un agonista dual de los receptores GLP-1 y glucagón, desarrollado por Boehringer Ingelheim en colaboración con Zealand Pharma. Se está estudiando en ensayos de fase 3 para la regulación del peso en la obesidad así como en la esteatohepatitis asociada a la disfunción metabólica (MASH), y no está aprobada como medicamento en ningún país hasta la fecha.","mechanismus":"A través del receptor GLP-1, se ha descrito un aumento de la saciedad y una ralentización del vaciado gástrico. La activación adicional del receptor de glucagón se ha relacionado con un aumento del gasto energético hepático y una reducción del contenido de grasa hepática. Esta acción dual distingue a survodutida de los agonistas puros del GLP-1.","mechanismus_en":"A través del receptor GLP-1, se ha descrito un aumento de la saciedad y una ralentización del vaciado gástrico. La activación adicional del receptor de glucagón se ha relacionado con un aumento del gasto energético hepático y una reducción del contenido de grasa hepática. Esta acción dual distingue a survodutida de los agonistas puros del GLP-1.","evidenz":[{"art":"clínico","kurz":"En un ensayo aleatorizado de fase 3 con 725 adultos con obesidad sin diabetes, survodutida condujo a una pérdida de peso corporal media del 12 al 13 por ciento después de 76 semanas, en comparación con el 5 por ciento bajo placebo.","kurz_en":"En un ensayo aleatorizado de fase 3 con 725 adultos con obesidad sin diabetes, survodutida condujo a una pérdida de peso corporal media del 12 al 13 por ciento después de 76 semanas, en comparación con el 5 por ciento bajo placebo.","quelle":"Le Roux CW et al. 2026, New England Journal of Medicine, DOI 10.1056/NEJMoa2600751"},{"art":"clínico","kurz":"En un ensayo aleatorizado de fase 2 con 386 adultos con obesidad, survodutida condujo a una pérdida de peso corporal de hasta el 14,9 por ciento en el grupo con mayor cantidad después de 46 semanas, en comparación con el 2,8 por ciento bajo placebo.","kurz_en":"En un ensayo aleatorizado de fase 2 con 386 adultos con obesidad, survodutida condujo a una pérdida de peso corporal de hasta el 14,9 por ciento en el grupo con mayor cantidad después de 46 semanas, en comparación con el 2,8 por ciento bajo placebo.","quelle":"le Roux CW et al. 2024, The Lancet Diabetes & Endocrinology 12:162-173, PMID 38330987"},{"art":"clínico","kurz":"En un ensayo de fase 2 con 293 personas con MASH y fibrosis hepática, hasta el 62 por ciento de los participantes en survodutida mostraron mejoría histológica de MASH sin empeoramiento de la fibrosis después de 48 semanas, en comparación con el 14 por ciento bajo placebo.","kurz_en":"En un ensayo de fase 2 con 293 personas con MASH y fibrosis hepática, hasta el 62 por ciento de los participantes en survodutida mostraron mejoría histológica de MASH sin empeoramiento de la fibrosis después de 48 semanas, en comparación con el 14 por ciento bajo placebo.","quelle":"Sanyal AJ et al. 2024, New England Journal of Medicine, PMID 38847460"}],"sicherheit":["Los efectos más comúnmente reportados en ensayos son gastrointestinales, incluyendo náuseas, diarrea y vómitos, que ocurren con mucha más frecuencia bajo survodutida que bajo placebo.","En el ensayo de obesidad de fase 3, se reportaron síntomas gastrointestinales en hasta el 90 por ciento de los participantes en survodutida frente al 48 por ciento bajo placebo, mayormente leves a moderados.","En el ensayo de MASH de fase 2, se registraron eventos adversos graves en el 8 por ciento de los participantes en survodutida y en el 7 por ciento bajo placebo.","Dado que la survodutida no está aprobada como medicamento en ninguna parte, no existe información oficial de prescripción sobre seguridad a largo plazo."],"sicherheit_en":["Los efectos más comúnmente reportados en ensayos son gastrointestinales, incluyendo náuseas, diarrea y vómitos, que ocurren con mucha más frecuencia bajo survodutida que bajo placebo.","En el ensayo de obesidad de fase 3, se reportaron síntomas gastrointestinales en hasta el 90 por ciento de los participantes en survodutida frente al 48 por ciento bajo placebo, mayormente leves a moderados.","En el ensayo de MASH de fase 2, se registraron eventos adversos graves en el 8 por ciento de los participantes en survodutida y en el 7 por ciento bajo placebo.","Dado que la survodutida no está aprobada como medicamento en ninguna parte, no existe información oficial de prescripción sobre seguridad a largo plazo."],"hinweise":["Solo con fines de investigación, no apto para uso en humanos","Un certificado de análisis no establece idoneidad médica"],"hinweise_en":["Solo con fines de investigación, no apto para uso en humanos","Un certificado de análisis no establece idoneidad médica"],"rekonstitution":"Las condiciones específicas de cada producto figuran en la documentación original del fabricante. Este portal no ofrece instrucciones de preparación ni de uso en humanos.","rekonstitution_en":"Las condiciones específicas de cada producto figuran en la documentación original del fabricante. Este portal no ofrece instrucciones de preparación ni de uso en humanos.","lagerung":"Las condiciones específicas de cada producto figuran en la documentación original del fabricante. Este portal no ofrece instrucciones de preparación ni de uso en humanos.","lagerung_en":"Las condiciones específicas de cada producto figuran en la documentación original del fabricante. Este portal no ofrece instrucciones de preparación ni de uso en humanos.","rechtsstatus":"Survodutida se encuentra actualmente en ensayos de fase 3 para obesidad y MASH y aún no ha sido aprobado como medicamento en la UE ni en Estados Unidos. Según el fabricante, la aprobación de la FDA no se espera antes de 2027; se vende exclusivamente como producto químico de investigación.","rechtsstatus_en":"Survodutida se encuentra actualmente en ensayos de fase 3 para obesidad y MASH y aún no ha sido aprobado como medicamento en la UE ni en Estados Unidos. Según el fabricante, la aprobación de la FDA no se espera antes de 2027; se vende exclusivamente como producto químico de investigación.","typischeMg":[5,10,20],"faq":[{"q":"¿Está survodutida ya disponible como medicamento?","a":"No. Survodutida se encuentra actualmente en ensayos de fase 3; según el fabricante, la aprobación de la FDA no se espera antes de 2027. Actualmente no es un medicamento autorizado.","q_en":"¿Está survodutida ya disponible como medicamento?","a_en":"No. Survodutida se encuentra actualmente en ensayos de fase 3; según el fabricante, la aprobación de la FDA no se espera antes de 2027. Actualmente no es un medicamento autorizado."},{"q":"¿Qué diferencia a survodutida de semaglutida?","a":"La semaglutida actúa solo sobre el receptor GLP-1, mientras que la survodutida actúa adicionalmente sobre el receptor del glucagón. Los ensayos clínicos mostraron que esta acción dual también reduce el contenido de grasa hepática junto con el efecto sobre el peso corporal.","q_en":"¿Qué diferencia a survodutida de semaglutida?","a_en":"La semaglutida actúa solo sobre el receptor GLP-1, mientras que la survodutida actúa adicionalmente sobre el receptor del glucagón. Los ensayos clínicos mostraron que esta acción dual también reduce el contenido de grasa hepática junto con el efecto sobre el peso corporal."},{"q":"¿De dónde proviene survodutida?","a":"La survodutida fue desarrollada por la compañía farmacéutica Boehringer Ingelheim y está siendo estudiada en varios ensayos de fase 3 bajo el nombre del programa SYNCHRONIZE, en parte en colaboración con Zealand Pharma.","q_en":"¿De dónde proviene survodutida?","a_en":"La survodutida fue desarrollada por la compañía farmacéutica Boehringer Ingelheim y está siendo estudiada en varios ensayos de fase 3 bajo el nombre del programa SYNCHRONIZE, en parte en colaboración con Zealand Pharma."}],"seo":{"title":"Survodutida: Agonista Dual en Ensayos de Fase 3","title_en":"Survodutida: Agonista Dual en Ensayos de Fase 3","description":"Survodutida de un vistazo: mecanismo, estado del estudio y perfil de seguridad del agonista dual GLP-1/glucagón en ensayos clínicos avanzados.","description_en":"Survodutida de un vistazo: mecanismo, estado del estudio y perfil de seguridad del agonista dual GLP-1/glucagón en ensayos clínicos avanzados."},"demo":false,"steckbrief":{"cas":"2805997-46-8","molekulargewicht":"4232 g/mol","aminosaeuren":null,"halbwertszeit":null,"reinheitsstandard":null,"loeslichkeit":null,"sequenzLaenge":null,"quellen":["PubChem CID 171378821","chemverify Katalog 14.09.2026 (Aminosäurenzahl/Reinheitsstandard dort nicht geführt)"]},"verwandt":["semaglutid","tirzepatid","retatrutid","cagrilintid"]},{"slug":"tirzepatid","name":"Tirzepatida","synonyme":["LY3298176"],"kategorie":"Stoffwechsel","studienlage":"zugelassenes Arzneimittel","kurz":"Un agonista dual del receptor GIP/GLP-1, conocido como un medicamento aprobado y listado aquí como sustancia de investigación para la regulación metabólica.","kurz_en":"Un agonista dual del receptor GIP/GLP-1, conocido como un medicamento aprobado y listado aquí como sustancia de investigación para la regulación metabólica.","beschreibung":"La tirzepatida es un agonista dual del receptor GIP/GLP-1 aprobado como medicamento bajo los nombres Mounjaro y Zepbound. Es objeto de extensa investigación clínica sobre la regulación metabólica y del peso en la diabetes tipo 2 y la obesidad. Los lotes de investigación enumerados aquí no son equivalentes a los medicamentos aprobados y están destinados únicamente para uso de laboratorio.","beschreibung_en":"La tirzepatida es un agonista dual del receptor GIP/GLP-1 aprobado como medicamento bajo los nombres Mounjaro y Zepbound. Es objeto de extensa investigación clínica sobre la regulación metabólica y del peso en la diabetes tipo 2 y la obesidad. Los lotes de investigación enumerados aquí no son equivalentes a los medicamentos aprobados y están destinados únicamente para uso de laboratorio.","mechanismus":"La tirzepatida activa simultáneamente el receptor GIP y el GLP-1, por lo que se describe como un agonista dual. A través del receptor GLP-1, se han descrito efectos en la regulación de la saciedad en el hipotálamo, la ralentización del vaciado gástrico y la liberación de insulina dependiente de la glucosa. El componente adicional del receptor GIP se ha relacionado con una secreción de insulina mejorada y efectos en el metabolismo lipídico.","mechanismus_en":"La tirzepatida activa simultáneamente el receptor GIP y el GLP-1, por lo que se describe como un agonista dual. A través del receptor GLP-1, se han descrito efectos en la regulación de la saciedad en el hipotálamo, la ralentización del vaciado gástrico y la liberación de insulina dependiente de la glucosa. El componente adicional del receptor GIP se ha relacionado con una secreción de insulina mejorada y efectos en el metabolismo lipídico.","evidenz":[{"art":"clínico","kurz":"En un ensayo aleatorizado con 2.539 adultos con obesidad o sobrepeso, tirzepatida semanal durante 72 semanas condujo a una pérdida de peso corporal media de hasta el 20,9 por ciento (15 mg) frente a un 3,1 por ciento con placebo.","kurz_en":"En un ensayo aleatorizado con 2.539 adultos con obesidad o sobrepeso, tirzepatida semanal durante 72 semanas condujo a una pérdida de peso corporal media de hasta el 20,9 por ciento (15 mg) frente a un 3,1 por ciento con placebo.","quelle":"Jastreboff AM et al. 2022, New England Journal of Medicine, PMID 35658024"},{"art":"clínico","kurz":"En un ensayo aleatorizado cara a cara con 1.879 personas con diabetes tipo 2, tirzepatida redujo la HbA1c en 2,09 a 2,46 puntos porcentuales y el peso corporal en 7,8 a 12,4 kg después de 40 semanas, en cada caso más que semaglutida 1 mg.","kurz_en":"En un ensayo aleatorizado cara a cara con 1.879 personas con diabetes tipo 2, tirzepatida redujo la HbA1c en 2,09 a 2,46 puntos porcentuales y el peso corporal en 7,8 a 12,4 kg después de 40 semanas, en cada caso más que semaglutida 1 mg.","quelle":"Frías JP et al. 2021, New England Journal of Medicine, PMID 34170647"}],"sicherheit":["Los efectos reportados más comunes son gastrointestinales, particularmente náuseas, vómitos y diarrea, con un riesgo de deshidratación en casos pronunciados.","Según la información para prescribir, el uso está contraindicado en personas con antecedentes personales o familiares de carcinoma medular de tiroides o síndrome de neoplasia endocrina múltiple tipo 2.","Estudios en animales en ratas mostraron tumores de células C tiroideas dependientes de la cantidad y la duración de la exposición, y si este hallazgo se traduce en humanos no se ha establecido según la información para prescribir."],"sicherheit_en":["Los efectos reportados más comunes son gastrointestinales, particularmente náuseas, vómitos y diarrea, con un riesgo de deshidratación en casos pronunciados.","Según la información para prescribir, el uso está contraindicado en personas con antecedentes personales o familiares de carcinoma medular de tiroides o síndrome de neoplasia endocrina múltiple tipo 2.","Estudios en animales en ratas mostraron tumores de células C tiroideas dependientes de la cantidad y la duración de la exposición, y si este hallazgo se traduce en humanos no se ha establecido según la información para prescribir."],"hinweise":["Solo con fines de investigación, no apto para uso en humanos","Un certificado de análisis no establece idoneidad médica"],"hinweise_en":["Solo con fines de investigación, no apto para uso en humanos","Un certificado de análisis no establece idoneidad médica"],"rekonstitution":"Las condiciones específicas de cada producto figuran en la documentación original del fabricante. Este portal no ofrece instrucciones de preparación ni de uso en humanos.","rekonstitution_en":"Las condiciones específicas de cada producto figuran en la documentación original del fabricante. Este portal no ofrece instrucciones de preparación ni de uso en humanos.","lagerung":"Las condiciones específicas de cada producto figuran en la documentación original del fabricante. Este portal no ofrece instrucciones de preparación ni de uso en humanos.","lagerung_en":"Las condiciones específicas de cada producto figuran en la documentación original del fabricante. Este portal no ofrece instrucciones de preparación ni de uso en humanos.","rechtsstatus":"La tirzepatida está aprobada como medicamento bajo el nombre Mounjaro en la UE desde septiembre de 2022 para el tratamiento de la diabetes tipo 2, y desde finales de 2023 también para el control de peso. En los Estados Unidos, está aprobado bajo el nombre Mounjaro para el tratamiento de la diabetes tipo 2 y bajo el nombre Zepbound para el control de peso, y está disponible solo por receta en ambas regiones. Los lotes de investigación descritos aquí no son equivalentes a los productos farmacéuticos terminados aprobados.","rechtsstatus_en":"La tirzepatida está aprobada como medicamento bajo el nombre Mounjaro en la UE desde septiembre de 2022 para el tratamiento de la diabetes tipo 2, y desde finales de 2023 también para el control de peso. En los Estados Unidos, está aprobado bajo el nombre Mounjaro para el tratamiento de la diabetes tipo 2 y bajo el nombre Zepbound para el control de peso, y está disponible solo por receta en ambas regiones. Los lotes de investigación descritos aquí no son equivalentes a los productos farmacéuticos terminados aprobados.","typischeMg":[10,30,60],"faq":[{"q":"¿Es tirzepatida un medicamento aprobado?","a":"Sí, la tirzepatida está aprobada como medicamento de prescripción bajo los nombres Mounjaro y Zepbound. La sustancia descrita aquí es solo un lote de investigación, no un producto farmacéutico terminado.","q_en":"¿Es tirzepatida un medicamento aprobado?","a_en":"Sí, la tirzepatida está aprobada como medicamento de prescripción bajo los nombres Mounjaro y Zepbound. La sustancia descrita aquí es solo un lote de investigación, no un producto farmacéutico terminado."},{"q":"¿En qué se diferencia tirzepatida de semaglutida?","a":"La semaglutida actúa solo sobre el receptor GLP-1, mientras que la tirzepatida actúa adicionalmente sobre el receptor GIP. En un ensayo comparativo directo, tirzepatida mostró efectos mayores en HbA1c y peso corporal que semaglutida.","q_en":"¿En qué se diferencia tirzepatida de semaglutida?","a_en":"La semaglutida actúa solo sobre el receptor GLP-1, mientras que la tirzepatida actúa adicionalmente sobre el receptor GIP. En un ensayo comparativo directo, tirzepatida mostró efectos mayores en HbA1c y peso corporal que semaglutida."},{"q":"¿Para qué se utiliza tirzepatida como medicamento?","a":"Como medicamento aprobado, tirzepatida se prescribe para diabetes tipo 2 y control de peso. Esta página describe la sustancia exclusivamente como un químico de investigación para fines de laboratorio.","q_en":"¿Para qué se utiliza tirzepatida como medicamento?","a_en":"Como medicamento aprobado, tirzepatida se prescribe para diabetes tipo 2 y control de peso. Esta página describe la sustancia exclusivamente como un químico de investigación para fines de laboratorio."}],"seo":{"title":"Tirzepatida: Resumen del compuesto dual GIP/GLP-1","title_en":"Tirzepatida: Resumen del compuesto dual GIP/GLP-1","description":"Tirzepatida de un vistazo: mecanismo dual GIP/GLP-1, evidencia de los ensayos SURMOUNT y SURPASS, perfil de seguridad y estado legal del compuesto.","description_en":"Tirzepatida de un vistazo: mecanismo dual GIP/GLP-1, evidencia de los ensayos SURMOUNT y SURPASS, perfil de seguridad y estado legal del compuesto."},"demo":false,"steckbrief":{"cas":"2023788-19-2","molekulargewicht":"4813 g/mol","aminosaeuren":39,"halbwertszeit":"≈ 5 días (eliminación, información de prescripción de Mounjaro)","reinheitsstandard":"≥ 99 % (HPLC, estándar comercial)","loeslichkeit":null,"sequenzLaenge":39,"quellen":["PubChem CID 166567236","DailyMed SPL MOUNJARO (Tirzepatid), Eli Lilly and Company","chemverify Katalog 14.09.2026"],"halbwertszeit_en":"≈ 5 días (eliminación, información de prescripción de Mounjaro)","reinheitsstandard_en":"≥ 99 % (HPLC, estándar comercial)"},"verwandt":["semaglutid","retatrutid","cagrilintid","survodutid"]},{"slug":"cjc-1295","name":"CJC-1295","synonyme":["Mod GRF 1-29","Modified GRF (1-29)","CJC-1295 con DAC","DAC:GRF"],"kategorie":"Wachstumshormon-Achse","studienlage":"frühe klinische Studien","kurz":"Un análogo sintético de la hormona liberadora de crecimiento, estudiado en dos variantes con diferentes duraciones de acción.","kurz_en":"Un análogo sintético de la hormona liberadora de crecimiento, estudiado en dos variantes con diferentes duraciones de acción.","beschreibung":"CJC-1295 es un análogo estabilizado de la GHRH propia del cuerpo, estudiado en el contexto del eje de la hormona del crecimiento. Existe en dos variantes: sin DAC (Complejo de Afinidad de Fármaco), que tiene una corta duración de acción, y con DAC, que logra una duración sustancialmente extendida mediante la unión a la albúmina sérica. Los datos humanos disponibles provienen principalmente de investigación clínica temprana en adultos sanos.","beschreibung_en":"CJC-1295 es un análogo estabilizado de la GHRH propia del cuerpo, estudiado en el contexto del eje de la hormona del crecimiento. Existe en dos variantes: sin DAC (Complejo de Afinidad de Fármaco), que tiene una corta duración de acción, y con DAC, que logra una duración sustancialmente extendida mediante la unión a la albúmina sérica. Los datos humanos disponibles provienen principalmente de investigación clínica temprana en adultos sanos.","mechanismus":"CJC-1295 se une al receptor de GHRH en las células somatotróficas de la glándula pituitaria, desencadenando la liberación pulsátil de la propia hormona del crecimiento del cuerpo. Sin DAC, la molécula se descompone en minutos, produciendo un pulso hormonal corto y pronunciado. Con DAC, un anclaje químico se une covalentemente a la albúmina en la sangre, extendiendo la duración de la acción a varios días, mientras que los estudios indican que el patrón de liberación pulsátil se conserva.","mechanismus_en":"CJC-1295 se une al receptor de GHRH en las células somatotróficas de la glándula pituitaria, desencadenando la liberación pulsátil de la propia hormona del crecimiento del cuerpo. Sin DAC, la molécula se descompone en minutos, produciendo un pulso hormonal corto y pronunciado. Con DAC, un anclaje químico se une covalentemente a la albúmina en la sangre, extendiendo la duración de la acción a varios días, mientras que los estudios indican que el patrón de liberación pulsátil se conserva.","evidenz":[{"art":"clínico","kurz":"Dos ensayos aleatorizados controlados con placebo en adultos sanos con cantidades crecientes por pasos: una inyección única de CJC-1295 con DAC elevó los niveles de hormona del crecimiento durante varios días y los niveles de IGF-1 durante 9 a 11 días.","kurz_en":"Dos ensayos aleatorizados controlados con placebo en adultos sanos con cantidades crecientes por pasos: una inyección única de CJC-1295 con DAC elevó los niveles de hormona del crecimiento durante varios días y los niveles de IGF-1 durante 9 a 11 días.","quelle":"Teichman et al. 2006, Journal of Clinical Endocrinology & Metabolism, PMID 16352683"},{"art":"clínico","kurz":"Un análisis de seguimiento de los mismos sujetos encontró que la liberación pulsátil de hormona del crecimiento se conservó incluso bajo la estimulación extendida de CJC-1295 con DAC.","kurz_en":"Un análisis de seguimiento de los mismos sujetos encontró que la liberación pulsátil de hormona del crecimiento se conservó incluso bajo la estimulación extendida de CJC-1295 con DAC.","quelle":"Ionescu & Frohman 2006, Journal of Clinical Endocrinology & Metabolism, PMID 17018654"}],"sicherheit":["En los estudios disponibles, se informaron principalmente reacciones locales leves en el sitio de la inyección.","Un ensayo de fase 2 de CJC-1295 con DAC para una condición no relacionada fue descontinuado como precaución después de que un participante muriera; no se estableció un vínculo causal con el péptido.","Los efectos a largo plazo de un nivel persistentemente elevado de IGF-1 en humanos no se comprenden completamente.","Los datos de seguridad humana a largo plazo aún no están disponibles."],"sicherheit_en":["En los estudios disponibles, se informaron principalmente reacciones locales leves en el sitio de la inyección.","Un ensayo de fase 2 de CJC-1295 con DAC para una condición no relacionada fue descontinuado como precaución después de que un participante muriera; no se estableció un vínculo causal con el péptido.","Los efectos a largo plazo de un nivel persistentemente elevado de IGF-1 en humanos no se comprenden completamente.","Los datos de seguridad humana a largo plazo aún no están disponibles."],"hinweise":["Solo con fines de investigación, no apto para uso en humanos","Un certificado de análisis no establece idoneidad médica"],"hinweise_en":["Solo con fines de investigación, no apto para uso en humanos","Un certificado de análisis no establece idoneidad médica"],"rekonstitution":"Las condiciones específicas de cada producto figuran en la documentación original del fabricante. Este portal no ofrece instrucciones de preparación ni de uso en humanos.","rekonstitution_en":"Las condiciones específicas de cada producto figuran en la documentación original del fabricante. Este portal no ofrece instrucciones de preparación ni de uso en humanos.","lagerung":"Las condiciones específicas de cada producto figuran en la documentación original del fabricante. Este portal no ofrece instrucciones de preparación ni de uso en humanos.","lagerung_en":"Las condiciones específicas de cada producto figuran en la documentación original del fabricante. Este portal no ofrece instrucciones de preparación ni de uso en humanos.","rechtsstatus":"CJC-1295 no está aprobado como medicamento ni en la UE ni en EE. UU. Se vende exclusivamente como un químico de investigación y no está destinado para uso humano.","rechtsstatus_en":"CJC-1295 no está aprobado como medicamento ni en la UE ni en EE. UU. Se vende exclusivamente como un químico de investigación y no está destinado para uso humano.","typischeMg":[2,5],"faq":[{"q":"¿Cuál es la diferencia entre CJC-1295 con y sin DAC?","a":"Sin DAC, el péptido se descompone en minutos, produciendo un pulso hormonal corto y pronunciado. Con DAC, un ancla química se une a la albúmina en la sangre, extendiendo la duración a varios días, mientras que los estudios indican que el patrón de liberación pulsátil se conserva.","q_en":"¿Cuál es la diferencia entre CJC-1295 con y sin DAC?","a_en":"Sin DAC, el péptido se descompone en minutos, produciendo un pulso hormonal corto y pronunciado. Con DAC, un ancla química se une a la albúmina en la sangre, extendiendo la duración a varios días, mientras que los estudios indican que el patrón de liberación pulsátil se conserva."},{"q":"¿Es CJC-1295 un medicamento aprobado?","a":"No. CJC-1295 no está aprobado como medicamento en la UE o en EE. UU. y se vende exclusivamente como un químico de investigación para uso de laboratorio.","q_en":"¿Es CJC-1295 un medicamento aprobado?","a_en":"No. CJC-1295 no está aprobado como medicamento en la UE o en EE. UU. y se vende exclusivamente como un químico de investigación para uso de laboratorio."},{"q":"¿Para qué se estudia CJC-1295 en la investigación?","a":"CJC-1295 se estudia en el contexto del eje de la hormona del crecimiento, particularmente con respecto a la liberación propia de la hormona del crecimiento por parte del cuerpo y la producción resultante de IGF-1 en el hígado.","q_en":"¿Para qué se estudia CJC-1295 en la investigación?","a_en":"CJC-1295 se estudia en el contexto del eje de la hormona del crecimiento, particularmente con respecto a la liberación propia de la hormona del crecimiento por parte del cuerpo y la producción resultante de IGF-1 en el hígado."}],"seo":{"title":"Resumen de investigación sobre CJC-1295","title_en":"Resumen de investigación sobre CJC-1295","description":"CJC-1295 explicado de forma fáctica: mecanismo de acción, la diferencia con y sin DAC, datos de estudio y estado legal de este análogo de GHRH.","description_en":"CJC-1295 explicado de forma fáctica: mecanismo de acción, la diferencia con y sin DAC, datos de estudio y estado legal de este análogo de GHRH."},"demo":false,"steckbrief":{"cas":null,"molekulargewicht":null,"aminosaeuren":null,"halbwertszeit":null,"reinheitsstandard":null,"loeslichkeit":null,"sequenzLaenge":null,"quellen":["chemverify Katalog 14.09.2026 (Eintrag deckt CJC-1295 mit und ohne DAC generisch ab, CAS/Molekulargewicht nicht eindeutig einer Variante zuordenbar)"]},"verwandt":["ipamorelin","sermorelin","tesamorelin","igf-1-lr3"]},{"slug":"hexarelin","name":"Hexarelin","synonyme":[],"kategorie":"Wachstumshormon-Achse","studienlage":"frühe klinische Studien","kurz":"Un hexapéptido sintético de la clase de péptidos liberadores de hormona del crecimiento, estudiado en investigación clínica temprana sobre la secreción de hormona del crecimiento.","kurz_en":"Un hexapéptido sintético de la clase de péptidos liberadores de hormona del crecimiento, estudiado en investigación clínica temprana sobre la secreción de hormona del crecimiento.","beschreibung":"Hexarelin es un hexapéptido sintético de la clase GHRP (péptido liberador de hormona del crecimiento), descrito farmacológicamente por primera vez en 1994. Se ha estudiado en ensayos clínicos sobre la secreción de hormona del crecimiento en niños, adultos y adultos mayores, y por separado en investigación preclínica sobre efectos cardíacos.","beschreibung_en":"Hexarelin es un hexapéptido sintético de la clase GHRP (péptido liberador de hormona del crecimiento), descrito farmacológicamente por primera vez en 1994. Se ha estudiado en ensayos clínicos sobre la secreción de hormona del crecimiento en niños, adultos y adultos mayores, y por separado en investigación preclínica sobre efectos cardíacos.","mechanismus":"Hexarelin se une al receptor de ghrelina (GHS-R1a) en el hipotálamo y la glándula pituitaria, desencadenando una liberación pulsátil de la propia hormona del crecimiento del cuerpo. A diferencia de péptidos más selectivos en la misma clase como ipamorelina, hexarelin mostró una liberación adicional relevante de ACTH y cortisol en estudios. La investigación preclínica también describe una unión independiente de la hormona del crecimiento a los receptores GHS-R1a cardíacos.","mechanismus_en":"Hexarelin se une al receptor de ghrelina (GHS-R1a) en el hipotálamo y la glándula pituitaria, desencadenando una liberación pulsátil de la propia hormona del crecimiento del cuerpo. A diferencia de péptidos más selectivos en la misma clase como ipamorelina, hexarelin mostró una liberación adicional relevante de ACTH y cortisol en estudios. La investigación preclínica también describe una unión independiente de la hormona del crecimiento a los receptores GHS-R1a cardíacos.","evidenz":[{"art":"preclínico","kurz":"En estudios en ratas recién nacidas y adultas, hexarelin desencadenó una liberación pronunciada y duradera de hormona del crecimiento, y fue más efectivo que el péptido relacionado GHRP-6 cuando se administró subcutáneamente.","kurz_en":"En estudios en ratas recién nacidas y adultas, hexarelin desencadenó una liberación pronunciada y duradera de hormona del crecimiento, y fue más efectivo que el péptido relacionado GHRP-6 cuando se administró subcutáneamente.","quelle":"Deghenghi R et al. 1994, Life Sciences, Bd. 54(18), S. 1321-1328, PMID 7910650"},{"art":"clínico","kurz":"En un estudio de 60 personas de 5 a 81 años, la respuesta de la hormona del crecimiento a la hexarelin se comparó en niños prepuberales y puberales, adultos jóvenes y adultos mayores, con una respuesta marcadamente más débil en niños prepuberales y participantes mayores.","kurz_en":"En un estudio de 60 personas de 5 a 81 años, la respuesta de la hormona del crecimiento a la hexarelin se comparó en niños prepuberales y puberales, adultos jóvenes y adultos mayores, con una respuesta marcadamente más débil en niños prepuberales y participantes mayores.","quelle":"Arvat E et al. 1997, European Journal of Endocrinology, Bd. 137(6), PMID 9437229"},{"art":"clínico","kurz":"En un estudio de 15 hombres sanos, la hexarelin aumentó la ACTH y el cortisol, un efecto que fue potenciado por la desmopressina (un análogo de la vasopresina), lo que sugiere la implicación de la vasopresina en este efecto secundario.","kurz_en":"En un estudio de 15 hombres sanos, la hexarelin aumentó la ACTH y el cortisol, un efecto que fue potenciado por la desmopressina (un análogo de la vasopresina), lo que sugiere la implicación de la vasopresina en este efecto secundario.","quelle":"Korbonits M et al. 1999, Journal of Clinical Endocrinology & Metabolism, Bd. 84(7), S. 2489-2495, PMID 10404825"},{"art":"preclínico","kurz":"En un modelo de rata, la hexarelin mostró efectos protectores en el corazón después de isquemia-repercusión que ocurrieron independientemente de la actividad de la hormona del crecimiento y se atribuyeron a la unión directa a receptores cardíacos.","kurz_en":"En un modelo de rata, la hexarelin mostró efectos protectores en el corazón después de isquemia-repercusión que ocurrieron independientemente de la actividad de la hormona del crecimiento y se atribuyeron a la unión directa a receptores cardíacos.","quelle":"Locatelli V et al. 1999, Endocrinology, Bd. 140(9), S. 4024-4031, PMID 10465272"}],"sicherheit":["En estudios clínicos, la hexarelin desencadenó no solo la hormona del crecimiento sino también una liberación relevante de ACTH, cortisol y prolactina, un efecto no observado en esta medida con GHRPs más selectivos como la ipamorelina.","La respuesta de la hormona del crecimiento a la hexarelin es marcadamente más débil en niños prepuberales y adultos mayores que en adolescentes y adultos jóvenes.","No hay datos de seguridad a largo plazo independientes en adultos sanos más allá de estudios controlados a corto plazo.","Las interacciones con otros ejes hormonales, particularmente el eje hipotálamo-pituitario-adrenal, no han sido estudiadas de manera concluyente."],"sicherheit_en":["En estudios clínicos, la hexarelin desencadenó no solo la hormona del crecimiento sino también una liberación relevante de ACTH, cortisol y prolactina, un efecto no observado en esta medida con GHRPs más selectivos como la ipamorelina.","La respuesta de la hormona del crecimiento a la hexarelin es marcadamente más débil en niños prepuberales y adultos mayores que en adolescentes y adultos jóvenes.","No hay datos de seguridad a largo plazo independientes en adultos sanos más allá de estudios controlados a corto plazo.","Las interacciones con otros ejes hormonales, particularmente el eje hipotálamo-pituitario-adrenal, no han sido estudiadas de manera concluyente."],"hinweise":["Solo con fines de investigación, no apto para uso en humanos","Un certificado de análisis no establece idoneidad médica"],"hinweise_en":["Solo con fines de investigación, no apto para uso en humanos","Un certificado de análisis no establece idoneidad médica"],"rekonstitution":"Las condiciones específicas de cada producto figuran en la documentación original del fabricante. Este portal no ofrece instrucciones de preparación ni de uso en humanos.","rekonstitution_en":"Las condiciones específicas de cada producto figuran en la documentación original del fabricante. Este portal no ofrece instrucciones de preparación ni de uso en humanos.","lagerung":"Las condiciones específicas de cada producto figuran en la documentación original del fabricante. Este portal no ofrece instrucciones de preparación ni de uso en humanos.","lagerung_en":"Las condiciones específicas de cada producto figuran en la documentación original del fabricante. Este portal no ofrece instrucciones de preparación ni de uso en humanos.","rechtsstatus":"La hexarelin no está aprobada como medicamento en Alemania, la UE o los Estados Unidos, y se vende exclusivamente como un químico de investigación para fines de laboratorio.","rechtsstatus_en":"La hexarelin no está aprobada como medicamento en Alemania, la UE o los Estados Unidos, y se vende exclusivamente como un químico de investigación para fines de laboratorio.","typischeMg":[2,5],"faq":[{"q":"¿Difiere la hexarelin de la ipamorelina?","a":"Sí. Ambas se unen al mismo receptor de la grelina, pero la hexarelin mostró adicionalmente una liberación relevante de ACTH y cortisol en estudios, mientras que la ipamorelina se considera más selectiva para el eje de la hormona del crecimiento por sí solo.","q_en":"¿Difiere la hexarelin de la ipamorelina?","a_en":"Sí. Ambas se unen al mismo receptor de la grelina, pero la hexarelin mostró adicionalmente una liberación relevante de ACTH y cortisol en estudios, mientras que la ipamorelina se considera más selectiva para el eje de la hormona del crecimiento por sí solo."},{"q":"¿Se estudió la hexarelin en niños?","a":"La hexarelin se ha utilizado en estudios clínicos sobre la secreción de hormona del crecimiento en niños en diferentes etapas puberales, dentro de protocolos de investigación controlados y no como medicamento aprobado.","q_en":"¿Se estudió la hexarelin en niños?","a_en":"La hexarelin se ha utilizado en estudios clínicos sobre la secreción de hormona del crecimiento en niños en diferentes etapas puberales, dentro de protocolos de investigación controlados y no como medicamento aprobado."},{"q":"¿Es la hexarelin un medicamento aprobado?","a":"No. La hexarelin no está aprobada como medicamento en la UE o EE. UU. y se ofrece exclusivamente como químico de investigación, no para uso humano.","q_en":"¿Es la hexarelin un medicamento aprobado?","a_en":"No. La hexarelin no está aprobada como medicamento en la UE o EE. UU. y se ofrece exclusivamente como químico de investigación, no para uso humano."}],"seo":{"title":"Resumen de investigación sobre hexarelin","title_en":"Resumen de investigación sobre hexarelin","description":"La hexarelin explicada de forma fáctica: mecanismo de acción, datos de estudio sobre hormona del crecimiento y ACTH/cortisol, perfil de seguridad y estado legal de este péptido GHRP.","description_en":"La hexarelin explicada de forma fáctica: mecanismo de acción, datos de estudio sobre hormona del crecimiento y ACTH/cortisol, perfil de seguridad y estado legal de este péptido GHRP."},"demo":false,"steckbrief":{"cas":"140703-51-1","molekulargewicht":"887.0 g/mol","aminosaeuren":6,"halbwertszeit":null,"reinheitsstandard":null,"loeslichkeit":null,"sequenzLaenge":6,"quellen":["PubChem CID 6918297","chemverify Katalog 14.09.2026"]},"verwandt":["ipamorelin","cjc-1295","sermorelin","igf-1-lr3"]},{"slug":"igf-1-lr3","name":"IGF-1 LR3","synonyme":["Long R3 IGF-1","LR3-IGF-1","IGF-1 Long R3"],"kategorie":"Wachstumshormon-Achse","studienlage":"präklinisch","kurz":"Un análogo genéticamente alargado de IGF-1 con 83 aminoácidos, estudiado en modelos animales para efectos de crecimiento y listado como sustancia de dopaje en deportes competitivos.","kurz_en":"Un análogo genéticamente alargado de IGF-1 con 83 aminoácidos, estudiado en modelos animales para efectos de crecimiento y listado como sustancia de dopaje en deportes competitivos.","beschreibung":"IGF-1 LR3 es un análogo recombinante del factor de crecimiento similar a la insulina 1 que se encuentra de forma natural, desarrollado originalmente para investigación en cultivo celular. Lleva aminoácidos adicionales en el extremo N y una posición 3 alterada, lo que lo hace en gran medida incapaz de unirse a las proteínas que se unen a IGF. Se estudia principalmente en modelos animales de crecimiento de órganos y células, pero fuera de la investigación también se utiliza ampliamente para la mejora del rendimiento supuesta sin datos humanos sólidos.","beschreibung_en":"IGF-1 LR3 es un análogo recombinante del factor de crecimiento similar a la insulina 1 que se encuentra de forma natural, desarrollado originalmente para investigación en cultivo celular. Lleva aminoácidos adicionales en el extremo N y una posición 3 alterada, lo que lo hace en gran medida incapaz de unirse a las proteínas que se unen a IGF. Se estudia principalmente en modelos animales de crecimiento de órganos y células, pero fuera de la investigación también se utiliza ampliamente para la mejora del rendimiento supuesta sin datos humanos sólidos.","mechanismus":"Debido a que se une pobremente a las proteínas que se unen a IGF, una mayor parte de IGF-1 LR3 permanece libre y activa el receptor de IGF-1 de manera más fuerte y por más tiempo que el IGF-1 nativo. En modelos preclínicos, esto se describe como la inducción de mayor proliferación celular a través de las vías ERK y PI3K/Akt. Al mismo tiempo, se informa de la supresión de la producción endógena de IGF-1 y de los niveles de proteínas que se unen a IGF.","mechanismus_en":"Debido a que se une pobremente a las proteínas que se unen a IGF, una mayor parte de IGF-1 LR3 permanece libre y activa el receptor de IGF-1 de manera más fuerte y por más tiempo que el IGF-1 nativo. En modelos preclínicos, esto se describe como la inducción de mayor proliferación celular a través de las vías ERK y PI3K/Akt. Al mismo tiempo, se informa de la supresión de la producción endógena de IGF-1 y de los niveles de proteínas que se unen a IGF.","evidenz":[{"art":"preclínico","kurz":"Un estudio de infusión en cobayas describe un aumento del crecimiento de órganos bajo R3 IGF-1 prolongado, mientras que al mismo tiempo los niveles plasmáticos de IGF-1 endógeno, IGF-2 y proteínas que se unen a IGF disminuyeron.","kurz_en":"Un estudio de infusión en cobayas describe un aumento del crecimiento de órganos bajo R3 IGF-1 prolongado, mientras que al mismo tiempo los niveles plasmáticos de IGF-1 endógeno, IGF-2 y proteínas que se unen a IGF disminuyeron.","quelle":"Conlon et al. 1995, Journal of Endocrinology, PMID 7561636"},{"art":"preclínico","kurz":"Un estudio celular en cardiomiocitos de ovejas fetales utilizó IGF-1 LR3 como estímulo de receptor estable y describió la proliferación celular mediada a través de las vías ERK y PI3K.","kurz_en":"Un estudio celular en cardiomiocitos de ovejas fetales utilizó IGF-1 LR3 como estímulo de receptor estable y describió la proliferación celular mediada a través de las vías ERK y PI3K.","quelle":"Sundgren et al. 2003, American Journal of Physiology, PMID 12947030"},{"art":"clínico","kurz":"Una revisión de 2026 describió una brecha sustancial entre la base de evidencia clínica para péptidos del eje de la hormona del crecimiento como IGF-1 LR3 y su autoadministración generalizada fuera de supervisión médica.","kurz_en":"Una revisión de 2026 describió una brecha sustancial entre la base de evidencia clínica para péptidos del eje de la hormona del crecimiento como IGF-1 LR3 y su autoadministración generalizada fuera de supervisión médica.","quelle":"Dominikowski et al. 2026, Frontiers in Endocrinology, PMID 42395176"}],"sicherheit":["Faltan estudios de seguridad humana controlados sobre IGF-1 LR3, la evidencia disponible proviene de modelos celulares y animales.","Los modelos animales describen la supresión del propio eje de IGF-1 del cuerpo, cuyas consecuencias no se han estudiado en humanos.","La elevación no controlada de la actividad de IGF-1 se discute en la literatura como un factor de riesgo teórico para el crecimiento celular y tisular no deseado, no se ha establecido un vínculo causal en humanos.","Los productos de fabricación no controlada conllevan un riesgo de contaminación que es independiente de la molécula misma."],"sicherheit_en":["Faltan estudios de seguridad humana controlados sobre IGF-1 LR3, la evidencia disponible proviene de modelos celulares y animales.","Los modelos animales describen la supresión del propio eje de IGF-1 del cuerpo, cuyas consecuencias no se han estudiado en humanos.","La elevación no controlada de la actividad de IGF-1 se discute en la literatura como un factor de riesgo teórico para el crecimiento celular y tisular no deseado, no se ha establecido un vínculo causal en humanos.","Los productos de fabricación no controlada conllevan un riesgo de contaminación que es independiente de la molécula misma."],"hinweise":["Solo con fines de investigación, no apto para uso en humanos","Un certificado de análisis no establece idoneidad médica"],"hinweise_en":["Solo con fines de investigación, no apto para uso en humanos","Un certificado de análisis no establece idoneidad médica"],"rekonstitution":"Las condiciones específicas de cada producto figuran en la documentación original del fabricante. Este portal no ofrece instrucciones de preparación ni de uso en humanos.","rekonstitution_en":"Las condiciones específicas de cada producto figuran en la documentación original del fabricante. Este portal no ofrece instrucciones de preparación ni de uso en humanos.","lagerung":"Las condiciones específicas de cada producto figuran en la documentación original del fabricante. Este portal no ofrece instrucciones de preparación ni de uso en humanos.","lagerung_en":"Las condiciones específicas de cada producto figuran en la documentación original del fabricante. Este portal no ofrece instrucciones de preparación ni de uso en humanos.","rechtsstatus":"IGF-1 LR3 no está autorizado como medicamento en Alemania, la UE ni Estados Unidos y no está clasificado como producto alimenticio. Se vende exclusivamente como sustancia química para investigación. En el deporte organizado está prohibido en todo momento como factor de crecimiento de categoría S2 según la Lista de Prohibiciones de la AMA.","rechtsstatus_en":"IGF-1 LR3 no está autorizado como medicamento en Alemania, la UE ni Estados Unidos y no está clasificado como producto alimenticio. Se vende exclusivamente como sustancia química para investigación. En el deporte organizado está prohibido en todo momento como factor de crecimiento de categoría S2 según la Lista de Prohibiciones de la AMA.","typischeMg":[],"faq":[{"q":"¿Qué distingue a IGF-1 LR3 del IGF-1 natural?","a":"IGF-1 LR3 lleva aminoácidos adicionales en el extremo N y una posición 3 alterada, lo que significa que apenas se une a las proteínas que se unen a IGF y, por lo tanto, actúa sobre el receptor más tiempo y con mayor fuerza que el IGF-1 nativo.","q_en":"¿Qué distingue a IGF-1 LR3 del IGF-1 natural?","a_en":"IGF-1 LR3 lleva aminoácidos adicionales en el extremo N y una posición 3 alterada, lo que significa que apenas se une a las proteínas que se unen a IGF y, por lo tanto, actúa sobre el receptor más tiempo y con mayor fuerza que el IGF-1 nativo."},{"q":"¿Se permite IGF-1 LR3 en el deporte?","a":"No, está listado como factor de crecimiento en la Lista Prohibida de WADA (categoría S2) y está prohibido en todo momento en el deporte organizado.","q_en":"¿Se permite IGF-1 LR3 en el deporte?","a_en":"No, está listado como factor de crecimiento en la Lista Prohibida de WADA (categoría S2) y está prohibido en todo momento en el deporte organizado."},{"q":"¿Existen estudios en humanos sobre IGF-1 LR3?","a":"No hay estudios en humanos controlados disponibles, la evidencia existente proviene de modelos celulares y animales, una revisión de 2026 señala esta brecha de evidencia.","q_en":"¿Existen estudios en humanos sobre IGF-1 LR3?","a_en":"No hay estudios en humanos controlados disponibles, la evidencia existente proviene de modelos celulares y animales, una revisión de 2026 señala esta brecha de evidencia."}],"seo":{"title":"IGF-1 LR3: perfil de investigación y evidencia","title_en":"IGF-1 LR3: perfil de investigación y evidencia","description":"Resumen de IGF-1 LR3: estructura, evidencia preclínica, estado de dopaje en el deporte (WADA S2) y perfil de seguridad, presentado de forma fáctica para el contexto de la investigación.","description_en":"Resumen de IGF-1 LR3: estructura, evidencia preclínica, estado de dopaje en el deporte (WADA S2) y perfil de seguridad, presentado de forma fáctica para el contexto de la investigación."},"demo":false,"steckbrief":{"cas":null,"molekulargewicht":"9111.4 g/mol","aminosaeuren":83,"halbwertszeit":null,"reinheitsstandard":"≥ 98 % (HPLC, estándar comercial)","loeslichkeit":null,"sequenzLaenge":83,"quellen":["chemverify Katalog 14.09.2026 (PubChem: kein Eintrag für IGF-1 LR3, CAS dort nicht geführt)"],"reinheitsstandard_en":"≥ 98 % (HPLC, estándar comercial)"},"verwandt":["hexarelin","cjc-1295","tesamorelin","sermorelin"]},{"slug":"ipamorelin","name":"Ipamorelina","synonyme":["NNC 26-0161"],"kategorie":"Wachstumshormon-Achse","studienlage":"frühe klinische Studien","kurz":"Un pentapéptido selectivo de la clase de péptidos liberadores de hormona del crecimiento, estudiado en investigación clínica temprana.","kurz_en":"Un pentapéptido selectivo de la clase de péptidos liberadores de hormona del crecimiento, estudiado en investigación clínica temprana.","beschreibung":"Ipamorelina es un péptido sintético compuesto por cinco aminoácidos que imita la grelina propia del cuerpo. Fue descrito por primera vez en 1998 como el primer miembro selectivo de su clase de fármacos y ha sido estudiado en ensayos clínicos incluidos en pacientes que se recuperan de cirugía abdominal. Para aplicaciones relacionadas con la hormona del crecimiento, no hay estudios controlados en adultos sanos disponibles hasta la fecha.","beschreibung_en":"Ipamorelina es un péptido sintético compuesto por cinco aminoácidos que imita la grelina propia del cuerpo. Fue descrito por primera vez en 1998 como el primer miembro selectivo de su clase de fármacos y ha sido estudiado en ensayos clínicos incluidos en pacientes que se recuperan de cirugía abdominal. Para aplicaciones relacionadas con la hormona del crecimiento, no hay estudios controlados en adultos sanos disponibles hasta la fecha.","mechanismus":"Ipamorelina se une selectivamente al receptor de la grelina (GHS-R1A) en el hipotálamo y la glándula pituitaria, relajando el efecto inhibitorio de la somatostatina. Esto conduce a la liberación pulsátil de la propia hormona del crecimiento del cuerpo desde la glándula pituitaria. A diferencia de los péptidos más antiguos de la misma clase, los estudios no encontraron un aumento relevante en ACTH, cortisol o prolactina con ipamorelina.","mechanismus_en":"Ipamorelina se une selectivamente al receptor de la grelina (GHS-R1A) en el hipotálamo y la glándula pituitaria, relajando el efecto inhibitorio de la somatostatina. Esto conduce a la liberación pulsátil de la propia hormona del crecimiento del cuerpo desde la glándula pituitaria. A diferencia de los péptidos más antiguos de la misma clase, los estudios no encontraron un aumento relevante en ACTH, cortisol o prolactina con ipamorelina.","evidenz":[{"art":"preclínico","kurz":"La descripción original en un modelo de cerdo mostró que ipamorelina libera hormona del crecimiento sin un efecto relevante en ACTH, cortisol, prolactina, FSH o LH, a diferencia de los péptidos más antiguos de la misma clase.","kurz_en":"La descripción original en un modelo de cerdo mostró que ipamorelina libera hormona del crecimiento sin un efecto relevante en ACTH, cortisol, prolactina, FSH o LH, a diferencia de los péptidos más antiguos de la misma clase.","quelle":"Raun et al. 1998, European Journal of Endocrinology, PMID 9849822"},{"art":"preclínico","kurz":"En un modelo de rata de parálisis intestinal postoperatoria, ipamorelina aceleró el retorno del movimiento intestinal después de la cirugía.","kurz_en":"En un modelo de rata de parálisis intestinal postoperatoria, ipamorelina aceleró el retorno del movimiento intestinal después de la cirugía.","quelle":"Venkova et al. 2009, Journal of Pharmacology and Experimental Therapeutics, PMID 19289567"},{"art":"clínico","kurz":"En un ensayo de fase 2 aleatorizado y controlado con placebo en 117 pacientes después de cirugía intestinal, el tiempo hasta la primera comida tolerada no difirió estadísticamente entre los grupos de ipamorelina y placebo.","kurz_en":"En un ensayo de fase 2 aleatorizado y controlado con placebo en 117 pacientes después de cirugía intestinal, el tiempo hasta la primera comida tolerada no difirió estadísticamente entre los grupos de ipamorelina y placebo.","quelle":"International Journal of Colorectal Disease 2014, DOI 10.1007/s00384-014-2030-8"}],"sicherheit":["En el ensayo controlado más grande hasta la fecha, los eventos adversos reportados fueron igualmente frecuentes en los grupos de ipamorelina y placebo.","La FDA detuvo el desarrollo clínico de ipamorelina en 2023 después de que ocurrieran dos muertes en la población del estudio; se considera científicamente discutida una relación causal con el péptido.","Los datos de seguridad a largo plazo en adultos sanos no están disponibles.","Las interacciones con otros ejes hormonales no se han estudiado completamente."],"sicherheit_en":["En el ensayo controlado más grande hasta la fecha, los eventos adversos reportados fueron igualmente frecuentes en los grupos de ipamorelina y placebo.","La FDA detuvo el desarrollo clínico de ipamorelina en 2023 después de que ocurrieran dos muertes en la población del estudio; se considera científicamente discutida una relación causal con el péptido.","Los datos de seguridad a largo plazo en adultos sanos no están disponibles.","Las interacciones con otros ejes hormonales no se han estudiado completamente."],"hinweise":["Solo con fines de investigación, no apto para uso en humanos","Un certificado de análisis no establece idoneidad médica"],"hinweise_en":["Solo con fines de investigación, no apto para uso en humanos","Un certificado de análisis no establece idoneidad médica"],"rekonstitution":"Las condiciones específicas de cada producto figuran en la documentación original del fabricante. Este portal no ofrece instrucciones de preparación ni de uso en humanos.","rekonstitution_en":"Las condiciones específicas de cada producto figuran en la documentación original del fabricante. Este portal no ofrece instrucciones de preparación ni de uso en humanos.","lagerung":"Las condiciones específicas de cada producto figuran en la documentación original del fabricante. Este portal no ofrece instrucciones de preparación ni de uso en humanos.","lagerung_en":"Las condiciones específicas de cada producto figuran en la documentación original del fabricante. Este portal no ofrece instrucciones de preparación ni de uso en humanos.","rechtsstatus":"Ipamorelina no está aprobada como medicamento ni en la UE ni en EE. UU. la FDA detuvo el desarrollo clínico adicional en 2023. Se vende exclusivamente como un químico de investigación.","rechtsstatus_en":"Ipamorelina no está aprobada como medicamento ni en la UE ni en EE. UU. la FDA detuvo el desarrollo clínico adicional en 2023. Se vende exclusivamente como un químico de investigación.","typischeMg":[2,5],"faq":[{"q":"¿Aumenta ipamorelina el cortisol como los péptidos más antiguos de la misma clase?","a":"En los estudios disponibles, a diferencia de péptidos más antiguos como GHRP-6 o GHRP-2, ipamorelina no mostró un aumento relevante en ACTH o cortisol. Esta es considerada su característica distintiva mejor documentada científicamente.","q_en":"¿Aumenta ipamorelina el cortisol como los péptidos más antiguos de la misma clase?","a_en":"En los estudios disponibles, a diferencia de péptidos más antiguos como GHRP-6 o GHRP-2, ipamorelina no mostró un aumento relevante en ACTH o cortisol. Esta es considerada su característica distintiva mejor documentada científicamente."},{"q":"¿Es ipamorelina un medicamento aprobado?","a":"No. La FDA detuvo el desarrollo clínico de ipamorelina en 2023. No está aprobado en la UE ni en EE. UU. y se vende como un químico de investigación.","q_en":"¿Es ipamorelina un medicamento aprobado?","a_en":"No. La FDA detuvo el desarrollo clínico de ipamorelina en 2023. No está aprobado en la UE ni en EE. UU. y se vende como un químico de investigación."},{"q":"¿Por qué se detuvo el desarrollo de ipamorelina?","a":"Después de que ocurrieron dos muertes en una población de estudio de pacientes gravemente enfermos tras cirugía abdominal, la FDA detuvo el desarrollo adicional en 2023. Un vínculo causal con el péptido se considera científicamente disputado.","q_en":"¿Por qué se detuvo el desarrollo de ipamorelina?","a_en":"Después de que ocurrieron dos muertes en una población de estudio de pacientes gravemente enfermos tras cirugía abdominal, la FDA detuvo el desarrollo adicional en 2023. Un vínculo causal con el péptido se considera científicamente disputado."}],"seo":{"title":"Resumen de investigación sobre ipamorelina","title_en":"Resumen de investigación sobre ipamorelina","description":"Ipamorelina explicado de forma fáctica: mecanismo de acción selectivo, datos del estudio, perfil de seguridad y estado legal de este mimetizador de grelina.","description_en":"Ipamorelina explicado de forma fáctica: mecanismo de acción selectivo, datos del estudio, perfil de seguridad y estado legal de este mimetizador de grelina."},"demo":false,"steckbrief":{"cas":"170851-70-4","molekulargewicht":"711.9 g/mol","aminosaeuren":5,"halbwertszeit":null,"reinheitsstandard":"≥ 99 % (HPLC, estándar comercial)","loeslichkeit":null,"sequenzLaenge":5,"quellen":["PubChem CID 9831659","chemverify Katalog 14.09.2026"],"reinheitsstandard_en":"≥ 99 % (HPLC, estándar comercial)"},"verwandt":["cjc-1295","sermorelin","tesamorelin","hexarelin"]},{"slug":"sermorelin","name":"Sermorelina","synonyme":["GRF 1-29","GHRH(1-29)","Geref (nombre comercial histórico)"],"kategorie":"Wachstumshormon-Achse","studienlage":"klinisch untersucht","kurz":"Un fragmento de cadena corta de la propia GHRH del cuerpo, históricamente aprobado como medicamento, ahora se vende como sustancia de investigación.","kurz_en":"Un fragmento de cadena corta de la propia GHRH del cuerpo, históricamente aprobado como medicamento, ahora se vende como sustancia de investigación.","beschreibung":"Sermorelina es el fragmento biológicamente activo GHRH(1-29) de la hormona liberadora de crecimiento del propio cuerpo. En EE. UU. fue aprobado en 1990 como agente de diagnóstico y en 1997 para la baja estatura relacionada con deficiencia de hormona del crecimiento en niños; la aprobación fue retirada en 2008 por razones de fabricación. Hoy se estudia fuera de esa aprobación histórica como sustancia de investigación.","beschreibung_en":"Sermorelina es el fragmento biológicamente activo GHRH(1-29) de la hormona liberadora de crecimiento del propio cuerpo. En EE. UU. fue aprobado en 1990 como agente de diagnóstico y en 1997 para la baja estatura relacionada con deficiencia de hormona del crecimiento en niños; la aprobación fue retirada en 2008 por razones de fabricación. Hoy se estudia fuera de esa aprobación histórica como sustancia de investigación.","mechanismus":"Sermorelina se une al receptor de GHRH en las células somatotróficas de la glándula pituitaria y activa la cascada adenilato ciclasa-cAMP. Esto desencadena la liberación de la propia hormona del crecimiento del cuerpo en pulsos fisiológicos. Debido a su vida media muy corta de solo unos pocos minutos, el pulso hormonal resultante es breve y moderado.","mechanismus_en":"Sermorelina se une al receptor de GHRH en las células somatotróficas de la glándula pituitaria y activa la cascada adenilato ciclasa-cAMP. Esto desencadena la liberación de la propia hormona del crecimiento del cuerpo en pulsos fisiológicos. Debido a su vida media muy corta de solo unos pocos minutos, el pulso hormonal resultante es breve y moderado.","evidenz":[{"art":"clínico","kurz":"En un ensayo aleatorizado controlado con placebo en hombres y mujeres mayores, un análogo de GHRH(1-29) sustituido con Nle27 aumentó los niveles de hormona del crecimiento e IGF-1 durante varios meses y mejoró la masa corporal sin grasa.","kurz_en":"En un ensayo aleatorizado controlado con placebo en hombres y mujeres mayores, un análogo de GHRH(1-29) sustituido con Nle27 aumentó los niveles de hormona del crecimiento e IGF-1 durante varios meses y mejoró la masa corporal sin grasa.","quelle":"Khorram et al. 1997, Journal of Clinical Endocrinology & Metabolism, PMID 9141536"},{"art":"clínico","kurz":"Una revisión de los datos clínicos disponibles en niños con deficiencia de hormona del crecimiento describió una velocidad de crecimiento acelerada durante doce meses en la mayoría de los niños estudiados.","kurz_en":"Una revisión de los datos clínicos disponibles en niños con deficiencia de hormona del crecimiento describió una velocidad de crecimiento acelerada durante doce meses en la mayoría de los niños estudiados.","quelle":"Prakash & Goa 1999, BioDrugs, PMID 18031173"}],"sicherheit":["Los estudios disponibles informaron principalmente sobre efectos secundarios leves y transitorios.","La aprobación original fue retirada en 2008 por razones de fabricación; no hubo advertencia de seguridad detrás de esta decisión.","Se discute un aumento posible e inconsistente observado en LH y FSH en la literatura.","Los datos de seguridad a largo plazo en adultos sanos no están disponibles."],"sicherheit_en":["Los estudios disponibles informaron principalmente sobre efectos secundarios leves y transitorios.","La aprobación original fue retirada en 2008 por razones de fabricación; no hubo advertencia de seguridad detrás de esta decisión.","Se discute un aumento posible e inconsistente observado en LH y FSH en la literatura.","Los datos de seguridad a largo plazo en adultos sanos no están disponibles."],"hinweise":["Solo con fines de investigación, no apto para uso en humanos","Un certificado de análisis no establece idoneidad médica"],"hinweise_en":["Solo con fines de investigación, no apto para uso en humanos","Un certificado de análisis no establece idoneidad médica"],"rekonstitution":"Las condiciones específicas de cada producto figuran en la documentación original del fabricante. Este portal no ofrece instrucciones de preparación ni de uso en humanos.","rekonstitution_en":"Las condiciones específicas de cada producto figuran en la documentación original del fabricante. Este portal no ofrece instrucciones de preparación ni de uso en humanos.","lagerung":"Las condiciones específicas de cada producto figuran en la documentación original del fabricante. Este portal no ofrece instrucciones de preparación ni de uso en humanos.","lagerung_en":"Las condiciones específicas de cada producto figuran en la documentación original del fabricante. Este portal no ofrece instrucciones de preparación ni de uso en humanos.","rechtsstatus":"Sermorelina fue aprobada como medicamento en EE. UU. de 1990 a 2008; la aprobación fue retirada por razones de fabricación. Actualmente no se comercializa como medicamento ni en la UE ni en EE. UU. y se ofrece como producto químico de investigación.","rechtsstatus_en":"Sermorelina fue aprobada como medicamento en EE. UU. de 1990 a 2008; la aprobación fue retirada por razones de fabricación. Actualmente no se comercializa como medicamento ni en la UE ni en EE. UU. y se ofrece como producto químico de investigación.","typischeMg":[5,10],"faq":[{"q":"¿Fue sermorelina alguna vez un medicamento aprobado?","a":"Sí. Sermorelina fue aprobada en EE. UU. de 1990 a 2008, primero como agente diagnóstico, luego para la baja estatura relacionada con la deficiencia de hormona del crecimiento en niños. La aprobación fue retirada por razones de fabricación, no por preocupaciones de seguridad.","q_en":"¿Fue sermorelina alguna vez un medicamento aprobado?","a_en":"Sí. Sermorelina fue aprobada en EE. UU. de 1990 a 2008, primero como agente diagnóstico, luego para la baja estatura relacionada con la deficiencia de hormona del crecimiento en niños. La aprobación fue retirada por razones de fabricación, no por preocupaciones de seguridad."},{"q":"¿Cuál es la diferencia entre sermorelina y CJC-1295?","a":"Ambos son análogos de GHRH. Sermorelina consiste en los primeros 29 aminoácidos de la GHRH propia del cuerpo sin modificación adicional, mientras que CJC-1295 está adicionalmente estabilizado y por lo tanto tiene una vida media más larga.","q_en":"¿Cuál es la diferencia entre sermorelina y CJC-1295?","a_en":"Ambos son análogos de GHRH. Sermorelina consiste en los primeros 29 aminoácidos de la GHRH propia del cuerpo sin modificación adicional, mientras que CJC-1295 está adicionalmente estabilizado y por lo tanto tiene una vida media más larga."},{"q":"¿Está sermorelina disponible como medicamento hoy en día?","a":"No. Desde la retirada del mercado en 2008, sermorelina ya no está disponible como medicamento aprobado en la UE o en EE. UU. y se vende como producto químico de investigación.","q_en":"¿Está sermorelina disponible como medicamento hoy en día?","a_en":"No. Desde la retirada del mercado en 2008, sermorelina ya no está disponible como medicamento aprobado en la UE o en EE. UU. y se vende como producto químico de investigación."}],"seo":{"title":"Resumen de investigación sobre sermorelina","title_en":"Resumen de investigación sobre sermorelina","description":"Sermorelina explicado de forma fáctica: mecanismo de acción, aprobación histórica, datos de estudio y estado legal actual de este fragmento de GHRH.","description_en":"Sermorelina explicado de forma fáctica: mecanismo de acción, aprobación histórica, datos de estudio y estado legal actual de este fragmento de GHRH."},"demo":false,"steckbrief":{"cas":"86168-78-7","molekulargewicht":"3357.9 g/mol","aminosaeuren":29,"halbwertszeit":null,"reinheitsstandard":"≥ 98 % (HPLC, estándar comercial)","loeslichkeit":"soluble en agua y ácido acético diluido","sequenzLaenge":29,"quellen":["PubChem CID 16132413","chemverify Katalog 14.09.2026"],"reinheitsstandard_en":"≥ 98 % (HPLC, estándar comercial)","loeslichkeit_en":"soluble en agua y ácido acético diluido"},"verwandt":["cjc-1295","ipamorelin","tesamorelin","hexarelin"]},{"slug":"tesamorelin","name":"Tesamorelina","synonyme":["Egrifta","TH9507","Egrifta WR"],"kategorie":"Wachstumshormon-Achse","studienlage":"zugelassenes Arzneimittel","kurz":"Un análogo de GHRH estabilizado, aprobado en EE. UU. como el medicamento Egrifta para reducir la grasa abdominal visceral en lipodistrofia asociada al VIH.","kurz_en":"Un análogo de GHRH estabilizado, aprobado en EE. UU. como el medicamento Egrifta para reducir la grasa abdominal visceral en lipodistrofia asociada al VIH.","beschreibung":"Tesamorelina es un análogo estabilizado de la GHRH completa de 44 aminoácidos. Bajo el nombre comercial Egrifta, ha sido aprobado por la FDA de EE. UU. desde 2010 para reducir la grasa abdominal visceral en lipodistrofia asociada al VIH. Esto lo convierte en el único péptido de su clase con un estudio de aprobación de fase 3 completado en más de 800 participantes.","beschreibung_en":"Tesamorelina es un análogo estabilizado de la GHRH completa de 44 aminoácidos. Bajo el nombre comercial Egrifta, ha sido aprobado por la FDA de EE. UU. desde 2010 para reducir la grasa abdominal visceral en lipodistrofia asociada al VIH. Esto lo convierte en el único péptido de su clase con un estudio de aprobación de fase 3 completado en más de 800 participantes.","mechanismus":"Tesamorelina se une al receptor de GHRH en las células somatotróficas de la glándula pituitaria, estimulando la liberación pulsátil propia de hormona del crecimiento del cuerpo mientras que el bucle de retroalimentación de somatostatina permanece completamente intacto. La hormona del crecimiento liberada se convierte en IGF-1 en el hígado. Tesamorelina también actúa de forma relativamente selectiva sobre los receptores de hormona del crecimiento en el tejido de grasa visceral, activando la lipasa sensible a la hormona allí.","mechanismus_en":"Tesamorelina se une al receptor de GHRH en las células somatotróficas de la glándula pituitaria, estimulando la liberación pulsátil propia de hormona del crecimiento del cuerpo mientras que el bucle de retroalimentación de somatostatina permanece completamente intacto. La hormona del crecimiento liberada se convierte en IGF-1 en el hígado. Tesamorelina también actúa de forma relativamente selectiva sobre los receptores de hormona del crecimiento en el tejido de grasa visceral, activando la lipasa sensible a la hormona allí.","evidenz":[{"art":"clínico","kurz":"En un ensayo de fase 3 aleatorizado y controlado con placebo en personas con redistribución de grasa asociada al VIH, tesamorelina redujo significativamente el tejido adiposo visceral en comparación con el placebo durante 26 semanas y elevó los niveles de IGF-1.","kurz_en":"En un ensayo de fase 3 aleatorizado y controlado con placebo en personas con redistribución de grasa asociada al VIH, tesamorelina redujo significativamente el tejido adiposo visceral en comparación con el placebo durante 26 semanas y elevó los niveles de IGF-1.","quelle":"Falutz et al. 2007, New England Journal of Medicine, PMID 18057338"},{"art":"clínico","kurz":"Un ensayo aleatorizado adicional en pacientes con VIH con acumulación de grasa abdominal confirmó la reducción del tejido adiposo visceral y además mostró una disminución de la grasa hepática.","kurz_en":"Un ensayo aleatorizado adicional en pacientes con VIH con acumulación de grasa abdominal confirmó la reducción del tejido adiposo visceral y además mostró una disminución de la grasa hepática.","quelle":"Stanley et al. 2014, JAMA, PMID 25038357"}],"sicherheit":["El efecto secundario más común reportado en los ensayos fue dolor articular en un subconjunto de participantes.","Se observó retención de líquidos en las extremidades en una porción menor de los participantes, menos frecuente que con la hormona del crecimiento.","La glucosa en sangre aumentó ligeramente y temporalmente en promedio en los ensayos.","Según la información de prescripción, se considera contraindicado tesamorelina en enfermedad tumoral activa, tumor pituitario, embarazo o retinopatía diabética."],"sicherheit_en":["El efecto secundario más común reportado en los ensayos fue dolor articular en un subconjunto de participantes.","Se observó retención de líquidos en las extremidades en una porción menor de los participantes, menos frecuente que con la hormona del crecimiento.","La glucosa en sangre aumentó ligeramente y temporalmente en promedio en los ensayos.","Según la información de prescripción, se considera contraindicado tesamorelina en enfermedad tumoral activa, tumor pituitario, embarazo o retinopatía diabética."],"hinweise":["Solo con fines de investigación, no apto para uso en humanos","Un certificado de análisis no establece idoneidad médica"],"hinweise_en":["Solo con fines de investigación, no apto para uso en humanos","Un certificado de análisis no establece idoneidad médica"],"rekonstitution":"Las condiciones específicas de cada producto figuran en la documentación original del fabricante. Este portal no ofrece instrucciones de preparación ni de uso en humanos.","rekonstitution_en":"Las condiciones específicas de cada producto figuran en la documentación original del fabricante. Este portal no ofrece instrucciones de preparación ni de uso en humanos.","lagerung":"Las condiciones específicas de cada producto figuran en la documentación original del fabricante. Este portal no ofrece instrucciones de preparación ni de uso en humanos.","lagerung_en":"Las condiciones específicas de cada producto figuran en la documentación original del fabricante. Este portal no ofrece instrucciones de preparación ni de uso en humanos.","rechtsstatus":"Tesamorelina ha sido aprobada en EE. UU. bajo el nombre comercial Egrifta desde 2010 para una indicación específica en lipodistrofia asociada al VIH. No está aprobado en la UE o Suiza, y en Europa de habla alemana no está prácticamente disponible. Fuera de la indicación aprobada, cualquier uso se considera fuera de etiqueta.","rechtsstatus_en":"Tesamorelina ha sido aprobada en EE. UU. bajo el nombre comercial Egrifta desde 2010 para una indicación específica en lipodistrofia asociada al VIH. No está aprobado en la UE o Suiza, y en Europa de habla alemana no está prácticamente disponible. Fuera de la indicación aprobada, cualquier uso se considera fuera de etiqueta.","typischeMg":[2,5],"faq":[{"q":"¿Es tesamorelina un medicamento aprobado","a":"Sí, bajo el nombre Egrifta desde 2010 en EE. UU., pero solo para una indicación específica: reducir la grasa abdominal visceral en lipodistrofia asociada al VIH. No hay aprobación en la UE.","q_en":"¿Es tesamorelina un medicamento aprobado","a_en":"Sí, bajo el nombre Egrifta desde 2010 en EE. UU., pero solo para una indicación específica: reducir la grasa abdominal visceral en lipodistrofia asociada al VIH. No hay aprobación en la UE."},{"q":"¿Construye tesamorelina músculo","a":"Los estudios muestran un aumento de la masa corporal libre de grasa, pero una parte relevante de esto consiste en agua y tejido conectivo. El crecimiento muscular notable sin estimulación adicional del receptor de andrógenos no está documentado científicamente.","q_en":"¿Construye tesamorelina músculo","a_en":"Los estudios muestran un aumento de la masa corporal libre de grasa, pero una parte relevante de esto consiste en agua y tejido conectivo. El crecimiento muscular notable sin estimulación adicional del receptor de andrógenos no está documentado científicamente."},{"q":"¿Cómo difiere tesamorelina de otros análogos de GHRH","a":"Tesamorelina es el único análogo de GHRH con un estudio de aprobación de fase 3 completado en más de 800 participantes y una aprobación regulatoria activa en EE. UU. Sermorelina y CJC-1295 no han alcanzado este estado.","q_en":"¿Cómo difiere tesamorelina de otros análogos de GHRH","a_en":"Tesamorelina es el único análogo de GHRH con un estudio de aprobación de fase 3 completado en más de 800 participantes y una aprobación regulatoria activa en EE. UU. Sermorelina y CJC-1295 no han alcanzado este estado."}],"seo":{"title":"Resumen de investigación sobre tesamorelina","title_en":"Resumen de investigación sobre tesamorelina","description":"Tesamorelina (Egrifta) explicado de forma fáctica: estado de aprobación, mecanismo de acción, datos de estudios clínicos y estado legal fuera de EE. UU.","description_en":"Tesamorelina (Egrifta) explicado de forma fáctica: estado de aprobación, mecanismo de acción, datos de estudios clínicos y estado legal fuera de EE. UU."},"demo":false,"steckbrief":{"cas":"218949-48-5","molekulargewicht":"5136 g/mol","aminosaeuren":44,"halbwertszeit":"≈ 8 minutos (eliminación, información de prescripción de Egrifta SV)","reinheitsstandard":"≥ 98 % (HPLC, estándar comercial)","loeslichkeit":null,"sequenzLaenge":44,"quellen":["PubChem CID 16137828","DailyMed SPL EGRIFTA SV (Tesamorelin), Theratechnologies","chemverify Katalog 14.09.2026"],"halbwertszeit_en":"≈ 8 minutos (eliminación, información de prescripción de Egrifta SV)","reinheitsstandard_en":"≥ 98 % (HPLC, estándar comercial)"},"verwandt":["cjc-1295","ipamorelin","sermorelin","igf-1-lr3"]},{"slug":"ghk-cu","name":"GHK-Cu","synonyme":["Glicil-L-histidil-L-lisina cobre","Tripeptido de cobre-1"],"kategorie":"Haut & Kosmetik","studienlage":"frühe klinische Studien","kurz":"Un tripéptido de cobre que se encuentra de forma natural, estudiado más exhaustivamente en investigación de la piel, con datos preclínicos adicionales sobre otros tejidos.","kurz_en":"Un tripéptido de cobre que se encuentra de forma natural, estudiado más exhaustivamente en investigación de la piel, con datos preclínicos adicionales sobre otros tejidos.","beschreibung":"GHK-Cu es un tripéptido de tres aminoácidos que se encuentra de forma natural en el cuerpo y se une de forma estable a un ion cobre. Se estudia principalmente en investigación cosmética y dermatológica sobre la formación de colágeno y la renovación de la piel. Además, la investigación preclínica se centra principalmente en los posibles efectos sobre procesos inflamatorios y expresión génica en diversos modelos de tejido.","beschreibung_en":"GHK-Cu es un tripéptido de tres aminoácidos que se encuentra de forma natural en el cuerpo y se une de forma estable a un ion cobre. Se estudia principalmente en investigación cosmética y dermatológica sobre la formación de colágeno y la renovación de la piel. Además, la investigación preclínica se centra principalmente en los posibles efectos sobre procesos inflamatorios y expresión génica en diversos modelos de tejido.","mechanismus":"En las células de la piel, se ha descrito que GHK-Cu aumenta la síntesis de colágeno y elastina y activa los fibroblastos, las células que construyen el tejido conectivo. En modelos preclínicos de expresión génica, GHK-Cu mostró una regulación dependiente del contexto de numerosos genes relacionados con la reparación de tejidos, el estrés oxidativo y la inflamación. El grado en que estos efectos de expresión génica se transfieren a los humanos vivos es objeto de investigación en curso.","mechanismus_en":"En las células de la piel, se ha descrito que GHK-Cu aumenta la síntesis de colágeno y elastina y activa los fibroblastos, las células que construyen el tejido conectivo. En modelos preclínicos de expresión génica, GHK-Cu mostró una regulación dependiente del contexto de numerosos genes relacionados con la reparación de tejidos, el estrés oxidativo y la inflamación. El grado en que estos efectos de expresión génica se transfieren a los humanos vivos es objeto de investigación en curso.","evidenz":[{"art":"clínico","kurz":"Un estudio de aplicación de doce semanas en mujeres con signos visibles de envejecimiento de la piel describió un aumento del grosor de la piel, una reducción de la profundidad de las arrugas y un aumento confirmado por biopsia de la actividad de las células de la piel bajo una crema de GHK-Cu, en comparación con la línea de base.","kurz_en":"Un estudio de aplicación de doce semanas en mujeres con signos visibles de envejecimiento de la piel describió un aumento del grosor de la piel, una reducción de la profundidad de las arrugas y un aumento confirmado por biopsia de la actividad de las células de la piel bajo una crema de GHK-Cu, en comparación con la línea de base.","quelle":"Finkley et al. 2005, in: Cosmeceuticals and Active Cosmetics: Drugs vs. Cosmetics"},{"art":"preclínico","kurz":"Un estudio en un modelo murino de colitis ulcerosa describió que GHK-Cu apoya la función de la barrera intestinal a través de la vía SIRT1/STAT3 y reduce los mensajeros inflamatorios.","kurz_en":"Un estudio en un modelo murino de colitis ulcerosa describió que GHK-Cu apoya la función de la barrera intestinal a través de la vía SIRT1/STAT3 y reduce los mensajeros inflamatorios.","quelle":"Mao et al. 2025, Frontiers in Pharmacology, PMID 40672369"}],"sicherheit":["Los estudios tópicos disponibles no describieron preocupaciones de seguridad relevantes.","GHK-Cu contiene cobre unido, a concentraciones cosméticas típicas esto no está asociado con sobrecarga de cobre.","Para uso inyectable y sistémico, no hay estudios de seguridad en humanos controlados con placebo disponibles.","Los productos de fabricación no controlada conllevan un riesgo de contaminación que es independiente de la molécula misma."],"sicherheit_en":["Los estudios tópicos disponibles no describieron preocupaciones de seguridad relevantes.","GHK-Cu contiene cobre unido, a concentraciones cosméticas típicas esto no está asociado con sobrecarga de cobre.","Para uso inyectable y sistémico, no hay estudios de seguridad en humanos controlados con placebo disponibles.","Los productos de fabricación no controlada conllevan un riesgo de contaminación que es independiente de la molécula misma."],"hinweise":["Solo con fines de investigación, no apto para uso en humanos","Un certificado de análisis no establece idoneidad médica"],"hinweise_en":["Solo con fines de investigación, no apto para uso en humanos","Un certificado de análisis no establece idoneidad médica"],"rekonstitution":"Las condiciones específicas de cada producto figuran en la documentación original del fabricante. Este portal no ofrece instrucciones de preparación ni de uso en humanos.","rekonstitution_en":"Las condiciones específicas de cada producto figuran en la documentación original del fabricante. Este portal no ofrece instrucciones de preparación ni de uso en humanos.","lagerung":"Las condiciones específicas de cada producto figuran en la documentación original del fabricante. Este portal no ofrece instrucciones de preparación ni de uso en humanos.","lagerung_en":"Las condiciones específicas de cada producto figuran en la documentación original del fabricante. Este portal no ofrece instrucciones de preparación ni de uso en humanos.","rechtsstatus":"En formulaciones cosméticas, el tripéptido de cobre-1 está listado como ingrediente cosmético en los Estados Unidos. En la UE y Alemania, la forma de investigación inyectable se sitúa en un área gris legal y no está aprobada como medicamento.","rechtsstatus_en":"En formulaciones cosméticas, el tripéptido de cobre-1 está listado como ingrediente cosmético en los Estados Unidos. En la UE y Alemania, la forma de investigación inyectable se sitúa en un área gris legal y no está aprobada como medicamento.","typischeMg":[],"faq":[{"q":"¿Está aprobado GHK-Cu en cosméticos?","a":"En los Estados Unidos, el tripéptido de cobre-1 está listado como ingrediente cosmético. La UE no tiene una aprobación independiente comparable, aunque los productos cosméticos se venden ampliamente.","q_en":"¿Está aprobado GHK-Cu en cosméticos?","a_en":"En los Estados Unidos, el tripéptido de cobre-1 está listado como ingrediente cosmético. La UE no tiene una aprobación independiente comparable, aunque los productos cosméticos se venden ampliamente."},{"q":"¿Dónde está la evidencia más sólida para GHK-Cu?","a":"Los datos humanos más sólidos provienen de estudios tópicos de la piel. El uso sistémico e inyectado se basa principalmente en modelos animales y celulares preclínicos.","q_en":"¿Dónde está la evidencia más sólida para GHK-Cu?","a_en":"Los datos humanos más sólidos provienen de estudios tópicos de la piel. El uso sistémico e inyectado se basa principalmente en modelos animales y celulares preclínicos."},{"q":"¿Es el cobre en GHK-Cu un riesgo de seguridad?","a":"A concentraciones cosméticas típicas esto no se describe como un riesgo relevante. La literatura considera la deficiencia de cobre más probable que la sobrecarga.","q_en":"¿Es el cobre en GHK-Cu un riesgo de seguridad?","a_en":"A concentraciones cosméticas típicas esto no se describe como un riesgo relevante. La literatura considera la deficiencia de cobre más probable que la sobrecarga."}],"seo":{"title":"GHK-Cu: perfil de investigación y evidencia","title_en":"GHK-Cu: perfil de investigación y evidencia","description":"Resumen de GHK-Cu: tripéptido de cobre, mecanismo, investigación de la piel y perfil de seguridad, presentado de forma fáctica para el contexto de la investigación.","description_en":"Resumen de GHK-Cu: tripéptido de cobre, mecanismo, investigación de la piel y perfil de seguridad, presentado de forma fáctica para el contexto de la investigación."},"demo":false,"steckbrief":{"cas":"89030-95-5","molekulargewicht":"402.92 g/mol","aminosaeuren":3,"halbwertszeit":null,"reinheitsstandard":"≥ 98 % (HPLC, estándar comercial, polvo azul)","loeslichkeit":null,"sequenzLaenge":3,"quellen":["PubChem CID 71587328","chemverify Katalog 14.09.2026"],"reinheitsstandard_en":"≥ 98 % (HPLC, estándar comercial, polvo azul)"},"verwandt":["bpc-157","tb-500","pentadeca-arginate"]},{"slug":"dihexa","name":"Dihexa","synonyme":["PNB-0408","N-Hexanoil-Tyr-Ile-(6)aminohexanamida"],"kategorie":"Kognition","studienlage":"präklinisch","kurz":"Un análogo sintético del angiotensina IV estudiado en modelos preclínicos de ratas de función de la memoria, sin datos humanos publicados hasta la fecha.","kurz_en":"Un análogo sintético del angiotensina IV estudiado en modelos preclínicos de ratas de función de la memoria, sin datos humanos publicados hasta la fecha.","beschreibung":"Dihexa es un peptidomimético sintético derivado del propio angiotensina IV del cuerpo, desarrollado en el grupo de investigación de Joseph Harding en la Universidad Estatal de Washington. Hasta la fecha se ha estudiado exclusivamente en modelos preclínicos, principalmente ratas, en relación con el rendimiento de aprendizaje y memoria. No existen estudios humanos publicados para dihexa, por lo que su perfil de seguridad en humanos no ha sido examinado.","beschreibung_en":"Dihexa es un peptidomimético sintético derivado del propio angiotensina IV del cuerpo, desarrollado en el grupo de investigación de Joseph Harding en la Universidad Estatal de Washington. Hasta la fecha se ha estudiado exclusivamente en modelos preclínicos, principalmente ratas, en relación con el rendimiento de aprendizaje y memoria. No existen estudios humanos publicados para dihexa, por lo que su perfil de seguridad en humanos no ha sido examinado.","mechanismus":"Dihexa se describe como un análogo de angiotensina IV metabolizado estabilizado que es oralmente disponible y capaz de cruzar la barrera hematoencefálica. A diferencia del propio angiotensina IV del cuerpo, se informa en modelos celulares que se une directamente al receptor de factor de crecimiento hepatocitario c-Met, a través del cual se propone que desencadene el crecimiento dendrítico y la sinaptogénesis. Parte del trabajo que originalmente respaldó este mecanismo fue retirado en 2025 debido a manipulación de imágenes confirmada, por lo que el mecanismo de acción preciso no puede considerarse científicamente establecido.","mechanismus_en":"Dihexa se describe como un análogo de angiotensina IV metabolizado estabilizado que es oralmente disponible y capaz de cruzar la barrera hematoencefálica. A diferencia del propio angiotensina IV del cuerpo, se informa en modelos celulares que se une directamente al receptor de factor de crecimiento hepatocitario c-Met, a través del cual se propone que desencadene el crecimiento dendrítico y la sinaptogénesis. Parte del trabajo que originalmente respaldó este mecanismo fue retirado en 2025 debido a manipulación de imágenes confirmada, por lo que el mecanismo de acción preciso no puede considerarse científicamente establecido.","evidenz":[{"art":"preclínico","kurz":"En ratas, el dihexa administrado oralmente (2 mg/kg) revirtió los déficits de memoria inducidos por escopolamina en la prueba del laberinto de agua de Morris y mejoró el aprendizaje en animales de 24 meses.","kurz_en":"En ratas, el dihexa administrado oralmente (2 mg/kg) revirtió los déficits de memoria inducidos por escopolamina en la prueba del laberinto de agua de Morris y mejoró el aprendizaje en animales de 24 meses.","quelle":"McCoy AT et al. 2013, Journal of Pharmacology and Experimental Therapeutics, PMID 23055539 (This paper has carried an Expression of Concern from the publisher since 2021 over possible image manipulation, no retraction)"},{"art":"preclínico","kurz":"En un modelo de ratas de síntomas similares a la enfermedad de Huntington inducidos por ácido 3-nitropropiónico, PNB-0408 (dihexa) no mostró ninguna mejoría significativa en los puntos finales motores o neuropatológicos en comparación con los animales de control.","kurz_en":"En un modelo de ratas de síntomas similares a la enfermedad de Huntington inducidos por ácido 3-nitropropiónico, PNB-0408 (dihexa) no mostró ninguna mejoría significativa en los puntos finales motores o neuropatológicos en comparación con los animales de control.","quelle":"Wells RG et al. 2024, Journal of Huntington's Disease, Bd. 13, Nr. 1, S. 55-66, PMID 38489193"}],"sicherheit":["No existen estudios humanos publicados para dihexa, y su perfil de seguridad en humanos no ha sido examinado.","Todos los datos publicados hasta la fecha provienen de modelos animales, principalmente ratas, con períodos de observación de solo unas pocas semanas.","Un estudio de 2013 sobre análogos de angiotensina IV metabolizados estabilizados ha tenido una Expresión de Preocupación editorial desde 2021 sobre posible manipulación de imágenes, sin que el artículo haya sido retirado.","Un artículo de 2014 sobre el mecanismo subyacente HGF/c-Met fue formalmente retirado en 2025 después de que una investigación confirmara figuras falsificadas y manipuladas.","Los datos de seguridad a largo plazo, incluidos los de estudios en animales, aún no están disponibles."],"sicherheit_en":["No existen estudios humanos publicados para dihexa, y su perfil de seguridad en humanos no ha sido examinado.","Todos los datos publicados hasta la fecha provienen de modelos animales, principalmente ratas, con períodos de observación de solo unas pocas semanas.","Un estudio de 2013 sobre análogos de angiotensina IV metabolizados estabilizados ha tenido una Expresión de Preocupación editorial desde 2021 sobre posible manipulación de imágenes, sin que el artículo haya sido retirado.","Un artículo de 2014 sobre el mecanismo subyacente HGF/c-Met fue formalmente retirado en 2025 después de que una investigación confirmara figuras falsificadas y manipuladas.","Los datos de seguridad a largo plazo, incluidos los de estudios en animales, aún no están disponibles."],"hinweise":["Solo con fines de investigación, no apto para uso en humanos","Un certificado de análisis no establece idoneidad médica"],"hinweise_en":["Solo con fines de investigación, no apto para uso en humanos","Un certificado de análisis no establece idoneidad médica"],"rekonstitution":"Las condiciones específicas de cada producto figuran en la documentación original del fabricante. Este portal no ofrece instrucciones de preparación ni de uso en humanos.","rekonstitution_en":"Las condiciones específicas de cada producto figuran en la documentación original del fabricante. Este portal no ofrece instrucciones de preparación ni de uso en humanos.","lagerung":"Las condiciones específicas de cada producto figuran en la documentación original del fabricante. Este portal no ofrece instrucciones de preparación ni de uso en humanos.","lagerung_en":"Las condiciones específicas de cada producto figuran en la documentación original del fabricante. Este portal no ofrece instrucciones de preparación ni de uso en humanos.","rechtsstatus":"Dihexa nunca ha entrado en un proceso de aprobación clínica para uso humano y no está aprobado como medicamento en Alemania, la UE o los Estados Unidos. Se vende exclusivamente como un químico de investigación para uso de laboratorio.","rechtsstatus_en":"Dihexa nunca ha entrado en un proceso de aprobación clínica para uso humano y no está aprobado como medicamento en Alemania, la UE o los Estados Unidos. Se vende exclusivamente como un químico de investigación para uso de laboratorio.","typischeMg":[],"faq":[{"q":"¿Existen estudios humanos sobre dihexa","a":"No. Todos los datos publicados sobre dihexa hasta la fecha provienen de modelos animales, principalmente ratas. No se ha examinado un perfil de seguridad para el uso humano, por lo que no existen datos de tolerabilidad ni de eficacia en humanos.","q_en":"¿Existen estudios humanos sobre dihexa","a_en":"No. Todos los datos publicados sobre dihexa hasta la fecha provienen de modelos animales, principalmente ratas. No se ha examinado un perfil de seguridad para el uso humano, por lo que no existen datos de tolerabilidad ni de eficacia en humanos."},{"q":"¿Cómo se explica el mecanismo de acción de dihexa?","a":"Se informa que dihexa se une al receptor del factor de crecimiento de hepatocitos c-Met, una vía propuesta para desencadenar la sinaptogénesis en modelos celulares. Parte del trabajo que originalmente respaldó este mecanismo fue retirado en 2025 debido a datos falsificados.","q_en":"¿Cómo se explica el mecanismo de acción de dihexa?","a_en":"Se informa que dihexa se une al receptor del factor de crecimiento de hepatocitos c-Met, una vía propuesta para desencadenar la sinaptogénesis en modelos celulares. Parte del trabajo que originalmente respaldó este mecanismo fue retirado en 2025 debido a datos falsificados."},{"q":"¿Es dihexa un medicamento aprobado?","a":"No. Dihexa nunca ha entrado en un proceso de aprobación clínica para uso humano y no está aprobado como medicamento en Alemania, la UE o los Estados Unidos. Se vende exclusivamente como un químico de investigación.","q_en":"¿Es dihexa un medicamento aprobado?","a_en":"No. Dihexa nunca ha entrado en un proceso de aprobación clínica para uso humano y no está aprobado como medicamento en Alemania, la UE o los Estados Unidos. Se vende exclusivamente como un químico de investigación."}],"seo":{"title":"Dihexa: Estado de investigación del análogo de la angiotensina IV","title_en":"Dihexa: Estado de investigación del análogo de la angiotensina IV","description":"Dihexa explicado de forma fáctica: origen, mecanismo de acción, estado del estudio preclínico y preguntas de seguridad abiertas en torno a este péptido de investigación.","description_en":"Dihexa explicado de forma fáctica: origen, mecanismo de acción, estado del estudio preclínico y preguntas de seguridad abiertas en torno a este péptido de investigación."},"demo":false,"steckbrief":{"cas":"1401708-83-5","molekulargewicht":"504.7 g/mol","aminosaeuren":2,"halbwertszeit":null,"reinheitsstandard":null,"loeslichkeit":null,"sequenzLaenge":2,"quellen":["PubChem CID 129010512","chemverify Katalog 14.09.2026"]},"verwandt":["semax","selank","dsip"]},{"slug":"dsip","name":"DSIP","synonyme":["Péptido Inductor de Sueño Delta","Péptido de Sueño Delta"],"kategorie":"Kognition","studienlage":"klinisch untersucht","kurz":"Una de las neuropeptidas más estudiadas, originalmente aislada como un mensajero inductor del sueño del cerebro de conejos dormidos, con un cuerpo de investigación inconsistente hasta la fecha.","kurz_en":"Una de las neuropeptidas más estudiadas, originalmente aislada como un mensajero inductor del sueño del cerebro de conejos dormidos, con un cuerpo de investigación inconsistente hasta la fecha.","beschreibung":"DSIP (péptido inductor del sueño delta) es un nonapéptido aislado por primera vez en 1977 por Schoenenberger y Monnier a partir de la sangre venosa cerebral de conejos dormidos y nombrado por su capacidad para desencadenar actividad de EEG de onda delta en ese modelo animal. Durante las décadas siguientes se estudió en numerosos ensayos en humanos sobre el sueño, el eje del estrés y la regulación hormonal. El efecto promotor del sueño descrito originalmente no se ha reproducido de manera fiable en estudios independientes y más rigurosos.","beschreibung_en":"DSIP (péptido inductor del sueño delta) es un nonapéptido aislado por primera vez en 1977 por Schoenenberger y Monnier a partir de la sangre venosa cerebral de conejos dormidos y nombrado por su capacidad para desencadenar actividad de EEG de onda delta en ese modelo animal. Durante las décadas siguientes se estudió en numerosos ensayos en humanos sobre el sueño, el eje del estrés y la regulación hormonal. El efecto promotor del sueño descrito originalmente no se ha reproducido de manera fiable en estudios independientes y más rigurosos.","mechanismus":"El mecanismo de acción preciso de DSIP sigue sin resolverse a pesar de décadas de investigación. La participación propuesta incluye un papel en la regulación del eje hipotalámico-pituitario-adrenal e interacciones con las vías de señalización GABAérgicas y opioides. Hasta la fecha no se ha descrito un receptor específico y claramente identificado para DSIP, lo que complica la interpretación de sus efectos.","mechanismus_en":"El mecanismo de acción preciso de DSIP sigue sin resolverse a pesar de décadas de investigación. La participación propuesta incluye un papel en la regulación del eje hipotalámico-pituitario-adrenal e interacciones con las vías de señalización GABAérgicas y opioides. Hasta la fecha no se ha descrito un receptor específico y claramente identificado para DSIP, lo que complica la interpretación de sus efectos.","evidenz":[{"art":"preclínico","kurz":"El aislamiento original a partir de la sangre cerebral de conejos dormidos identificó la secuencia del nonapéptido y mostró una mayor actividad de EEG de onda delta en el modelo animal tras la administración intraventricular.","kurz_en":"El aislamiento original a partir de la sangre cerebral de conejos dormidos identificó la secuencia del nonapéptido y mostró una mayor actividad de EEG de onda delta en el modelo animal tras la administración intraventricular.","quelle":"Schoenenberger GA, Monnier M 1977, Proceedings of the National Academy of Sciences, Bd. 74(3), S. 1282-1286, PMID 265572"},{"art":"clínico","kurz":"En un estudio de crossover doble ciego en pacientes con insomnio crónico con monitorización polisomnográfica durante cuatro noches, la mejora del sueño bajo DSIP fue menor en comparación con el placebo.","kurz_en":"En un estudio de crossover doble ciego en pacientes con insomnio crónico con monitorización polisomnográfica durante cuatro noches, la mejora del sueño bajo DSIP fue menor en comparación con el placebo.","quelle":"Monti JM et al. 1987, International Journal of Clinical Pharmacology Research, Bd. 7(2), S. 105-110, PMID 3583493"},{"art":"clínico","kurz":"Una revisión que resume tres décadas de investigación humana y animal concluye que el efecto inductor del sueño de DSIP originalmente postulado no pudo ser confirmado consistentemente en estudios independientes.","kurz_en":"Una revisión que resume tres décadas de investigación humana y animal concluye que el efecto inductor del sueño de DSIP originalmente postulado no pudo ser confirmado consistentemente en estudios independientes.","quelle":"Kovalzon VM, Strekalova TV 2006, Journal of Neurochemistry, Bd. 97(2), S. 303-309, PMID 16539679"},{"art":"preclínico","kurz":"Un estudio preclínico de 2024 examinó un péptido de fusión DSIP en un modelo de ratón de insomnio inducido farmacológicamente y describió efectos en los niveles de neurotransmisores como serotonina y dopamina.","kurz_en":"Un estudio preclínico de 2024 examinó un péptido de fusión DSIP en un modelo de ratón de insomnio inducido farmacológicamente y describió efectos en los niveles de neurotransmisores como serotonina y dopamina.","quelle":"Mu X et al. 2024, Frontiers in Pharmacology, Bd. 15, Artikel 1439536, PMID 39444618"}],"sicherheit":["El efecto promotor del sueño descrito en estudios humanos más antiguos no se considera reproducible de manera fiable, según la literatura de revisión actual.","Muchos de los estudios humanos disponibles datan de la década de 1980 y muestran debilidades metodológicas como tamaños de muestra pequeños y períodos de observación cortos.","En un estudio con voluntarios sanos, la infusión de DSIP no alteró mediblemente la secreción de ACTH y cortisol estimulados por CRH.","No hay datos de seguridad humana a largo plazo reproducidos de forma independiente."],"sicherheit_en":["El efecto promotor del sueño descrito en estudios humanos más antiguos no se considera reproducible de manera fiable, según la literatura de revisión actual.","Muchos de los estudios humanos disponibles datan de la década de 1980 y muestran debilidades metodológicas como tamaños de muestra pequeños y períodos de observación cortos.","En un estudio con voluntarios sanos, la infusión de DSIP no alteró mediblemente la secreción de ACTH y cortisol estimulados por CRH.","No hay datos de seguridad humana a largo plazo reproducidos de forma independiente."],"hinweise":["Solo con fines de investigación, no apto para uso en humanos","Un certificado de análisis no establece idoneidad médica"],"hinweise_en":["Solo con fines de investigación, no apto para uso en humanos","Un certificado de análisis no establece idoneidad médica"],"rekonstitution":"Las condiciones específicas de cada producto figuran en la documentación original del fabricante. Este portal no ofrece instrucciones de preparación ni de uso en humanos.","rekonstitution_en":"Las condiciones específicas de cada producto figuran en la documentación original del fabricante. Este portal no ofrece instrucciones de preparación ni de uso en humanos.","lagerung":"Las condiciones específicas de cada producto figuran en la documentación original del fabricante. Este portal no ofrece instrucciones de preparación ni de uso en humanos.","lagerung_en":"Las condiciones específicas de cada producto figuran en la documentación original del fabricante. Este portal no ofrece instrucciones de preparación ni de uso en humanos.","rechtsstatus":"DSIP no está aprobado como medicamento en Alemania, la UE o Estados Unidos, donde se vende exclusivamente como un químico de investigación.","rechtsstatus_en":"DSIP no está aprobado como medicamento en Alemania, la UE o Estados Unidos, donde se vende exclusivamente como un químico de investigación.","typischeMg":[5,10],"faq":[{"q":"¿Se ha confirmado el efecto promotor del sueño de DSIP en estudios?","a":"La evidencia es inconsistente. Los estudios iniciales informaron efectos promotores del sueño, pero una revisión de 2006 concluyó que este efecto no pudo ser reproducido consistentemente en estudios independientes.","q_en":"¿Se ha confirmado el efecto promotor del sueño de DSIP en estudios?","a_en":"La evidencia es inconsistente. Los estudios iniciales informaron efectos promotores del sueño, pero una revisión de 2006 concluyó que este efecto no pudo ser reproducido consistentemente en estudios independientes."},{"q":"De dónde viene el nombre DSIP","a":"DSIP significa péptido inductor del sueño delta. El nombre se remonta a su primera descripción en 1977, cuando se aisló de la sangre cerebral de conejos dormidos y se desencadenó actividad de EEG de ondas delta en ese modelo animal.","q_en":"De dónde viene el nombre DSIP","a_en":"DSIP significa péptido inductor del sueño delta. El nombre se remonta a su primera descripción en 1977, cuando se aisló de la sangre cerebral de conejos dormidos y se desencadenó actividad de EEG de ondas delta en ese modelo animal."},{"q":"¿Está DSIP legalmente disponible en Alemania?","a":"DSIP no está aprobado como medicamento en Alemania o la UE. Se ofrece exclusivamente como químico de investigación para fines de laboratorio, no para uso humano.","q_en":"¿Está DSIP legalmente disponible en Alemania?","a_en":"DSIP no está aprobado como medicamento en Alemania o la UE. Se ofrece exclusivamente como químico de investigación para fines de laboratorio, no para uso humano."}],"seo":{"title":"DSIP: Péptido de Investigación Con Evidencia Inconsistente","title_en":"DSIP: Péptido de Investigación Con Evidencia Inconsistente","description":"DSIP de un vistazo: origen, mecanismo, estado del estudio y perfil de seguridad de uno de los péptidos del sueño más estudiados.","description_en":"DSIP de un vistazo: origen, mecanismo, estado del estudio y perfil de seguridad de uno de los péptidos del sueño más estudiados."},"demo":false,"steckbrief":{"cas":"62568-57-4","molekulargewicht":"848.8 g/mol","aminosaeuren":9,"halbwertszeit":null,"reinheitsstandard":"≥ 98 % (HPLC, estándar comercial)","loeslichkeit":null,"sequenzLaenge":9,"quellen":["PubChem CID 68816","chemverify Katalog 14.09.2026"],"reinheitsstandard_en":"≥ 98 % (HPLC, estándar comercial)"},"verwandt":["selank","semax","dihexa"]},{"slug":"selank","name":"Selank","synonyme":[],"kategorie":"Kognition","studienlage":"klinisch untersucht","kurz":"Un análogo heptapéptido sintético del tuftsin propio del cuerpo, estudiado en investigación sobre la regulación de la ansiedad y la función cognitiva.","kurz_en":"Un análogo heptapéptido sintético del tuftsin propio del cuerpo, estudiado en investigación sobre la regulación de la ansiedad y la función cognitiva.","beschreibung":"Selank es un heptapéptido derivado del tuftsin tetrapeptídico propio del cuerpo, desarrollado originalmente en Rusia como ansiolítico. La investigación lo vincula a efectos reguladores de la ansiedad y de apoyo cognitivo leve, sin la sedación típica de las benzodiazepinas.","beschreibung_en":"Selank es un heptapéptido derivado del tuftsin tetrapeptídico propio del cuerpo, desarrollado originalmente en Rusia como ansiolítico. La investigación lo vincula a efectos reguladores de la ansiedad y de apoyo cognitivo leve, sin la sedación típica de las benzodiazepinas.","mechanismus":"Se describe que Selank inhibe las encefalinasas, las enzimas que degradan las encefalinas propias del cuerpo, con lo que sus niveles se mantienen elevados durante más tiempo. También se asocia con la modulación del receptor GABA en un sitio de unión distinto al de las benzodiazepinas y con efectos indirectos sobre el sistema dopaminérgico a través de la vía de las encefalinas.","mechanismus_en":"Se describe que Selank inhibe las encefalinasas, las enzimas que degradan las encefalinas propias del cuerpo, con lo que sus niveles se mantienen elevados durante más tiempo. También se asocia con la modulación del receptor GABA en un sitio de unión distinto al de las benzodiazepinas y con efectos indirectos sobre el sistema dopaminérgico a través de la vía de las encefalinas.","evidenz":[{"art":"clínico","kurz":"Un ensayo aleatorizado en 62 personas con trastorno de ansiedad generalizada o neurastenia comparó el efecto ansiolítico de selank con medazepam, con mejoras observadas adicionalmente en energía y concentración sin sedación.","kurz_en":"Un ensayo aleatorizado en 62 personas con trastorno de ansiedad generalizada o neurastenia comparó el efecto ansiolítico de selank con medazepam, con mejoras observadas adicionalmente en energía y concentración sin sedación.","quelle":"Zozulya AA et al. 2008, Bjulleten Eksperimentalnoj Biologii i Mediciny, PMID 18454096"},{"art":"clínico","kurz":"En un estudio de fMRI con 52 participantes sanos, la administración de selank se asoció con conectividad funcional alterada entre la amígdala derecha y la corteza temporal derecha, medible tan pronto como 5 minutos después de la aplicación.","kurz_en":"En un estudio de fMRI con 52 participantes sanos, la administración de selank se asoció con conectividad funcional alterada entre la amígdala derecha y la corteza temporal derecha, medible tan pronto como 5 minutos después de la aplicación.","quelle":"Panikratova KR et al. 2020, Doklady Biological Sciences, Bd. 490, S. 9-11"}],"sicherheit":["La literatura de estudios disponibles describe efectos leves y transitorios como irritación nasal con uso intranasal.","El uso concurrente con benzodiazepinas se discute en la literatura debido a posible interacción mutua de receptores.","Los datos de seguridad a largo plazo robustos de estudios independientes realizados fuera de Rusia aún no están disponibles."],"sicherheit_en":["La literatura de estudios disponibles describe efectos leves y transitorios como irritación nasal con uso intranasal.","El uso concurrente con benzodiazepinas se discute en la literatura debido a posible interacción mutua de receptores.","Los datos de seguridad a largo plazo robustos de estudios independientes realizados fuera de Rusia aún no están disponibles."],"hinweise":["Solo con fines de investigación, no apto para uso en humanos","Un certificado de análisis no establece idoneidad médica"],"hinweise_en":["Solo con fines de investigación, no apto para uso en humanos","Un certificado de análisis no establece idoneidad médica"],"rekonstitution":"Las condiciones específicas de cada producto figuran en la documentación original del fabricante. Este portal no ofrece instrucciones de preparación ni de uso en humanos.","rekonstitution_en":"Las condiciones específicas de cada producto figuran en la documentación original del fabricante. Este portal no ofrece instrucciones de preparación ni de uso en humanos.","lagerung":"Las condiciones específicas de cada producto figuran en la documentación original del fabricante. Este portal no ofrece instrucciones de preparación ni de uso en humanos.","lagerung_en":"Las condiciones específicas de cada producto figuran en la documentación original del fabricante. Este portal no ofrece instrucciones de preparación ni de uso en humanos.","rechtsstatus":"Selank está aprobado como ansiolítico en Rusia, pero no está aprobado como medicamento en Alemania, la UE o Estados Unidos, donde se vende exclusivamente como producto químico de investigación.","rechtsstatus_en":"Selank está aprobado como ansiolítico en Rusia, pero no está aprobado como medicamento en Alemania, la UE o Estados Unidos, donde se vende exclusivamente como producto químico de investigación.","typischeMg":[5,10],"faq":[{"q":"¿Es selank lo mismo que una benzodiazepina?","a":"No. Ambos actúan sobre el sistema GABA de maneras diferentes. Selank se une en un sitio diferente y no mostró potencial sedante ni de dependencia en estudios, a diferencia de las benzodiazepinas clásicas.","q_en":"¿Es selank lo mismo que una benzodiazepina?","a_en":"No. Ambos actúan sobre el sistema GABA de maneras diferentes. Selank se une en un sitio diferente y no mostró potencial sedante ni de dependencia en estudios, a diferencia de las benzodiazepinas clásicas."},{"q":"¿De dónde proviene selank?","a":"Selank fue desarrollado en la Academia de Ciencias de Rusia a partir del tuftsin peptídico propio del cuerpo, con una adición estabilizadora para una mayor duración en el cuerpo.","q_en":"¿De dónde proviene selank?","a_en":"Selank fue desarrollado en la Academia de Ciencias de Rusia a partir del tuftsin peptídico propio del cuerpo, con una adición estabilizadora para una mayor duración en el cuerpo."},{"q":"¿Está selank legalmente disponible en Alemania?","a":"Selank no está aprobado como medicamento en Alemania o la UE. Se ofrece exclusivamente como producto químico de investigación para fines de laboratorio, no para uso humano.","q_en":"¿Está selank legalmente disponible en Alemania?","a_en":"Selank no está aprobado como medicamento en Alemania o la UE. Se ofrece exclusivamente como producto químico de investigación para fines de laboratorio, no para uso humano."}],"seo":{"title":"Selank: Péptido de Investigación para la Regulación de la Ansiedad","title_en":"Selank: Péptido de Investigación para la Regulación de la Ansiedad","description":"Selank de un vistazo: origen, mecanismo, estado del estudio y perfil de seguridad de un péptido de investigación estudiado para la regulación de la ansiedad y la cognición.","description_en":"Selank de un vistazo: origen, mecanismo, estado del estudio y perfil de seguridad de un péptido de investigación estudiado para la regulación de la ansiedad y la cognición."},"demo":false,"steckbrief":{"cas":"129954-34-3","molekulargewicht":"751.9 g/mol","aminosaeuren":7,"halbwertszeit":null,"reinheitsstandard":"≥ 98 % (HPLC, estándar comercial)","loeslichkeit":null,"sequenzLaenge":7,"quellen":["PubChem CID 11765600","chemverify Katalog 14.09.2026"],"reinheitsstandard_en":"≥ 98 % (HPLC, estándar comercial)"},"verwandt":["semax","epitalon","dihexa"]},{"slug":"semax","name":"Semax","synonyme":[],"kategorie":"Kognition","studienlage":"klinisch untersucht","kurz":"Un heptapéptido derivado de ACTH sintético, aprobado en Rusia para neuroprotección y estudiado en investigación sobre cognición y adaptación al estrés.","kurz_en":"Un heptapéptido derivado de ACTH sintético, aprobado en Rusia para neuroprotección y estudiado en investigación sobre cognición y adaptación al estrés.","beschreibung":"Semax es un heptapeptido derivado del fragmento ACTH(4-10) de la hormona del estrés ACTH, aprobado como medicamento para el accidente cerebrovascular isquémico en Rusia. La investigación también lo examina en relación con la neuroplasticidad y la función cognitiva, sin activar el eje del cortisol.","beschreibung_en":"Semax es un heptapeptido derivado del fragmento ACTH(4-10) de la hormona del estrés ACTH, aprobado como medicamento para el accidente cerebrovascular isquémico en Rusia. La investigación también lo examina en relación con la neuroplasticidad y la función cognitiva, sin activar el eje del cortisol.","mechanismus":"Se describe que Semax aumenta la expresión de BDNF y su receptor TrkB, lo cual está relacionado con la plasticidad neuronal. Como derivado de ACTH, también se une a los receptores de melanocortina, lo que puede influir en los niveles de dopamina, serotonina y noradrenalina. La unión al receptor mu-opioide, descrito en 2025, se ha relacionado con efectos antioxidantes.","mechanismus_en":"Se describe que Semax aumenta la expresión de BDNF y su receptor TrkB, lo cual está relacionado con la plasticidad neuronal. Como derivado de ACTH, también se une a los receptores de melanocortina, lo que puede influir en los niveles de dopamina, serotonina y noradrenalina. La unión al receptor mu-opioide, descrito en 2025, se ha relacionado con efectos antioxidantes.","evidenz":[{"art":"preclínico","kurz":"En un estudio en ratas, una aplicación intranasal única de semax aumentó los niveles de proteína BDNF hipocampal 1,4 veces y la fosforilación de TrkB 1,6 veces.","kurz_en":"En un estudio en ratas, una aplicación intranasal única de semax aumentó los niveles de proteína BDNF hipocampal 1,4 veces y la fosforilación de TrkB 1,6 veces.","quelle":"PubMed ID 14556513"},{"art":"clínico","kurz":"En el mismo estudio de fMRI con 52 participantes sanos, semax también mostró conectividad funcional alterada entre la amígdala y la corteza temporal, con efectos que fueron en parte distinguibles de selank.","kurz_en":"En el mismo estudio de fMRI con 52 participantes sanos, semax también mostró conectividad funcional alterada entre la amígdala y la corteza temporal, con efectos que fueron en parte distinguibles de selank.","quelle":"Panikratova KR et al. 2020, Doklady Biological Sciences, Bd. 490, S. 9-11"}],"sicherheit":["Los estudios en animales han reportado hasta ahora no efectos tóxicos graves.","Se ha descrito una interacción in vitro con enzimas dependientes de cobre, su relevancia clínica aún no establecida.","Aún no se dispone de datos de seguridad humana a largo plazo, independientes y de procedencia occidental."],"sicherheit_en":["Los estudios en animales han reportado hasta ahora no efectos tóxicos graves.","Se ha descrito una interacción in vitro con enzimas dependientes de cobre, su relevancia clínica aún no establecida.","Aún no se dispone de datos de seguridad humana a largo plazo, independientes y de procedencia occidental."],"hinweise":["Solo con fines de investigación, no apto para uso en humanos","Un certificado de análisis no establece idoneidad médica"],"hinweise_en":["Solo con fines de investigación, no apto para uso en humanos","Un certificado de análisis no establece idoneidad médica"],"rekonstitution":"Las condiciones específicas de cada producto figuran en la documentación original del fabricante. Este portal no ofrece instrucciones de preparación ni de uso en humanos.","rekonstitution_en":"Las condiciones específicas de cada producto figuran en la documentación original del fabricante. Este portal no ofrece instrucciones de preparación ni de uso en humanos.","lagerung":"Las condiciones específicas de cada producto figuran en la documentación original del fabricante. Este portal no ofrece instrucciones de preparación ni de uso en humanos.","lagerung_en":"Las condiciones específicas de cada producto figuran en la documentación original del fabricante. Este portal no ofrece instrucciones de preparación ni de uso en humanos.","rechtsstatus":"Semax está aprobado como medicamento para la neuroprotección en Rusia, pero no está aprobado como medicamento en Alemania, la UE o Estados Unidos, donde se vende exclusivamente como producto químico de investigación.","rechtsstatus_en":"Semax está aprobado como medicamento para la neuroprotección en Rusia, pero no está aprobado como medicamento en Alemania, la UE o Estados Unidos, donde se vende exclusivamente como producto químico de investigación.","typischeMg":[10,30],"faq":[{"q":"¿Actúa semax como un nootrópico clásico?","a":"La investigación vincula principalmente a semax a efectos neuroprotectores y relacionados con BDNF, menos a un efecto de enfoque agudo como los estimulantes clásicos.","q_en":"¿Actúa semax como un nootrópico clásico?","a_en":"La investigación vincula principalmente a semax a efectos neuroprotectores y relacionados con BDNF, menos a un efecto de enfoque agudo como los estimulantes clásicos."},{"q":"¿Es semax lo mismo que selank?","a":"No, ambos son péptidos rusos relacionados con orígenes diferentes. Semax deriva de ACTH y está principalmente relacionado con la neuroprotección, selank de tuftsin y principalmente con la regulación de la ansiedad.","q_en":"¿Es semax lo mismo que selank?","a_en":"No, ambos son péptidos rusos relacionados con orígenes diferentes. Semax deriva de ACTH y está principalmente relacionado con la neuroprotección, selank de tuftsin y principalmente con la regulación de la ansiedad."},{"q":"¿Está semax legalmente disponible en Alemania?","a":"Semax no está aprobado como medicamento en Alemania o la UE y se ofrece exclusivamente como producto químico de investigación para fines de laboratorio, no para uso humano.","q_en":"¿Está semax legalmente disponible en Alemania?","a_en":"Semax no está aprobado como medicamento en Alemania o la UE y se ofrece exclusivamente como producto químico de investigación para fines de laboratorio, no para uso humano."}],"seo":{"title":"Semax: Péptido de Investigación ACTH para Neuroprotección","title_en":"Semax: Péptido de Investigación ACTH para Neuroprotección","description":"Semax de un vistazo: origen, mecanismo, estado del estudio y perfil de seguridad de un péptido de investigación estudiado para la neuroprotección y la cognición.","description_en":"Semax de un vistazo: origen, mecanismo, estado del estudio y perfil de seguridad de un péptido de investigación estudiado para la neuroprotección y la cognición."},"demo":false,"steckbrief":{"cas":"80714-61-0","molekulargewicht":"813.9 g/mol","aminosaeuren":7,"halbwertszeit":null,"reinheitsstandard":"≥ 98 % (HPLC, estándar comercial)","loeslichkeit":null,"sequenzLaenge":7,"quellen":["PubChem CID 9811102","chemverify Katalog 14.09.2026"],"reinheitsstandard_en":"≥ 98 % (HPLC, estándar comercial)"},"verwandt":["selank","epitalon","dsip"]},{"slug":"kpv","name":"KPV","synonyme":["Lys-Pro-Val","alpha-MSH(11-13)"],"kategorie":"Immunsystem","studienlage":"präklinisch","kurz":"Un fragmento de tres aminoácidos de alfa-MSH, estudiado en modelos animales por propiedades antiinflamatorias en el intestino y en la piel.","kurz_en":"Un fragmento de tres aminoácidos de alfa-MSH, estudiado en modelos animales por propiedades antiinflamatorias en el intestino y en la piel.","beschreibung":"KPV es un tripéptido hecho de los aminoácidos lisina, prolina y valina, derivado del extremo C-terminal de la hormona alfa-MSH. Está entre los péptidos más pequeños estudiados en investigación de inflamación, con un enfoque en modelos animales de enfermedad inflamatoria intestinal crónica e inflamación de la piel. Los estudios en humanos aún no están disponibles.","beschreibung_en":"KPV es un tripéptido hecho de los aminoácidos lisina, prolina y valina, derivado del extremo C-terminal de la hormona alfa-MSH. Está entre los péptidos más pequeños estudiados en investigación de inflamación, con un enfoque en modelos animales de enfermedad inflamatoria intestinal crónica e inflamación de la piel. Los estudios en humanos aún no están disponibles.","mechanismus":"En modelos preclínicos, se describe un efecto antiinflamatorio que opera independientemente del receptor de melanocortina y en su lugar se basa en la captación en las células intestinales a través del transportador peptídico PepT1. Allí, se describe la inhibición de la activación de NF-κB, un interruptor central en la respuesta inflamatoria. Los mecanismos exactos en humanos no han sido estudiados.","mechanismus_en":"En modelos preclínicos, se describe un efecto antiinflamatorio que opera independientemente del receptor de melanocortina y en su lugar se basa en la captación en las células intestinales a través del transportador peptídico PepT1. Allí, se describe la inhibición de la activación de NF-κB, un interruptor central en la respuesta inflamatoria. Los mecanismos exactos en humanos no han sido estudiados.","evidenz":[{"art":"preclínico","kurz":"Un estudio en dos modelos murinos de colitis describió una recuperación más rápida del peso corporal y una reducción marcada de los infiltrados inflamatorios en el tejido intestinal bajo KPV en comparación con animales no tratados.","kurz_en":"Un estudio en dos modelos murinos de colitis describió una recuperación más rápida del peso corporal y una reducción marcada de los infiltrados inflamatorios en el tejido intestinal bajo KPV en comparación con animales no tratados.","quelle":"Kannengiesser et al. 2008, Inflammatory Bowel Diseases, PMID 18092346"},{"art":"preclínico","kurz":"Un estudio mostró que el efecto antiinflamatorio de KPV en el modelo murino está mediado a través de la captación mediante el transportador peptídico PepT1 en lugar del receptor de melanocortina.","kurz_en":"Un estudio mostró que el efecto antiinflamatorio de KPV en el modelo murino está mediado a través de la captación mediante el transportador peptídico PepT1 en lugar del receptor de melanocortina.","quelle":"Dalmasso et al. 2008, Gastroenterology, PMID 18061177"},{"art":"preclínico","kurz":"Un estudio que utilizó nanopartículas funcionalizadas con ácido hialurónico para la liberación oral dirigida de KPV en el colon describió una reducción significativa de la inflamación en ratones con colitis en comparación con KPV no tratado.","kurz_en":"Un estudio que utilizó nanopartículas funcionalizadas con ácido hialurónico para la liberación oral dirigida de KPV en el colon describió una reducción significativa de la inflamación en ratones con colitis en comparación con KPV no tratado.","quelle":"Xiao et al. 2017, Molecular Therapy, PMID 28143741"}],"sicherheit":["Los estudios de seguridad en humanos de KPV aún no están disponibles, toda la evidencia proviene de modelos celulares y animales.","No se informaron efectos adversos graves en los estudios animales disponibles.","Las interacciones con otras sustancias no se han estudiado en humanos.","Los productos de fabricación no controlada conllevan un riesgo de contaminación que es independiente de la molécula misma."],"sicherheit_en":["Los estudios de seguridad en humanos de KPV aún no están disponibles, toda la evidencia proviene de modelos celulares y animales.","No se informaron efectos adversos graves en los estudios animales disponibles.","Las interacciones con otras sustancias no se han estudiado en humanos.","Los productos de fabricación no controlada conllevan un riesgo de contaminación que es independiente de la molécula misma."],"hinweise":["Solo con fines de investigación, no apto para uso en humanos","Un certificado de análisis no establece idoneidad médica"],"hinweise_en":["Solo con fines de investigación, no apto para uso en humanos","Un certificado de análisis no establece idoneidad médica"],"rekonstitution":"Las condiciones específicas de cada producto figuran en la documentación original del fabricante. Este portal no ofrece instrucciones de preparación ni de uso en humanos.","rekonstitution_en":"Las condiciones específicas de cada producto figuran en la documentación original del fabricante. Este portal no ofrece instrucciones de preparación ni de uso en humanos.","lagerung":"Las condiciones específicas de cada producto figuran en la documentación original del fabricante. Este portal no ofrece instrucciones de preparación ni de uso en humanos.","lagerung_en":"Las condiciones específicas de cada producto figuran en la documentación original del fabricante. Este portal no ofrece instrucciones de preparación ni de uso en humanos.","rechtsstatus":"KPV no está autorizado como medicamento en Alemania, la UE ni Estados Unidos y no está clasificado como producto alimenticio. Se vende exclusivamente como sustancia química para investigación.","rechtsstatus_en":"KPV no está autorizado como medicamento en Alemania, la UE ni Estados Unidos y no está clasificado como producto alimenticio. Se vende exclusivamente como sustancia química para investigación.","typischeMg":[],"faq":[{"q":"¿De dónde viene KPV?","a":"KPV es un fragmento de la hormona alfa-MSH, hecho de los tres aminoácidos lisina, prolina y valina.","q_en":"¿De dónde viene KPV?","a_en":"KPV es un fragmento de la hormona alfa-MSH, hecho de los tres aminoácidos lisina, prolina y valina."},{"q":"¿Actúa KPV a través del receptor de melanocortina?","a":"No. En modelos animales, se describe el efecto antiinflamatorio independientemente del receptor de melanocortina, en su lugar dependiendo del transportador PepT1.","q_en":"¿Actúa KPV a través del receptor de melanocortina?","a_en":"No. En modelos animales, se describe el efecto antiinflamatorio independientemente del receptor de melanocortina, en su lugar dependiendo del transportador PepT1."},{"q":"¿Existen estudios en humanos sobre KPV?","a":"No, hasta la fecha solo existen estudios celulares y animales, en su mayoría sobre enfermedad inflamatoria intestinal.","q_en":"¿Existen estudios en humanos sobre KPV?","a_en":"No, hasta la fecha solo existen estudios celulares y animales, en su mayoría sobre enfermedad inflamatoria intestinal."}],"seo":{"title":"KPV: perfil de investigación y evidencia","title_en":"KPV: perfil de investigación y evidencia","description":"Resumen de KPV: origen de alfa-MSH, mecanismo, evidencia preclínica y perfil de seguridad, presentado de forma fáctica para el contexto de la investigación.","description_en":"Resumen de KPV: origen de alfa-MSH, mecanismo, evidencia preclínica y perfil de seguridad, presentado de forma fáctica para el contexto de la investigación."},"demo":false,"steckbrief":{"cas":"67727-97-3","molekulargewicht":"342.43 g/mol","aminosaeuren":3,"halbwertszeit":null,"reinheitsstandard":null,"loeslichkeit":null,"sequenzLaenge":3,"quellen":["PubChem CID 125672","chemverify Katalog 14.09.2026"]},"verwandt":["ll-37","thymosin-alpha-1","bpc-157"]},{"slug":"ll-37","name":"LL-37","synonyme":["Catelicidina","hCAP18(134-170)","Catelicidina humana"],"kategorie":"Immunsystem","studienlage":"klinisch untersucht","kurz":"Un péptido antimicrobiano de ocurrencia natural hecho de 37 aminoácidos que protege la piel y las membranas mucosas, estudiado en ensayos clínicos para la curación de heridas.","kurz_en":"Un péptido antimicrobiano de ocurrencia natural hecho de 37 aminoácidos que protege la piel y las membranas mucosas, estudiado en ensayos clínicos para la curación de heridas.","beschreibung":"LL-37 es el único miembro conocido de la familia de péptidos catelicidina en humanos y es producido por células inmunitarias así como por células de la piel y mucosas en respuesta a una lesión o infección. Es generado por escisión de la proteína precursora hCAP18. La investigación clínica se ha centrado principalmente en la aplicación tópica para heridas difíciles de sanar, como úlceras venosas de la pierna y úlceras del pie diabético.","beschreibung_en":"LL-37 es el único miembro conocido de la familia de péptidos catelicidina en humanos y es producido por células inmunitarias así como por células de la piel y mucosas en respuesta a una lesión o infección. Es generado por escisión de la proteína precursora hCAP18. La investigación clínica se ha centrado principalmente en la aplicación tópica para heridas difíciles de sanar, como úlceras venosas de la pierna y úlceras del pie diabético.","mechanismus":"LL-37 se inserta en las membranas celulares bacterianas y altera su integridad, produciendo un efecto antimicrobiano directo contra una amplia gama de patógenos. Se describen efectos inmunomoduladores adicionales, incluida la reclutación de células inmunitarias al sitio de la herida y la promoción de la angiogénesis. La producción endógena puede mejorarse por ciertos estímulos como análogos de vitamina D.","mechanismus_en":"LL-37 se inserta en las membranas celulares bacterianas y altera su integridad, produciendo un efecto antimicrobiano directo contra una amplia gama de patógenos. Se describen efectos inmunomoduladores adicionales, incluida la reclutación de células inmunitarias al sitio de la herida y la promoción de la angiogénesis. La producción endógena puede mejorarse por ciertos estímulos como análogos de vitamina D.","evidenz":[{"art":"clínico","kurz":"Un ensayo aleatorizado controlado con placebo en humanos en 34 pacientes con úlceras venosas de la pierna difíciles de sanar describió una tasa de curación aproximadamente 3 a 6 veces más rápida bajo las dos concentraciones más bajas de LL-37 en comparación con el placebo.","kurz_en":"Un ensayo aleatorizado controlado con placebo en humanos en 34 pacientes con úlceras venosas de la pierna difíciles de sanar describió una tasa de curación aproximadamente 3 a 6 veces más rápida bajo las dos concentraciones más bajas de LL-37 en comparación con el placebo.","quelle":"Grönberg et al. 2014, Wound Repair and Regeneration, PMID 25041740"},{"art":"clínico","kurz":"Un ensayo aleatorizado doble ciego en pacientes con úlceras del pie diabético examinó una crema que contiene LL-37 y describió efectos sobre la colonización bacteriana, marcadores inflamatorios y tasa de curación en comparación con el placebo.","kurz_en":"Un ensayo aleatorizado doble ciego en pacientes con úlceras del pie diabético examinó una crema que contiene LL-37 y describió efectos sobre la colonización bacteriana, marcadores inflamatorios y tasa de curación en comparación con el placebo.","quelle":"Miranda et al. 2023, Archives of Dermatological Research, PMID 37480520"},{"art":"clínico","kurz":"Un estudio en la piel humana describió que la producción endógena de hCAP18/LL-37 aumenta después de una lesión y puede mejorarse aún más por la aplicación tópica del análogo de vitamina D calcipotriol.","kurz_en":"Un estudio en la piel humana describió que la producción endógena de hCAP18/LL-37 aumenta después de una lesión y puede mejorarse aún más por la aplicación tópica del análogo de vitamina D calcipotriol.","quelle":"Heilborn et al. 2010, Experimental Dermatology, PMID 19878298"}],"sicherheit":["En los ensayos aleatorizados disponibles, se describió que la aplicación tópica de LL-37 era segura y bien tolerada, sin eventos adversos graves.","Las poblaciones de estudio fueron cada una pequeñas, los ensayos controlados con placebo más grandes con más participantes aún están pendientes.","Las formas de aplicación sistémicas y la seguridad humana a largo plazo no se han estudiado con la misma extensión que el uso tópico.","Los productos de fabricación no controlada conllevan un riesgo de contaminación que es independiente de la molécula misma."],"sicherheit_en":["En los ensayos aleatorizados disponibles, se describió que la aplicación tópica de LL-37 era segura y bien tolerada, sin eventos adversos graves.","Las poblaciones de estudio fueron cada una pequeñas, los ensayos controlados con placebo más grandes con más participantes aún están pendientes.","Las formas de aplicación sistémicas y la seguridad humana a largo plazo no se han estudiado con la misma extensión que el uso tópico.","Los productos de fabricación no controlada conllevan un riesgo de contaminación que es independiente de la molécula misma."],"hinweise":["Solo con fines de investigación, no apto para uso en humanos","Un certificado de análisis no establece idoneidad médica"],"hinweise_en":["Solo con fines de investigación, no apto para uso en humanos","Un certificado de análisis no establece idoneidad médica"],"rekonstitution":"Las condiciones específicas de cada producto figuran en la documentación original del fabricante. Este portal no ofrece instrucciones de preparación ni de uso en humanos.","rekonstitution_en":"Las condiciones específicas de cada producto figuran en la documentación original del fabricante. Este portal no ofrece instrucciones de preparación ni de uso en humanos.","lagerung":"Las condiciones específicas de cada producto figuran en la documentación original del fabricante. Este portal no ofrece instrucciones de preparación ni de uso en humanos.","lagerung_en":"Las condiciones específicas de cada producto figuran en la documentación original del fabricante. Este portal no ofrece instrucciones de preparación ni de uso en humanos.","rechtsstatus":"LL-37 no está aprobado como medicamento en Alemania, la UE o los Estados Unidos, y no se clasifica como producto alimenticio. Se vende exclusivamente como un químico de investigación, las formulaciones investigacionales clínicas de LL-37 están vinculadas a programas de estudio individuales.","rechtsstatus_en":"LL-37 no está aprobado como medicamento en Alemania, la UE o los Estados Unidos, y no se clasifica como producto alimenticio. Se vende exclusivamente como un químico de investigación, las formulaciones investigacionales clínicas de LL-37 están vinculadas a programas de estudio individuales.","typischeMg":[],"faq":[{"q":"¿Es LL-37 un péptido humano de ocurrencia natural?","a":"Sí. Es el único péptido catelicidina humano conocido y es producido por células inmunitarias, de la piel y mucosas, especialmente durante una lesión o infección.","q_en":"¿Es LL-37 un péptido humano de ocurrencia natural?","a_en":"Sí. Es el único péptido catelicidina humano conocido y es producido por células inmunitarias, de la piel y mucosas, especialmente durante una lesión o infección."},{"q":"¿Hay estudios clínicos sobre LL-37?","a":"Sí, varios ensayos aleatorizados examinaron la aplicación tópica en heridas difíciles de cicatrizar como úlceras venosas de la pierna y úlceras del pie diabético, con resultados de seguridad mayormente positivos.","q_en":"¿Hay estudios clínicos sobre LL-37?","a_en":"Sí, varios ensayos aleatorizados examinaron la aplicación tópica en heridas difíciles de cicatrizar como úlceras venosas de la pierna y úlceras del pie diabético, con resultados de seguridad mayormente positivos."},{"q":"¿Actúa LL-37 solo como antimicrobiano?","a":"No, además de su efecto directo sobre las membranas bacterianas, también se describen efectos inmunomoduladores como el reclutamiento de células inmunitarias y la promoción de la formación de vasos sanguíneos.","q_en":"¿Actúa LL-37 solo como antimicrobiano?","a_en":"No, además de su efecto directo sobre las membranas bacterianas, también se describen efectos inmunomoduladores como el reclutamiento de células inmunitarias y la promoción de la formación de vasos sanguíneos."}],"seo":{"title":"LL-37: perfil de investigación y evidencia","title_en":"LL-37: perfil de investigación y evidencia","description":"Visión general de LL-37: catelicidina de origen natural, mecanismo, evidencia clínica sobre la cicatrización de heridas y perfil de seguridad en el contexto de la investigación.","description_en":"Visión general de LL-37: catelicidina de origen natural, mecanismo, evidencia clínica sobre la cicatrización de heridas y perfil de seguridad en el contexto de la investigación."},"demo":false,"steckbrief":{"cas":"154947-66-7","molekulargewicht":"4493 g/mol","aminosaeuren":37,"halbwertszeit":null,"reinheitsstandard":"≥ 95 % (HPLC, estándar comercial)","loeslichkeit":"soluble en agua y DMSO","sequenzLaenge":37,"quellen":["PubChem CID 16198951","chemverify Katalog 14.09.2026"],"reinheitsstandard_en":"≥ 95 % (HPLC, estándar comercial)","loeslichkeit_en":"soluble en agua y DMSO"},"verwandt":["kpv","thymosin-alpha-1","bpc-157"]},{"slug":"thymosin-alpha-1","name":"Timosina alfa 1","synonyme":["Tα1","Zadaxin (nombre comercial)"],"kategorie":"Immunsystem","studienlage":"zugelassenes Arzneimittel","kurz":"Un péptido inmune de origen natural derivado del timo, aprobado como medicamento en más de 35 países, aunque no actualmente en Alemania, Austria o Suiza.","kurz_en":"Un péptido inmune de origen natural derivado del timo, aprobado como medicamento en más de 35 países, aunque no actualmente en Alemania, Austria o Suiza.","beschreibung":"La timosina alfa 1 es un péptido de 28 aminoácidos aislado originalmente de la glándula tímica, el órgano central donde maduran las células T. Actúa como modulador inmune y se utiliza tanto en investigación clínica como, bajo el nombre comercial Zadaxin, como medicamento aprobado para ciertas afecciones inmunológicas. Las áreas de estudio incluyen infecciones virales crónicas, la respuesta inmunitaria a la vacunación y un papel de soporte en oncología.","beschreibung_en":"La timosina alfa 1 es un péptido de 28 aminoácidos aislado originalmente de la glándula tímica, el órgano central donde maduran las células T. Actúa como modulador inmune y se utiliza tanto en investigación clínica como, bajo el nombre comercial Zadaxin, como medicamento aprobado para ciertas afecciones inmunológicas. Las áreas de estudio incluyen infecciones virales crónicas, la respuesta inmunitaria a la vacunación y un papel de soporte en oncología.","mechanismus":"El efecto se describe principalmente a través de los receptores tipo Toll en las células inmunitarias, estructuras de reconocimiento molecular que responden a patógenos. Esto activa vías como NF-κB y la producción de interferón, involucrando tanto el sistema inmunitario innato como el adaptativo a la vez. Los efectos descritos incluyen aumento de la actividad de las células T y las células asesinas naturales, así como una mejor producción de anticuerpos.","mechanismus_en":"El efecto se describe principalmente a través de los receptores tipo Toll en las células inmunitarias, estructuras de reconocimiento molecular que responden a patógenos. Esto activa vías como NF-κB y la producción de interferón, involucrando tanto el sistema inmunitario innato como el adaptativo a la vez. Los efectos descritos incluyen aumento de la actividad de las células T y las células asesinas naturales, así como una mejor producción de anticuerpos.","evidenz":[{"art":"clínico","kurz":"Una revisión retrospectiva de 76 pacientes con COVID-19 grave en dos hospitales describió una menor mortalidad bajo timosina alfa 1 en comparación con el grupo no tratado, acompañada de una recuperación de los recuentos de células T.","kurz_en":"Una revisión retrospectiva de 76 pacientes con COVID-19 grave en dos hospitales describió una menor mortalidad bajo timosina alfa 1 en comparación con el grupo no tratado, acompañada de una recuperación de los recuentos de células T.","quelle":"Liu et al. 2020, Clinical Infectious Diseases"},{"art":"clínico","kurz":"Un ensayo aleatorizado en 42 pacientes con cáncer de pulmón de células no pequeñas después de la radiación describió una normalización más rápida de la función de las células T bajo timosina alfa 1 frente al placebo, junto con un beneficio de supervivencia, más pronunciado en pacientes con tumores más pequeños.","kurz_en":"Un ensayo aleatorizado en 42 pacientes con cáncer de pulmón de células no pequeñas después de la radiación describió una normalización más rápida de la función de las células T bajo timosina alfa 1 frente al placebo, junto con un beneficio de supervivencia, más pronunciado en pacientes con tumores más pequeños.","quelle":"Schulof et al. 1985, Journal of Biological Response Modifiers, PMID 3998766"}],"sicherheit":["Grandes bases de datos de seguridad que cubren miles de pacientes describen principalmente reacciones leves y transitorias en el sitio de inyección y fatiga leve.","Los informes raros incluyen reacciones de piel alérgicas y un brote temporal de condiciones autoinmunes preexistentes.","El uso concurrente de medicación inmunosupresora se enumera como contraindicación en la información del producto, ya que los efectos actúan en direcciones opuestas.","La información del producto aconseja precaución para el trasplante de órganos activo y la enfermedad autoinmune activa."],"sicherheit_en":["Grandes bases de datos de seguridad que cubren miles de pacientes describen principalmente reacciones leves y transitorias en el sitio de inyección y fatiga leve.","Los informes raros incluyen reacciones de piel alérgicas y un brote temporal de condiciones autoinmunes preexistentes.","El uso concurrente de medicación inmunosupresora se enumera como contraindicación en la información del producto, ya que los efectos actúan en direcciones opuestas.","La información del producto aconseja precaución para el trasplante de órganos activo y la enfermedad autoinmune activa."],"hinweise":["Solo con fines de investigación, no apto para uso en humanos","Un certificado de análisis no establece idoneidad médica"],"hinweise_en":["Solo con fines de investigación, no apto para uso en humanos","Un certificado de análisis no establece idoneidad médica"],"rekonstitution":"Las condiciones específicas de cada producto figuran en la documentación original del fabricante. Este portal no ofrece instrucciones de preparación ni de uso en humanos.","rekonstitution_en":"Las condiciones específicas de cada producto figuran en la documentación original del fabricante. Este portal no ofrece instrucciones de preparación ni de uso en humanos.","lagerung":"Las condiciones específicas de cada producto figuran en la documentación original del fabricante. Este portal no ofrece instrucciones de preparación ni de uso en humanos.","lagerung_en":"Las condiciones específicas de cada producto figuran en la documentación original del fabricante. Este portal no ofrece instrucciones de preparación ni de uso en humanos.","rechtsstatus":"Bajo el nombre comercial Zadaxin, la timosina alfa 1 está aprobada como medicamento para el tratamiento de ciertas afecciones inmunológicas, incluyendo hepatitis B y C, en más de 35 países. Actualmente no está aprobada en Alemania, Austria o Suiza, donde el abastecimiento se encuentra en una zona gris legal.","rechtsstatus_en":"Bajo el nombre comercial Zadaxin, la timosina alfa 1 está aprobada como medicamento para el tratamiento de ciertas afecciones inmunológicas, incluyendo hepatitis B y C, en más de 35 países. Actualmente no está aprobada en Alemania, Austria o Suiza, donde el abastecimiento se encuentra en una zona gris legal.","typischeMg":[],"faq":[{"q":"¿Es la timosina alfa 1 un medicamento aprobado?","a":"Sí, bajo el nombre comercial Zadaxin en más de 35 países, incluyendo para hepatitis B y C crónicas. Actualmente no hay aprobación en Alemania, Austria o Suiza.","q_en":"¿Es la timosina alfa 1 un medicamento aprobado?","a_en":"Sí, bajo el nombre comercial Zadaxin en más de 35 países, incluyendo para hepatitis B y C crónicas. Actualmente no hay aprobación en Alemania, Austria o Suiza."},{"q":"¿En qué actúa la timosina alfa 1 en el sistema inmunológico?","a":"Actúa tanto en el sistema inmunológico innato como en el adaptativo a la vez, incluyendo a través de la actividad aumentada de células T y células asesinas naturales, y la mejora de la formación de anticuerpos.","q_en":"¿En qué actúa la timosina alfa 1 en el sistema inmunológico?","a_en":"Actúa tanto en el sistema inmunológico innato como en el adaptativo a la vez, incluyendo a través de la actividad aumentada de células T y células asesinas naturales, y la mejora de la formación de anticuerpos."},{"q":"¿Existen estudios en humanos sobre la timosina alfa 1?","a":"Sí, en comparación con muchos otros péptidos existe una base más amplia de estudios clínicos, incluyendo trabajo sobre infecciones virales graves, un papel de apoyo en el cuidado del cáncer y la respuesta a la vacuna.","q_en":"¿Existen estudios en humanos sobre la timosina alfa 1?","a_en":"Sí, en comparación con muchos otros péptidos existe una base más amplia de estudios clínicos, incluyendo trabajo sobre infecciones virales graves, un papel de apoyo en el cuidado del cáncer y la respuesta a la vacuna."}],"seo":{"title":"Timosina alfa 1: perfil de investigación y evidencia","title_en":"Timosina alfa 1: perfil de investigación y evidencia","description":"Resumen de la timosina alfa 1: modulación inmunológica, estado de aprobación internacional, evidencia clínica y perfil de seguridad.","description_en":"Resumen de la timosina alfa 1: modulación inmunológica, estado de aprobación internacional, evidencia clínica y perfil de seguridad."},"demo":false,"steckbrief":{"cas":"62304-98-7","molekulargewicht":"3108.3 g/mol","aminosaeuren":28,"halbwertszeit":null,"reinheitsstandard":"≥ 98 % (HPLC, estándar comercial)","loeslichkeit":null,"sequenzLaenge":28,"quellen":["PubChem CID 16130571","chemverify Katalog 14.09.2026"],"reinheitsstandard_en":"≥ 98 % (HPLC, estándar comercial)"},"verwandt":["bpc-157","tb-500","kpv","ll-37"]},{"slug":"epitalon","name":"Epitalon","synonyme":["Epithalon","Tetrapeptido AEDG"],"kategorie":"Sonstige","studienlage":"präklinisch","kurz":"Un tetrapeptido sintético, estudiado en investigación del envejecimiento como sustancia de investigación relacionada con el envejecimiento celular.","kurz_en":"Un tetrapeptido sintético, estudiado en investigación del envejecimiento como sustancia de investigación relacionada con el envejecimiento celular.","beschreibung":"Epitalon es un tetrapeptido sintético desarrollado por Vladimir Khavinson en el Instituto de Bioregulación y Gerontología de San Petersburgo. Se estudia en investigación preclínica en relación con el envejecimiento celular y la regulación de la actividad de la telomerasa. Los datos clínicos sólidos en humanos aún están pendientes.","beschreibung_en":"Epitalon es un tetrapeptido sintético desarrollado por Vladimir Khavinson en el Instituto de Bioregulación y Gerontología de San Petersburgo. Se estudia en investigación preclínica en relación con el envejecimiento celular y la regulación de la actividad de la telomerasa. Los datos clínicos sólidos en humanos aún están pendientes.","mechanismus":"Se ha descrito que Epitalon aumenta la actividad de la telomerasa en cultivos de células, lo que se asoció con la elongación de los telómeros in vitro. También se han descrito efectos sobre la síntesis de melatonina y sobre las moléculas de señalización del sistema inmunológico.","mechanismus_en":"Se ha descrito que Epitalon aumenta la actividad de la telomerasa en cultivos de células, lo que se asoció con la elongación de los telómeros in vitro. También se han descrito efectos sobre la síntesis de melatonina y sobre las moléculas de señalización del sistema inmunológico.","evidenz":[{"art":"preclínico","kurz":"En cultivos de fibroblastos fetales humanos, epitalon indujo la expresión de la subunidad catalítica de la telomerasa y actividad medible de la telomerasa, asociada con la elongación de los telómeros.","kurz_en":"En cultivos de fibroblastos fetales humanos, epitalon indujo la expresión de la subunidad catalítica de la telomerasa y actividad medible de la telomerasa, asociada con la elongación de los telómeros.","quelle":"Khavinson VKh, Bondarev IE, Butyugov AA 2003, Bulletin of Experimental Biology and Medicine 135:590-592"},{"art":"preclínico","kurz":"En modelos animales, se han descrito los efectos de epitalon en la liberación de melatonina y en los parámetros del sistema inmunológico, con resultados mixtos sobre la esperanza de vida dependiendo del modelo y el protocolo utilizado.","kurz_en":"En modelos animales, se han descrito los efectos de epitalon en la liberación de melatonina y en los parámetros del sistema inmunológico, con resultados mixtos sobre la esperanza de vida dependiendo del modelo y el protocolo utilizado.","quelle":"Khavinson VKh, Morozov VG 2003, Neuroendocrinology Letters"}],"sicherheit":["La investigación preclínica no ha descrito hasta ahora efectos tóxicos graves.","No hay estudios de seguridad humana controlados que cumplan con los estándares de ensayos occidentales.","No existen datos sólidos sobre el uso a largo plazo."],"sicherheit_en":["La investigación preclínica no ha descrito hasta ahora efectos tóxicos graves.","No hay estudios de seguridad humana controlados que cumplan con los estándares de ensayos occidentales.","No existen datos sólidos sobre el uso a largo plazo."],"hinweise":["Solo con fines de investigación, no apto para uso en humanos","Un certificado de análisis no establece idoneidad médica"],"hinweise_en":["Solo con fines de investigación, no apto para uso en humanos","Un certificado de análisis no establece idoneidad médica"],"rekonstitution":"Las condiciones específicas de cada producto figuran en la documentación original del fabricante. Este portal no ofrece instrucciones de preparación ni de uso en humanos.","rekonstitution_en":"Las condiciones específicas de cada producto figuran en la documentación original del fabricante. Este portal no ofrece instrucciones de preparación ni de uso en humanos.","lagerung":"Las condiciones específicas de cada producto figuran en la documentación original del fabricante. Este portal no ofrece instrucciones de preparación ni de uso en humanos.","lagerung_en":"Las condiciones específicas de cada producto figuran en la documentación original del fabricante. Este portal no ofrece instrucciones de preparación ni de uso en humanos.","rechtsstatus":"Epitalon no está aprobado como medicamento en Alemania, la UE o los Estados Unidos, y se vende exclusivamente como producto químico de investigación para fines de laboratorio.","rechtsstatus_en":"Epitalon no está aprobado como medicamento en Alemania, la UE o los Estados Unidos, y se vende exclusivamente como producto químico de investigación para fines de laboratorio.","typischeMg":[10,20],"faq":[{"q":"¿Se ha estudiado epitalon en humanos?","a":"Los datos disponibles provienen predominantemente de cultivos celulares y modelos animales. Los estudios clínicos controlados en humanos que cumplan con los estándares occidentales aún no están disponibles.","q_en":"¿Se ha estudiado epitalon en humanos?","a_en":"Los datos disponibles provienen predominantemente de cultivos celulares y modelos animales. Los estudios clínicos controlados en humanos que cumplan con los estándares occidentales aún no están disponibles."},{"q":"¿Qué tiene que ver epitalon con los telómeros?","a":"Los estudios de cultivo celular observaron un aumento en la actividad de la telomerasa y la elongación de los telómeros. Si esto se traduce en el organismo completo sigue abierto.","q_en":"¿Qué tiene que ver epitalon con los telómeros?","a_en":"Los estudios de cultivo celular observaron un aumento en la actividad de la telomerasa y la elongación de los telómeros. Si esto se traduce en el organismo completo sigue abierto."},{"q":"¿Está epitalon legalmente disponible en Alemania?","a":"Epitalon no está aprobado como medicamento y se ofrece exclusivamente como producto químico de investigación, no para uso humano.","q_en":"¿Está epitalon legalmente disponible en Alemania?","a_en":"Epitalon no está aprobado como medicamento y se ofrece exclusivamente como producto químico de investigación, no para uso humano."}],"seo":{"title":"Epitalon: Tetrapeptido en Investigación del Envejecimiento","title_en":"Epitalon: Tetrapeptido en Investigación del Envejecimiento","description":"Epitalon de un vistazo: mecanismo, estado del estudio preclínico y perfil de seguridad del péptido de telomerasa de investigación de Khavinson.","description_en":"Epitalon de un vistazo: mecanismo, estado del estudio preclínico y perfil de seguridad del péptido de telomerasa de investigación de Khavinson."},"demo":false,"steckbrief":{"cas":"307297-39-8","molekulargewicht":"390.35 g/mol","aminosaeuren":4,"halbwertszeit":null,"reinheitsstandard":"≥ 98 % (HPLC, estándar comercial)","loeslichkeit":null,"sequenzLaenge":4,"quellen":["PubChem CID 219042","chemverify Katalog 14.09.2026"],"reinheitsstandard_en":"≥ 98 % (HPLC, estándar comercial)"},"verwandt":["melanotan-2","selank","semax","dsip"]},{"slug":"kisspeptin","name":"Kisspeptina-10","synonyme":["Metastin (45-54)","KP-10"],"kategorie":"Sonstige","studienlage":"klinisch untersucht","kurz":"El fragmento bioactivo más corto del propio sistema de kisspeptina del cuerpo, estudiado en investigación endocrina sobre el control del eje hipotálamo pituitario gonadal.","kurz_en":"El fragmento bioactivo más corto del propio sistema de kisspeptina del cuerpo, estudiado en investigación endocrina sobre el control del eje hipotálamo pituitario gonadal.","beschreibung":"La Kisspeptina-10 es el fragmento más corto del propio péptido kisspeptina (metastina) del cuerpo que retiene actividad completa en el receptor KISS1R. En investigación se utiliza para desencadenar la liberación de GnRH directamente y para estudiar el eje hipotálamo pituitario gonadal en cuestiones de desarrollo puberal, hipogonadismo y fertilidad. Los ensayos clínicos más grandes sobre objetivos como la maduración de oocitos o la excitación sexual utilizaron en su mayoría la isoforma natural más larga, kisspeptina-54, que actúa sobre el mismo receptor.","beschreibung_en":"La Kisspeptina-10 es el fragmento más corto del propio péptido kisspeptina (metastina) del cuerpo que retiene actividad completa en el receptor KISS1R. En investigación se utiliza para desencadenar la liberación de GnRH directamente y para estudiar el eje hipotálamo pituitario gonadal en cuestiones de desarrollo puberal, hipogonadismo y fertilidad. Los ensayos clínicos más grandes sobre objetivos como la maduración de oocitos o la excitación sexual utilizaron en su mayoría la isoforma natural más larga, kisspeptina-54, que actúa sobre el mismo receptor.","mechanismus":"La Kisspeptina-10 se une al receptor acoplado a proteína G KISS1R (GPR54) en las neuronas de GnRH en el hipotálamo. A través de una cascada de señalización mediada por Gq/11 que involucra la entrada de calcio, despolariza estas neuronas y desencadena la liberación pulsátil de GnRH, que, a su vez, controla la secreción de LH y FSH desde la glándula pituitaria. En hombres, un bolo de kisspeptina-10 elevó los niveles de LH y la frecuencia de pulso, con un efecto más fuerte en cantidades administradas más altas. Por el contrario, la estimulación sostenida o de alta frecuencia del receptor puede desensibilizar el KISS1R y atenuar la respuesta de LH.","mechanismus_en":"La Kisspeptina-10 se une al receptor acoplado a proteína G KISS1R (GPR54) en las neuronas de GnRH en el hipotálamo. A través de una cascada de señalización mediada por Gq/11 que involucra la entrada de calcio, despolariza estas neuronas y desencadena la liberación pulsátil de GnRH, que, a su vez, controla la secreción de LH y FSH desde la glándula pituitaria. En hombres, un bolo de kisspeptina-10 elevó los niveles de LH y la frecuencia de pulso, con un efecto más fuerte en cantidades administradas más altas. Por el contrario, la estimulación sostenida o de alta frecuencia del receptor puede desensibilizar el KISS1R y atenuar la respuesta de LH.","evidenz":[{"art":"clínico","kurz":"En un estudio en hombres sanos, un bolo intravenoso de kisspeptina-10 elevó los niveles de LH con un efecto creciente en cantidades más altas, y una infusión continua de baja concentración además aumentó la frecuencia de pulsos de LH.","kurz_en":"En un estudio en hombres sanos, un bolo intravenoso de kisspeptina-10 elevó los niveles de LH con un efecto creciente en cantidades más altas, y una infusión continua de baja concentración además aumentó la frecuencia de pulsos de LH.","quelle":"George JT et al. 2011, The Journal of Clinical Endocrinology & Metabolism, PMID 21632807"},{"art":"clínico","kurz":"En un ensayo aleatorizado en 60 mujeres con alto riesgo de OHSS, una inyección única del isoforma relacionado kisspeptina-54 desencadenó la maduración de oocitos en el 95 por ciento de los casos durante un ciclo de FIV, sin observar OHSS moderada a grave.","kurz_en":"En un ensayo aleatorizado en 60 mujeres con alto riesgo de OHSS, una inyección única del isoforma relacionado kisspeptina-54 desencadenó la maduración de oocitos en el 95 por ciento de los casos durante un ciclo de FIV, sin observar OHSS moderada a grave.","quelle":"Jayasena CN et al. 2015, The Journal of Clinical Endocrinology & Metabolism, PMID 26192876"},{"art":"clínico","kurz":"En un ensayo aleatorizado controlado con placebo en 32 hombres con trastorno de deseo sexual hipoactivo, una infusión única del isoforma kisspeptina-54 aumentó la actividad cerebral sexual y la tumescencia del pene durante la visualización de videos eróticos en comparación con el placebo.","kurz_en":"En un ensayo aleatorizado controlado con placebo en 32 hombres con trastorno de deseo sexual hipoactivo, una infusión única del isoforma kisspeptina-54 aumentó la actividad cerebral sexual y la tumescencia del pene durante la visualización de videos eróticos en comparación con el placebo.","quelle":"Mills EG et al. 2023, JAMA Network Open, PMID 36735255"}],"sicherheit":["En estudios publicados con más de 1.000 participantes combinados, no se han reportado eventos adversos graves atribuibles a la sustancia hasta la fecha, con un perfil de eventos adversos comparable al placebo.","Los efectos descritos con mayor frecuencia fueron reacciones leves y transitorias como reacciones en el sitio de la inyección, rubor y dolor de cabeza leve.","La estimulación sostenida o de alta frecuencia del receptor KISS1R puede provocar desensibilización del receptor y una respuesta de LH atenuada (taquifilaxis).","Los datos de seguridad a largo plazo robustos aún no están disponibles, ya que los estudios disponibles cubren principalmente la administración controlada a corto plazo."],"sicherheit_en":["En estudios publicados con más de 1.000 participantes combinados, no se han reportado eventos adversos graves atribuibles a la sustancia hasta la fecha, con un perfil de eventos adversos comparable al placebo.","Los efectos descritos con mayor frecuencia fueron reacciones leves y transitorias como reacciones en el sitio de la inyección, rubor y dolor de cabeza leve.","La estimulación sostenida o de alta frecuencia del receptor KISS1R puede provocar desensibilización del receptor y una respuesta de LH atenuada (taquifilaxis).","Los datos de seguridad a largo plazo robustos aún no están disponibles, ya que los estudios disponibles cubren principalmente la administración controlada a corto plazo."],"hinweise":["Solo con fines de investigación, no apto para uso en humanos","Un certificado de análisis no establece idoneidad médica"],"hinweise_en":["Solo con fines de investigación, no apto para uso en humanos","Un certificado de análisis no establece idoneidad médica"],"rekonstitution":"Las condiciones específicas de cada producto figuran en la documentación original del fabricante. Este portal no ofrece instrucciones de preparación ni de uso en humanos.","rekonstitution_en":"Las condiciones específicas de cada producto figuran en la documentación original del fabricante. Este portal no ofrece instrucciones de preparación ni de uso en humanos.","lagerung":"Las condiciones específicas de cada producto figuran en la documentación original del fabricante. Este portal no ofrece instrucciones de preparación ni de uso en humanos.","lagerung_en":"Las condiciones específicas de cada producto figuran en la documentación original del fabricante. Este portal no ofrece instrucciones de preparación ni de uso en humanos.","rechtsstatus":"La kisspeptina-10 no está aprobada como medicamento en Alemania, la UE o los Estados Unidos. Se vende exclusivamente como un químico de investigación para fines de laboratorio; las aplicaciones clínicas como un disparador de FIV o el uso en trastorno de deseo sexual hipoactivo siguen bajo investigación experimental.","rechtsstatus_en":"La kisspeptina-10 no está aprobada como medicamento en Alemania, la UE o los Estados Unidos. Se vende exclusivamente como un químico de investigación para fines de laboratorio; las aplicaciones clínicas como un disparador de FIV o el uso en trastorno de deseo sexual hipoactivo siguen bajo investigación experimental.","typischeMg":[5,10],"faq":[{"q":"¿Es la kisspeptina-10 lo mismo que la kisspeptina probada en ensayos clínicos?","a":"No exactamente. La mayoría de los ensayos clínicos importantes sobre fertilidad o excitación sexual utilizaron la isoforma natural más larga kisspeptina-54. La kisspeptina-10 es el fragmento más corto con actividad completa del receptor y se ha estudiado principalmente en investigación mecanicista sobre la liberación de LH en hombres.","q_en":"¿Es la kisspeptina-10 lo mismo que la kisspeptina probada en ensayos clínicos?","a_en":"No exactamente. La mayoría de los ensayos clínicos importantes sobre fertilidad o excitación sexual utilizaron la isoforma natural más larga kisspeptina-54. La kisspeptina-10 es el fragmento más corto con actividad completa del receptor y se ha estudiado principalmente en investigación mecanicista sobre la liberación de LH en hombres."},{"q":"¿Cómo actúa la kisspeptina-10 en el cuerpo?","a":"Se une al receptor KISS1R en las neuronas de GnRH en el hipotálamo y desencadena la liberación pulsátil de GnRH. Esto, a su vez, controla la secreción de LH y FSH de la glándula pituitaria y, con ello, las funciones centrales del eje reproductivo.","q_en":"¿Cómo actúa la kisspeptina-10 en el cuerpo?","a_en":"Se une al receptor KISS1R en las neuronas de GnRH en el hipotálamo y desencadena la liberación pulsátil de GnRH. Esto, a su vez, controla la secreción de LH y FSH de la glándula pituitaria y, con ello, las funciones centrales del eje reproductivo."},{"q":"¿Está la kisspeptina-10 legalmente disponible en Alemania?","a":"La kisspeptina-10 no está aprobada como medicamento en Alemania, la UE o los Estados Unidos. Se ofrece exclusivamente como un químico de investigación para fines de laboratorio, no para uso humano.","q_en":"¿Está la kisspeptina-10 legalmente disponible en Alemania?","a_en":"La kisspeptina-10 no está aprobada como medicamento en Alemania, la UE o los Estados Unidos. Se ofrece exclusivamente como un químico de investigación para fines de laboratorio, no para uso humano."}],"seo":{"title":"Kisspeptina-10: Péptido de Investigación para el Eje Hormonal","title_en":"Kisspeptina-10: Péptido de Investigación para el Eje Hormonal","description":"Kisspeptina-10 explicada de forma fáctica: mecanismo en el receptor KISS1R, datos de estudio sobre GnRH y el eje hormonal, y el perfil de seguridad de un péptido de investigación.","description_en":"Kisspeptina-10 explicada de forma fáctica: mecanismo en el receptor KISS1R, datos de estudio sobre GnRH y el eje hormonal, y el perfil de seguridad de un péptido de investigación."},"demo":false,"steckbrief":{"cas":"374675-21-5","molekulargewicht":"1302.4 g/mol","aminosaeuren":10,"halbwertszeit":null,"reinheitsstandard":"≥ 98 % (HPLC, estándar comercial)","loeslichkeit":"soluble en agua y buffers acuosos","sequenzLaenge":10,"quellen":["PubChem CID 25240297","chemverify Katalog 14.09.2026"],"reinheitsstandard_en":"≥ 98 % (HPLC, estándar comercial)","loeslichkeit_en":"soluble en agua y buffers acuosos"},"verwandt":["pt-141","oxytocin"]},{"slug":"melanotan-2","name":"Melanotan II","synonyme":["MT-2","MT2"],"kategorie":"Sonstige","studienlage":"frühe klinische Studien","kurz":"Un análogo sintético de la propia hormona alpha-MSH del cuerpo, estudiado en ensayos clínicos tempranos sobre pigmentación y función sexual.","kurz_en":"Un análogo sintético de la propia hormona alpha-MSH del cuerpo, estudiado en ensayos clínicos tempranos sobre pigmentación y función sexual.","beschreibung":"Melanotan II es un péptido cíclico sintético de siete aminoácidos que se une a varios receptores melanocortina en el cuerpo. Fue desarrollado en la década de 1980 en la Universidad de Arizona y es considerablemente más potente que su contraparte natural, alpha-MSH. Las áreas de estudio incluyen un papel en la pigmentación de la piel así como en el deseo y la excitación sexual.","beschreibung_en":"Melanotan II es un péptido cíclico sintético de siete aminoácidos que se une a varios receptores melanocortina en el cuerpo. Fue desarrollado en la década de 1980 en la Universidad de Arizona y es considerablemente más potente que su contraparte natural, alpha-MSH. Las áreas de estudio incluyen un papel en la pigmentación de la piel así como en el deseo y la excitación sexual.","mechanismus":"A través del receptor MC1R en las células pigmentarias de la piel, el melanotan II desencadena la producción de eumelanina que ocurre independientemente de la exposición a los rayos UV. A través del receptor MC4R en el sistema nervioso central, se describe un efecto en el deseo y la excitación sexual, junto con un efecto regulador del apetito. Debido a que el melanotan II activa varios receptores de forma no selectiva a la vez, la interacción de estos efectos es más compleja que con los compuestos relacionados más selectivos.","mechanismus_en":"A través del receptor MC1R en las células pigmentarias de la piel, el melanotan II desencadena la producción de eumelanina que ocurre independientemente de la exposición a los rayos UV. A través del receptor MC4R en el sistema nervioso central, se describe un efecto en el deseo y la excitación sexual, junto con un efecto regulador del apetito. Debido a que el melanotan II activa varios receptores de forma no selectiva a la vez, la interacción de estos efectos es más compleja que con los compuestos relacionados más selectivos.","evidenz":[{"art":"clínico","kurz":"Un estudio piloto de fase 1 en tres voluntarios masculinos describió pigmentación cutánea marcada sin exposición a rayos UV después de inyecciones subcutáneas repetidas, acompañada de náuseas, rubor y erecciones espontáneas como los efectos adversos más comunes.","kurz_en":"Un estudio piloto de fase 1 en tres voluntarios masculinos describió pigmentación cutánea marcada sin exposición a rayos UV después de inyecciones subcutáneas repetidas, acompañada de náuseas, rubor y erecciones espontáneas como los efectos adversos más comunes.","quelle":"Dorr et al. 1996, Life Sciences, PMID 8637402"},{"art":"clínico","kurz":"Un estudio cruzado doble ciego controlado con placebo en hombres con disfunción eréctil psicogénica describió una erección en 8 de 10 participantes después de la inyección de melanotan II, con rigidez significativamente más larga que bajo placebo.","kurz_en":"Un estudio cruzado doble ciego controlado con placebo en hombres con disfunción eréctil psicogénica describió una erección en 8 de 10 participantes después de la inyección de melanotan II, con rigidez significativamente más larga que bajo placebo.","quelle":"Hadley et al. 1998, PMID 9679884"}],"sicherheit":["Los efectos agudos comúnmente reportados son náuseas y rubor facial, atribuidos a la liberación de histamina.","Se han observado aumentos leves en la presión arterial y el pulso.","Se ha documentado una emergencia médica que involucra una erección que dura varias horas como un efecto secundario raro pero grave.","Los informes de casos describen lunares nuevos o más oscuros, sobre todo en relación con una exposición simultánea a los rayos UV. No se ha establecido un vínculo causal con el cáncer de piel."],"sicherheit_en":["Los efectos agudos comúnmente reportados son náuseas y rubor facial, atribuidos a la liberación de histamina.","Se han observado aumentos leves en la presión arterial y el pulso.","Se ha documentado una emergencia médica que involucra una erección que dura varias horas como un efecto secundario raro pero grave.","Los informes de casos describen lunares nuevos o más oscuros, sobre todo en relación con una exposición simultánea a los rayos UV. No se ha establecido un vínculo causal con el cáncer de piel."],"hinweise":["Solo con fines de investigación, no apto para uso en humanos","Un certificado de análisis no establece idoneidad médica"],"hinweise_en":["Solo con fines de investigación, no apto para uso en humanos","Un certificado de análisis no establece idoneidad médica"],"rekonstitution":"Las condiciones específicas de cada producto figuran en la documentación original del fabricante. Este portal no ofrece instrucciones de preparación ni de uso en humanos.","rekonstitution_en":"Las condiciones específicas de cada producto figuran en la documentación original del fabricante. Este portal no ofrece instrucciones de preparación ni de uso en humanos.","lagerung":"Las condiciones específicas de cada producto figuran en la documentación original del fabricante. Este portal no ofrece instrucciones de preparación ni de uso en humanos.","lagerung_en":"Las condiciones específicas de cada producto figuran en la documentación original del fabricante. Este portal no ofrece instrucciones de preparación ni de uso en humanos.","rechtsstatus":"Melanotan II no está aprobado como medicamento en Alemania, la UE o los Estados Unidos, y se vende exclusivamente como un químico de investigación. Tres fármacos melanocortínicos estructuralmente relacionados (afamelanotide, bremelanotida, setmelanotide) están aprobadas para indicaciones específicas y separadas en los Estados Unidos y en partes de la UE; el melanotan II en sí mismo no está entre ellas.","rechtsstatus_en":"Melanotan II no está aprobado como medicamento en Alemania, la UE o los Estados Unidos, y se vende exclusivamente como un químico de investigación. Tres fármacos melanocortínicos estructuralmente relacionados (afamelanotide, bremelanotida, setmelanotide) están aprobadas para indicaciones específicas y separadas en los Estados Unidos y en partes de la UE; el melanotan II en sí mismo no está entre ellas.","typischeMg":[],"faq":[{"q":"¿Está aprobado el melanotan II?","a":"No, el melanotan II en sí mismo no está aprobado en la UE o en los Estados Unidos. Se vende solo como un químico de investigación, mientras que tres compuestos relacionados están aprobados para otras indicaciones.","q_en":"¿Está aprobado el melanotan II?","a_en":"No, el melanotan II en sí mismo no está aprobado en la UE o en los Estados Unidos. Se vende solo como un químico de investigación, mientras que tres compuestos relacionados están aprobados para otras indicaciones."},{"q":"¿El melanotan II solo funciona con luz solar?","a":"No. Según estudios, la formación de pigmento ocurre independientemente de la exposición a la luz UV. La luz UV puede aumentar aún más el efecto pero no es necesaria para ello.","q_en":"¿El melanotan II solo funciona con luz solar?","a_en":"No. Según estudios, la formación de pigmento ocurre independientemente de la exposición a la luz UV. La luz UV puede aumentar aún más el efecto pero no es necesaria para ello."},{"q":"¿Qué efectos secundarios han descrito los estudios?","a":"Lo más frecuente son náuseas y rubor facial. Con menor frecuencia se han descrito aumentos de la presión arterial, una erección prolongada como urgencia médica y cambios en los lunares.","q_en":"¿Qué efectos secundarios han descrito los estudios?","a_en":"Lo más frecuente son náuseas y rubor facial. Con menor frecuencia se han descrito aumentos de la presión arterial, una erección prolongada como urgencia médica y cambios en los lunares."}],"seo":{"title":"Melanotan II: perfil de investigación y evidencia","title_en":"Melanotan II: perfil de investigación y evidencia","description":"Resumen del melanotan II: mecanismo, evidencia clínica sobre pigmentación y función sexual, y perfil de seguridad.","description_en":"Resumen del melanotan II: mecanismo, evidencia clínica sobre pigmentación y función sexual, y perfil de seguridad."},"demo":false,"steckbrief":{"cas":"121062-08-6","molekulargewicht":"1024.2 g/mol","aminosaeuren":7,"halbwertszeit":null,"reinheitsstandard":"≥ 99 % (HPLC, estándar comercial)","loeslichkeit":null,"sequenzLaenge":7,"quellen":["PubChem CID 92432","chemverify Katalog 14.09.2026"],"reinheitsstandard_en":"≥ 99 % (HPLC, estándar comercial)"},"verwandt":["ghk-cu","epitalon","pt-141","kpv"]},{"slug":"oxytocin","name":"Oxitocina","synonyme":["OXT","Pitocin"],"kategorie":"Sonstige","studienlage":"zugelassenes Arzneimittel","kurz":"Una hormona nonapeptídica endógena, aprobada como medicamento para inducir el parto y también estudiada en investigación sobre comportamiento social y vínculo.","kurz_en":"Una hormona nonapeptídica endógena, aprobada como medicamento para inducir el parto y también estudiada en investigación sobre comportamiento social y vínculo.","beschreibung":"La oxitocina es una hormona de nueve aminoácidos producida en el hipotálamo y liberada a través de la glándula pituitaria. Como medicamento, como Syntocinon o Pitocin, está aprobada para inducir el parto y controlar la hemorragia posparto. La oxitocina administrada intranasalmente por separado se estudia en investigación básica sobre comportamiento social, confianza y vínculo.","beschreibung_en":"La oxitocina es una hormona de nueve aminoácidos producida en el hipotálamo y liberada a través de la glándula pituitaria. Como medicamento, como Syntocinon o Pitocin, está aprobada para inducir el parto y controlar la hemorragia posparto. La oxitocina administrada intranasalmente por separado se estudia en investigación básica sobre comportamiento social, confianza y vínculo.","mechanismus":"La oxitocina se une al receptor de oxitocina (OXTR), un receptor acoplado a proteína Gq/11 en el músculo liso uterino y en varias regiones cerebrales. La unión del receptor activa la fosfolipasa C y, a través de ella, la liberación de calcio intracelular, lo que impulsa la contracción del músculo liso uterino. A concentraciones más altas, la oxitocina también actúa sobre el receptor vasopresina V2 estructuralmente relacionado, produciendo un efecto antidiurético.","mechanismus_en":"La oxitocina se une al receptor de oxitocina (OXTR), un receptor acoplado a proteína Gq/11 en el músculo liso uterino y en varias regiones cerebrales. La unión del receptor activa la fosfolipasa C y, a través de ella, la liberación de calcio intracelular, lo que impulsa la contracción del músculo liso uterino. A concentraciones más altas, la oxitocina también actúa sobre el receptor vasopresina V2 estructuralmente relacionado, produciendo un efecto antidiurético.","evidenz":[{"art":"preclínico","kurz":"En un modelo animal de topillo de la pradera, la administración central de oxitocina indujo preferencia por la pareja en las hembras, mientras que un antagonista selectivo de la oxitocina bloqueó su formación después de la cópula.","kurz_en":"En un modelo animal de topillo de la pradera, la administración central de oxitocina indujo preferencia por la pareja en las hembras, mientras que un antagonista selectivo de la oxitocina bloqueó su formación después de la cópula.","quelle":"Insel TR & Hulihan TJ 1995, Behavioral Neuroscience, 109:782-789"},{"art":"clínico","kurz":"En un estudio conductual controlado con placebo en participantes masculinos sanos, la oxitocina administrada intranasalmente aumentó la disposición a confiar dinero a un extraño en un juego de confianza, sin alterar la toma de riesgos general.","kurz_en":"En un estudio conductual controlado con placebo en participantes masculinos sanos, la oxitocina administrada intranasalmente aumentó la disposición a confiar dinero a un extraño en un juego de confianza, sin alterar la toma de riesgos general.","quelle":"Kosfeld M, Heinrichs M, Zak PJ, Fischbacher U, Fehr E 2005, Nature, PMID 15931222"},{"art":"clínico","kurz":"En un ensayo aleatorizado, controlado con placebo en 106 adultos con trastorno del espectro autista, seis semanas de oxitocina intranasal no mostraron una mejoría estadísticamente significativa en los síntomas sociales centrales en comparación con el placebo.","kurz_en":"En un ensayo aleatorizado, controlado con placebo en 106 adultos con trastorno del espectro autista, seis semanas de oxitocina intranasal no mostraron una mejoría estadísticamente significativa en los síntomas sociales centrales en comparación con el placebo.","quelle":"Yamasue H et al. 2020, Molecular Psychiatry, PMID 29955161"},{"art":"preclínico","kurz":"Una revisión de receptor-farmacología describe el acoplamiento del receptor de oxitocina a las vías de señalización mediadas por la proteína Gq/11 como fosfolipasa C y proteína quinasa C en modelos celulares y animales.","kurz_en":"Una revisión de receptor-farmacología describe el acoplamiento del receptor de oxitocina a las vías de señalización mediadas por la proteína Gq/11 como fosfolipasa C y proteína quinasa C en modelos celulares y animales.","quelle":"Jurek B & Neumann ID 2018, Physiological Reviews, PMID 29897293"}],"sicherheit":["Con administración intravenosa combinada con grandes volúmenes de líquido libre de electrolitos, se documenta la intoxicación por agua con hiponatremia, impulsada por el efecto antidiurético de la oxitocina vinculado a su similitud estructural con la vasopresina.","Un estudio ampliamente citado sobre los efectos que mejoran la confianza de la oxitocina intranasal no pudo ser confirmado en un estudio de replicación posterior bajo condiciones experimentales idénticas.","En el ensayo aleatorizado más grande de oxitocina intranasal en trastorno del espectro autista hasta la fecha, no se observó un efecto significativo en los síntomas centrales.","Para usos fuera de la indicación obstétrica aprobada, no hay datos de seguridad a largo plazo sólidos disponibles."],"sicherheit_en":["Con administración intravenosa combinada con grandes volúmenes de líquido libre de electrolitos, se documenta la intoxicación por agua con hiponatremia, impulsada por el efecto antidiurético de la oxitocina vinculado a su similitud estructural con la vasopresina.","Un estudio ampliamente citado sobre los efectos que mejoran la confianza de la oxitocina intranasal no pudo ser confirmado en un estudio de replicación posterior bajo condiciones experimentales idénticas.","En el ensayo aleatorizado más grande de oxitocina intranasal en trastorno del espectro autista hasta la fecha, no se observó un efecto significativo en los síntomas centrales.","Para usos fuera de la indicación obstétrica aprobada, no hay datos de seguridad a largo plazo sólidos disponibles."],"hinweise":["Solo con fines de investigación, no apto para uso en humanos","Un certificado de análisis no establece idoneidad médica"],"hinweise_en":["Solo con fines de investigación, no apto para uso en humanos","Un certificado de análisis no establece idoneidad médica"],"rekonstitution":"Las condiciones específicas de cada producto figuran en la documentación original del fabricante. Este portal no ofrece instrucciones de preparación ni de uso en humanos.","rekonstitution_en":"Las condiciones específicas de cada producto figuran en la documentación original del fabricante. Este portal no ofrece instrucciones de preparación ni de uso en humanos.","lagerung":"Las condiciones específicas de cada producto figuran en la documentación original del fabricante. Este portal no ofrece instrucciones de preparación ni de uso en humanos.","lagerung_en":"Las condiciones específicas de cada producto figuran en la documentación original del fabricante. Este portal no ofrece instrucciones de preparación ni de uso en humanos.","rechtsstatus":"La oxitocina está aprobada como medicamento, como Syntocinon o Pitocin, en Alemania, la UE y los Estados Unidos para la inducción del parto y el tratamiento de la hemorragia posparto, y solo se dispensa con receta para ese uso. Para otras preguntas de investigación no aprobadas como el comportamiento social o el vínculo, se vende por separado como un químico de investigación.","rechtsstatus_en":"La oxitocina está aprobada como medicamento, como Syntocinon o Pitocin, en Alemania, la UE y los Estados Unidos para la inducción del parto y el tratamiento de la hemorragia posparto, y solo se dispensa con receta para ese uso. Para otras preguntas de investigación no aprobadas como el comportamiento social o el vínculo, se vende por separado como un químico de investigación.","typischeMg":[],"faq":[{"q":"¿Es la oxitocina un medicamento aprobado o un químico de investigación?","a":"Ambos, dependiendo del uso. Para la inducción del parto y la hemorragia posparto, la oxitocina es un medicamento de prescripción. Para otras preguntas de investigación como el comportamiento social, se vende por separado como un químico de investigación, sin aprobación para ese propósito.","q_en":"¿Es la oxitocina un medicamento aprobado o un químico de investigación?","a_en":"Ambos, dependiendo del uso. Para la inducción del parto y la hemorragia posparto, la oxitocina es un medicamento de prescripción. Para otras preguntas de investigación como el comportamiento social, se vende por separado como un químico de investigación, sin aprobación para ese propósito."},{"q":"¿Para qué se estudia la oxitocina en la investigación del comportamiento social?","a":"Los estudios examinan la oxitocina administrada intranasalmente en relación con la confianza, el vínculo y la percepción social. Los resultados son mixtos, y un estudio temprano ampliamente citado sobre la confianza no pudo ser confirmado en una replicación.","q_en":"¿Para qué se estudia la oxitocina en la investigación del comportamiento social?","a_en":"Los estudios examinan la oxitocina administrada intranasalmente en relación con la confianza, el vínculo y la percepción social. Los resultados son mixtos, y un estudio temprano ampliamente citado sobre la confianza no pudo ser confirmado en una replicación."},{"q":"¿Funciona la oxitocina para el trastorno del espectro autista?","a":"El ensayo aleatorizado más grande en adultos con trastorno del espectro autista hasta la fecha no encontró un efecto significativo de la oxitocina intranasal en los síntomas sociales centrales en comparación con el placebo.","q_en":"¿Funciona la oxitocina para el trastorno del espectro autista?","a_en":"El ensayo aleatorizado más grande en adultos con trastorno del espectro autista hasta la fecha no encontró un efecto significativo de la oxitocina intranasal en los síntomas sociales centrales en comparación con el placebo."}],"seo":{"title":"Oxitocina: Hormona, Medicamento y Péptido de Investigación","title_en":"Oxitocina: Hormona, Medicamento y Péptido de Investigación","description":"Oxitocina explicada de forma fáctica: indicación aprobada, mecanismo de acción, investigación sobre el comportamiento social y estado legal como químico de investigación.","description_en":"Oxitocina explicada de forma fáctica: indicación aprobada, mecanismo de acción, investigación sobre el comportamiento social y estado legal como químico de investigación."},"demo":false,"steckbrief":{"cas":"50-56-6","molekulargewicht":"1007.2 g/mol","aminosaeuren":9,"halbwertszeit":"≈ 1 a 6 minutos (vida media plasmática, información de prescripción de Pitocin)","reinheitsstandard":"≥ 98 % (HPLC, estándar comercial)","loeslichkeit":null,"sequenzLaenge":9,"quellen":["PubChem CID 439302","DailyMed SPL PITOCIN (Oxytocin), Par Health USA","chemverify Katalog 14.09.2026"],"halbwertszeit_en":"≈ 1 a 6 minutos (vida media plasmática, información de prescripción de Pitocin)","reinheitsstandard_en":"≥ 98 % (HPLC, estándar comercial)"},"verwandt":["kisspeptin","pt-141","dsip"]},{"slug":"pt-141","name":"PT-141 (bremelanotida)","synonyme":["Bremelanotida","Vyleesi"],"kategorie":"Sonstige","studienlage":"zugelassenes Arzneimittel","kurz":"Un heptapéptido sintético y agonista del receptor de melanocortina, aprobado en EE. UU. bajo el nombre Vyleesi para una forma específica de bajo deseo sexual en mujeres.","kurz_en":"Un heptapéptido sintético y agonista del receptor de melanocortina, aprobado en EE. UU. bajo el nombre Vyleesi para una forma específica de bajo deseo sexual en mujeres.","beschreibung":"PT-141 (bremelanotida) es un péptido de siete aminoácidos desarrollado en Palatin Technologies como compuesto de seguimiento a melanotan II. A diferencia de melanotan II, que fue estudiado principalmente por la pigmentación de la piel, la investigación sobre bremelanotida se centró en la regulación central del deseo sexual. Desde 2019, el compuesto ha sido aprobado en EE. UU. bajo el nombre Vyleesi para la indicación de trastorno de deseo sexual hipoactivo (HSDD) en mujeres premenopáusicas.","beschreibung_en":"PT-141 (bremelanotida) es un péptido de siete aminoácidos desarrollado en Palatin Technologies como compuesto de seguimiento a melanotan II. A diferencia de melanotan II, que fue estudiado principalmente por la pigmentación de la piel, la investigación sobre bremelanotida se centró en la regulación central del deseo sexual. Desde 2019, el compuesto ha sido aprobado en EE. UU. bajo el nombre Vyleesi para la indicación de trastorno de deseo sexual hipoactivo (HSDD) en mujeres premenopáusicas.","mechanismus":"Bremelanotida actúa como agonista en los receptores de melanocortina, principalmente el subtipo MC4R concentrado en el área preóptica medial del hipotálamo. La investigación preclínica describe la liberación de dopamina desencadenada a través de este receptor en regiones cerebrales involucradas en la excitación sexual. El sitio de acción es, por lo tanto, central, en el cerebro, en lugar de vascular como con los inhibidores de PDE5. Según la etiqueta de la FDA, el mecanismo preciso detrás de la mejora de los síntomas del HSDD no se ha establecido completamente.","mechanismus_en":"Bremelanotida actúa como agonista en los receptores de melanocortina, principalmente el subtipo MC4R concentrado en el área preóptica medial del hipotálamo. La investigación preclínica describe la liberación de dopamina desencadenada a través de este receptor en regiones cerebrales involucradas en la excitación sexual. El sitio de acción es, por lo tanto, central, en el cerebro, en lugar de vascular como con los inhibidores de PDE5. Según la etiqueta de la FDA, el mecanismo preciso detrás de la mejora de los síntomas del HSDD no se ha establecido completamente.","evidenz":[{"art":"preclínico","kurz":"Estudios en ratas hembras mostraron un aumento del comportamiento de solicitud sexual después de la administración de bremelanotida, mediado por la liberación de dopamina tras la activación de los receptores MC4 en el área preóptica medial del hipotálamo.","kurz_en":"Estudios en ratas hembras mostraron un aumento del comportamiento de solicitud sexual después de la administración de bremelanotida, mediado por la liberación de dopamina tras la activación de los receptores MC4 en el área preóptica medial del hipotálamo.","quelle":"Pfaus JG et al. 2007, The Journal of Sexual Medicine, PMID 17958619"},{"art":"clínico","kurz":"En dos ensayos aleatorizados controlados con placebo de fase 3 (RECONNECT) en mujeres premenopáusicas con HSDD, bremelanotida mejoró el deseo sexual y la angustia relacionada más que el placebo.","kurz_en":"En dos ensayos aleatorizados controlados con placebo de fase 3 (RECONNECT) en mujeres premenopáusicas con HSDD, bremelanotida mejoró el deseo sexual y la angustia relacionada más que el placebo.","quelle":"Kingsberg SA, Clayton AH, Portman D et al. 2019, Obstetrics & Gynecology, PMID 31599840"},{"art":"clínico","kurz":"Un análisis agrupado de 43 estudios clínicos con aproximadamente 3.500 participantes documentó náuseas, rubor, dolor de cabeza y aumentos transitorios de la presión arterial como los efectos adversos más comunes de bremelanotida.","kurz_en":"Un análisis agrupado de 43 estudios clínicos con aproximadamente 3.500 participantes documentó náuseas, rubor, dolor de cabeza y aumentos transitorios de la presión arterial como los efectos adversos más comunes de bremelanotida.","quelle":"Clayton AH et al. 2022, Journal of Women's Health, PMID 35147466"}],"sicherheit":["En ensayos clínicos, la náusea ocurrió en aproximadamente el 40 por ciento de los participantes en bremelanotida, en comparación con aproximadamente el 1 por ciento en placebo.","Se observó un aumento transitorio de la presión arterial y una caída de la frecuencia cardíaca después de cada administración, resolviéndose en aproximadamente 12 horas según la etiqueta de la FDA.","Según la etiqueta de la FDA, Vyleesi está contraindicado en hipertensión no controlada o enfermedad cardiovascular conocida.","En los ensayos RECONNECT, se observó hiperpigmentación cutánea focal en aproximadamente el 1 por ciento de los participantes."],"sicherheit_en":["En ensayos clínicos, la náusea ocurrió en aproximadamente el 40 por ciento de los participantes en bremelanotida, en comparación con aproximadamente el 1 por ciento en placebo.","Se observó un aumento transitorio de la presión arterial y una caída de la frecuencia cardíaca después de cada administración, resolviéndose en aproximadamente 12 horas según la etiqueta de la FDA.","Según la etiqueta de la FDA, Vyleesi está contraindicado en hipertensión no controlada o enfermedad cardiovascular conocida.","En los ensayos RECONNECT, se observó hiperpigmentación cutánea focal en aproximadamente el 1 por ciento de los participantes."],"hinweise":["Solo con fines de investigación, no apto para uso en humanos","Un certificado de análisis no establece idoneidad médica"],"hinweise_en":["Solo con fines de investigación, no apto para uso en humanos","Un certificado de análisis no establece idoneidad médica"],"rekonstitution":"Las condiciones específicas de cada producto figuran en la documentación original del fabricante. Este portal no ofrece instrucciones de preparación ni de uso en humanos.","rekonstitution_en":"Las condiciones específicas de cada producto figuran en la documentación original del fabricante. Este portal no ofrece instrucciones de preparación ni de uso en humanos.","lagerung":"Las condiciones específicas de cada producto figuran en la documentación original del fabricante. Este portal no ofrece instrucciones de preparación ni de uso en humanos.","lagerung_en":"Las condiciones específicas de cada producto figuran en la documentación original del fabricante. Este portal no ofrece instrucciones de preparación ni de uso en humanos.","rechtsstatus":"Bremelanotida ha sido aprobada por la FDA como Vyleesi desde 2019 para la indicación de HSDD en mujeres premenopáusicas. En Alemania y la UE, no existe aprobación de medicamento, y la sustancia se vende allí exclusivamente como un químico de investigación.","rechtsstatus_en":"Bremelanotida ha sido aprobada por la FDA como Vyleesi desde 2019 para la indicación de HSDD en mujeres premenopáusicas. En Alemania y la UE, no existe aprobación de medicamento, y la sustancia se vende allí exclusivamente como un químico de investigación.","typischeMg":[10,20],"faq":[{"q":"¿Es PT-141 lo mismo que melanotan II?","a":"No. Ambos se remontan a estructuras relacionadas de melanocortina, pero PT-141 (bremelanotida) se estudió específicamente para el deseo sexual, mientras que melanotan II se investigó principalmente para la pigmentación de la piel. Solo bremelanotida alcanzó la aprobación de mercado en EE. UU., como Vyleesi.","q_en":"¿Es PT-141 lo mismo que melanotan II?","a_en":"No. Ambos se remontan a estructuras relacionadas de melanocortina, pero PT-141 (bremelanotida) se estudió específicamente para el deseo sexual, mientras que melanotan II se investigó principalmente para la pigmentación de la piel. Solo bremelanotida alcanzó la aprobación de mercado en EE. UU., como Vyleesi."},{"q":"¿Es bremelanotida un medicamento aprobado?","a":"En EE. UU., sí: desde 2019 bremelanotida ha sido aprobada bajo el nombre Vyleesi para la indicación de HSDD en mujeres premenopáusicas. En Alemania y la UE, no existe aprobación de medicamento, y la sustancia se clasifica como un químico de investigación allí.","q_en":"¿Es bremelanotida un medicamento aprobado?","a_en":"En EE. UU., sí: desde 2019 bremelanotida ha sido aprobada bajo el nombre Vyleesi para la indicación de HSDD en mujeres premenopáusicas. En Alemania y la UE, no existe aprobación de medicamento, y la sustancia se clasifica como un químico de investigación allí."},{"q":"¿Qué efectos secundarios se observaron en estudios?","a":"Los efectos documentados con más frecuencia fueron náuseas, rubor, dolor de cabeza y aumentos transitorios de la presión arterial después de la administración. Según la etiqueta de la FDA, la sustancia está contraindicada en hipertensión no controlada o enfermedad cardiovascular conocida.","q_en":"¿Qué efectos secundarios se observaron en estudios?","a_en":"Los efectos documentados con más frecuencia fueron náuseas, rubor, dolor de cabeza y aumentos transitorios de la presión arterial después de la administración. Según la etiqueta de la FDA, la sustancia está contraindicada en hipertensión no controlada o enfermedad cardiovascular conocida."}],"seo":{"title":"Resumen de investigación sobre PT-141 (bremelanotida)","title_en":"Resumen de investigación sobre PT-141 (bremelanotida)","description":"PT-141 (bremelanotida): mecanismo, datos de estudio, perfil de seguridad y estado de aprobación de este agonista del receptor de melanocortina en un vistazo.","description_en":"PT-141 (bremelanotida): mecanismo, datos de estudio, perfil de seguridad y estado de aprobación de este agonista del receptor de melanocortina en un vistazo."},"demo":false,"steckbrief":{"cas":"189691-06-3","molekulargewicht":"1025.2 g/mol","aminosaeuren":7,"halbwertszeit":"≈ 2,7 horas (vida media terminal, información de prescripción de Vyleesi)","reinheitsstandard":"≥ 99 % (HPLC, estándar comercial)","loeslichkeit":null,"sequenzLaenge":7,"quellen":["PubChem CID 9941379","DailyMed SPL VYLEESI (Bremelanotid), Cosette Pharmaceuticals","chemverify Katalog 14.09.2026"],"halbwertszeit_en":"≈ 2,7 horas (vida media terminal, información de prescripción de Vyleesi)","reinheitsstandard_en":"≥ 99 % (HPLC, estándar comercial)"},"verwandt":["melanotan-2","kisspeptin","kpv"]},{"slug":"ss-31","name":"SS-31 (elamipretida)","synonyme":["Elamipretida","MTP-131","Bendavia"],"kategorie":"Sonstige","studienlage":"klinisch untersucht","kurz":"Un tetrapeptido dirigido a mitocondrias estudiado en varios ensayos clínicos para insuficiencia cardíaca y enfermedad mitocondrial, aún no aprobado.","kurz_en":"Un tetrapeptido dirigido a mitocondrias estudiado en varios ensayos clínicos para insuficiencia cardíaca y enfermedad mitocondrial, aún no aprobado.","beschreibung":"SS-31, también conocido bajo el nombre genérico elamipretida como MTP-131 o Bendavia, es un tetrapeptido sintético que se une específicamente a la cardiolina, un lípido en la membrana mitocondrial. Se ha estudiado en varios ensayos clínicos de fase 1 a fase 3 para insuficiencia cardíaca, miopatía mitocondrial primaria y síndrome de Barth. A pesar de una base de datos clínica comparativamente amplia, ninguno de estos estudios ha llevado a la aprobación como medicamento.","beschreibung_en":"SS-31, también conocido bajo el nombre genérico elamipretida como MTP-131 o Bendavia, es un tetrapeptido sintético que se une específicamente a la cardiolina, un lípido en la membrana mitocondrial. Se ha estudiado en varios ensayos clínicos de fase 1 a fase 3 para insuficiencia cardíaca, miopatía mitocondrial primaria y síndrome de Barth. A pesar de una base de datos clínica comparativamente amplia, ninguno de estos estudios ha llevado a la aprobación como medicamento.","mechanismus":"SS-31 se une con alta afinidad a la cardiolina en la membrana mitocondrial interna, un lípido requerido para la estructura de las crestas. Se describe como reduciendo las especies reactivas de oxígeno y estabilizando la estructura de la membrana mitocondrial. En modelos preclínicos, esto se relacionó con la protección contra la lesión por isquemia-reperfusión, por ejemplo en el músculo cardíaco.","mechanismus_en":"SS-31 se une con alta afinidad a la cardiolina en la membrana mitocondrial interna, un lípido requerido para la estructura de las crestas. Se describe como reduciendo las especies reactivas de oxígeno y estabilizando la estructura de la membrana mitocondrial. En modelos preclínicos, esto se relacionó con la protección contra la lesión por isquemia-reperfusión, por ejemplo en el músculo cardíaco.","evidenz":[{"art":"clínico","kurz":"Un ensayo aleatorizado, controlado con placebo de fase 3 en personas con miopatía mitocondrial primaria no cumplió con sus objetivos primarios predefinidos ni en la prueba de caminata de 6 minutos ni en la puntuación de fatiga, aunque se describió que el fármaco del estudio fue bien tolerado.","kurz_en":"Un ensayo aleatorizado, controlado con placebo de fase 3 en personas con miopatía mitocondrial primaria no cumplió con sus objetivos primarios predefinidos ni en la prueba de caminata de 6 minutos ni en la puntuación de fatiga, aunque se describió que el fármaco del estudio fue bien tolerado.","quelle":"Karaa et al. 2023, Neurology, PMID 37268435"},{"art":"clínico","kurz":"Un ensayo de fase 1 controlado con placebo con aumentos escalonados de cantidades de infusión en personas con insuficiencia cardíaca y fracción de eyección reducida describió una única infusión de elamipretida como segura y bien tolerada.","kurz_en":"Un ensayo de fase 1 controlado con placebo con aumentos escalonados de cantidades de infusión en personas con insuficiencia cardíaca y fracción de eyección reducida describió una única infusión de elamipretida como segura y bien tolerada.","quelle":"Daubert et al. 2017, Circulation: Heart Failure, PMID 29217757"},{"art":"preclínico","kurz":"Un estudio en ratas con lesión por isquemia-repercusión cardíaca describió un área de infarto significativamente menor cuando se administró SS-31 de antemano en comparación con los animales de control.","kurz_en":"Un estudio en ratas con lesión por isquemia-repercusión cardíaca describió un área de infarto significativamente menor cuando se administró SS-31 de antemano en comparación con los animales de control.","quelle":"Cho et al. 2007, Coronary Artery Disease, PMID 17429296"}],"sicherheit":["En ensayos clínicos hasta la fecha, la elamipretida ha sido descrita en su mayoría como segura y bien tolerada, con eventos adversos predominantemente leves a moderados.","Varios ensayos, incluidos en miopatía mitocondrial y síndrome de Barth, no cumplieron con sus objetivos primarios de eficacia, por lo que una solicitud de aprobación de EE. UU. no fue aceptada para revisión por la agencia en 2021.","No hay datos a largo plazo fuera de programas de estudio controlados.","Los productos de fabricación no controlada conllevan un riesgo de contaminación que es independiente de la molécula misma."],"sicherheit_en":["En ensayos clínicos hasta la fecha, la elamipretida ha sido descrita en su mayoría como segura y bien tolerada, con eventos adversos predominantemente leves a moderados.","Varios ensayos, incluidos en miopatía mitocondrial y síndrome de Barth, no cumplieron con sus objetivos primarios de eficacia, por lo que una solicitud de aprobación de EE. UU. no fue aceptada para revisión por la agencia en 2021.","No hay datos a largo plazo fuera de programas de estudio controlados.","Los productos de fabricación no controlada conllevan un riesgo de contaminación que es independiente de la molécula misma."],"hinweise":["Solo con fines de investigación, no apto para uso en humanos","Un certificado de análisis no establece idoneidad médica"],"hinweise_en":["Solo con fines de investigación, no apto para uso en humanos","Un certificado de análisis no establece idoneidad médica"],"rekonstitution":"Las condiciones específicas de cada producto figuran en la documentación original del fabricante. Este portal no ofrece instrucciones de preparación ni de uso en humanos.","rekonstitution_en":"Las condiciones específicas de cada producto figuran en la documentación original del fabricante. Este portal no ofrece instrucciones de preparación ni de uso en humanos.","lagerung":"Las condiciones específicas de cada producto figuran en la documentación original del fabricante. Este portal no ofrece instrucciones de preparación ni de uso en humanos.","lagerung_en":"Las condiciones específicas de cada producto figuran en la documentación original del fabricante. Este portal no ofrece instrucciones de preparación ni de uso en humanos.","rechtsstatus":"SS-31 (elamipretida) no está aprobada como medicamento en Alemania, la UE o Estados Unidos. Una solicitud de aprobación de EE. UU. de 2021 no fue aceptada para revisión debido a la falta de un único estudio de eficacia adecuado y controlado. Se vende exclusivamente como producto químico de investigación.","rechtsstatus_en":"SS-31 (elamipretida) no está aprobada como medicamento en Alemania, la UE o Estados Unidos. Una solicitud de aprobación de EE. UU. de 2021 no fue aceptada para revisión debido a la falta de un único estudio de eficacia adecuado y controlado. Se vende exclusivamente como producto químico de investigación.","typischeMg":[],"faq":[{"q":"¿Es la elamipretida un medicamento aprobado?","a":"No. A pesar de varios ensayos clínicos en insuficiencia cardíaca, miopatía mitocondrial y síndrome de Barth, no se ha concedido ninguna aprobación, una solicitud de aprobación de EE. UU. no fue aceptada para revisión en 2021.","q_en":"¿Es la elamipretida un medicamento aprobado?","a_en":"No. A pesar de varios ensayos clínicos en insuficiencia cardíaca, miopatía mitocondrial y síndrome de Barth, no se ha concedido ninguna aprobación, una solicitud de aprobación de EE. UU. no fue aceptada para revisión en 2021."},{"q":"¿Sobre qué actúa SS-31 en el cuerpo?","a":"Se une a la cardiolina en la membrana mitocondrial interna y se asocia con la reducción de especies reactivas de oxígeno y la estabilización de la estructura de la membrana.","q_en":"¿Sobre qué actúa SS-31 en el cuerpo?","a_en":"Se une a la cardiolina en la membrana mitocondrial interna y se asocia con la reducción de especies reactivas de oxígeno y la estabilización de la estructura de la membrana."},{"q":"¿Los ensayos clínicos cumplieron sus objetivos?","a":"Varios ensayos no cumplieron con sus objetivos primarios predefinidos, por ejemplo en miopatía mitocondrial y síndrome de Barth, mientras que la tolerabilidad se describió consistentemente como buena.","q_en":"¿Los ensayos clínicos cumplieron sus objetivos?","a_en":"Varios ensayos no cumplieron con sus objetivos primarios predefinidos, por ejemplo en miopatía mitocondrial y síndrome de Barth, mientras que la tolerabilidad se describió consistentemente como buena."}],"seo":{"title":"SS-31 (Elamipretida): Perfil de Investigación y Evidencia","title_en":"SS-31 (Elamipretida): Perfil de Investigación y Evidencia","description":"Resumen de SS-31/elamipretida: mecanismo mitocondrial, evidencia clínica en insuficiencia cardíaca y miopatía mitocondrial, y perfil de seguridad.","description_en":"Resumen de SS-31/elamipretida: mecanismo mitocondrial, evidencia clínica en insuficiencia cardíaca y miopatía mitocondrial, y perfil de seguridad."},"demo":false,"steckbrief":{"cas":"736992-21-5","molekulargewicht":"639.8 g/mol","aminosaeuren":4,"halbwertszeit":null,"reinheitsstandard":"≥ 98 % (HPLC, estándar comercial)","loeslichkeit":null,"sequenzLaenge":4,"quellen":["PubChem CID 11764719","chemverify Katalog 14.09.2026"],"reinheitsstandard_en":"≥ 98 % (HPLC, estándar comercial)"},"verwandt":["mots-c","epitalon","dihexa"]}];
